import { render, screen } from '@testing-library/react';
import TasksPage from '@/app/(shell)/tasks/page';
import { AuthContext } from '@/contexts/AuthContextProvider';

// Mock Next.js Link component
jest.mock('next/link', () => {
    return ({ children, href }: any) => {
        return <a href={href}>{children}</a>;
    };
});

// Mock Next.js navigation
jest.mock('next/navigation', () => ({
    useRouter: () => ({
        push: jest.fn(),
        replace: jest.fn(),
        prefetch: jest.fn(),
    }),
    useSearchParams: () => ({
        get: jest.fn(),
    }),
    usePathname: () => '/tasks',
}));

// Mock lucide-react icons using Proxy to dynamically support all icons
jest.mock('lucide-react', () => {
    return new Proxy({}, {
        get: (target, name) => {
            return (props: any) => <span data-testid={String(name)}>{String(name)} Icon</span>;
        }
    });
});

// Mock useWorkspace dynamically based on useAuth
jest.mock('@/system/workspace/WorkspaceProvider', () => {
    return {
        useWorkspace: () => {
            const { useAuth } = require('@/contexts/AuthContextProvider');
            const { user } = useAuth();
            return {
                currentWorkspaceId: 'test-workspace',
                currentRole: user?.role || 'member'
            };
        }
    };
});

// Mock react-query useQueryClient hook
jest.mock('@tanstack/react-query', () => {
    const original = jest.requireActual('@tanstack/react-query');
    return {
        ...original,
        useQueryClient: () => ({
            getQueryData: jest.fn(),
            setQueryData: jest.fn(),
            invalidateQueries: jest.fn(),
            cancelQueries: jest.fn(),
        }),
    };
});

// Mock TaskKanbanView, TaskListView, TaskConfidenceView
jest.mock('@/components/tasks/TaskKanbanView', () => ({
    TaskKanbanView: () => <div data-testid="kanban-view">Kanban View</div>
}));

jest.mock('@/components/tasks/TaskListView', () => ({
    TaskListView: () => <div data-testid="list-view">List View</div>
}));

jest.mock('@/components/tasks/TaskConfidenceView', () => ({
    TaskConfidenceView: () => <div data-testid="confidence-view">Confidence View</div>
}));

describe('TasksPage - New Task Button Visibility', () => {
    const mockAdminUser = {
        uid: 'admin-123',
        email: 'admin@test.com',
        role: 'admin',
        name: 'Admin User'
    };

    const mockMemberUser = {
        uid: 'member-123',
        email: 'member@test.com',
        role: 'member',
        name: 'Member User'
    };

    const renderWithAuth = (user: any) => {
        return render(
            <AuthContext.Provider value={{ user, loading: false, logout: jest.fn() }}>
                <TasksPage />
            </AuthContext.Provider>
        );
    };

    /**
     * REAL USER RISK: Admin users must be able to create tasks
     * If this button is hidden, admins cannot perform their core workflow
     */
    test('Admin: New Task button is visible', async () => {
        renderWithAuth(mockAdminUser);

        // Wait for component to render
        await screen.findAllByText('Tasks');

        // Verify "New Task" button exists and is accessible
        const newTaskButton = screen.getByLabelText('New Task');
        expect(newTaskButton).toBeInTheDocument();
        expect(newTaskButton).toBeVisible();
    });

    /**
     * REAL USER RISK: Members should also see the New Task button
     * (Based on current implementation - button is NOT role-gated)
     * If this changes, update test accordingly
     */
    test('Member: New Task button is visible', async () => {
        renderWithAuth(mockMemberUser);

        await screen.findAllByText('Tasks');

        const newTaskButton = screen.getByLabelText('New Task');
        expect(newTaskButton).toBeInTheDocument();
        expect(newTaskButton).toBeVisible();
    });

    /**
     * REAL USER RISK: View switcher should only be visible to non-member users
     * Members should not see Kanban/List/Confidence toggle
     */
    test('Admin: View switcher is visible', async () => {
        renderWithAuth(mockAdminUser);

        await screen.findAllByText('Tasks');

        // Admin should see view mode buttons
        const kanbanButton = screen.getByTitle('Kanban Board');
        const listButton = screen.getByTitle('List View');

        expect(kanbanButton).toBeInTheDocument();
        expect(listButton).toBeInTheDocument();
    });

    /**
     * REAL USER RISK: Members should not see view switcher
     * This prevents confusion and enforces simplified member UX
     */
    test('Member: View switcher is hidden', async () => {
        renderWithAuth(mockMemberUser);

        await screen.findAllByText('Tasks');

        // Member should NOT see view mode buttons
        const kanbanButton = screen.queryByTitle('Kanban Board');
        const listButton = screen.queryByTitle('List View');

        expect(kanbanButton).not.toBeInTheDocument();
        expect(listButton).not.toBeInTheDocument();
    });

    /**
     * REAL USER RISK: Admin Confidence Panel should only be visible to admins
     * Exposing this to non-admins could leak sensitive information
     */
    test('Admin: Confidence view button is visible', async () => {
        renderWithAuth(mockAdminUser);

        await screen.findAllByText('Tasks');

        const confidenceButton = screen.getByTitle('Admin Confidence Panel');
        expect(confidenceButton).toBeInTheDocument();
    });

    /**
     * REAL USER RISK: Non-admins should not see Admin Confidence Panel
     */
    test('Member: Confidence view button is hidden', async () => {
        renderWithAuth(mockMemberUser);

        await screen.findAllByText('Tasks');

        const confidenceButton = screen.queryByTitle('Admin Confidence Panel');
        expect(confidenceButton).not.toBeInTheDocument();
    });

    /**
     * REAL USER RISK: Page should handle missing user gracefully
     * Prevents crashes during auth loading states
     */
    test('No user: Page renders without crashing', () => {
        render(
            <AuthContext.Provider value={{ user: null, loading: false, logout: jest.fn() }}>
                <TasksPage />
            </AuthContext.Provider>
        );

        // Should render header even without user
        expect(screen.getAllByText('Tasks')[0]).toBeInTheDocument();
    });
});

'use client';



import React, { useState, useEffect } from 'react';
import { InstitutionAssistant } from '@/components/AI/InstitutionAssistant';
import { getProductionPipelineStats } from '@/services/statsService';
import { apiClient } from '@/lib/apiClient';
import { DropdownSelector } from '@/components/ui/selectors/DropdownSelector';

interface DashboardData {
  taskWorkload: any[];
  tatMetrics: any;
  slaCompliance: any;
  eventFrequency: any[];
  mediaOutput: any[];
  teamActivity: any[];
  productionPipeline: any;
  performanceAnomalies: any[];
}

// Helper function to get date ranges
const getDateRange = (period: string) => {
  const now = new Date();
  let startDate = new Date();

  switch (period) {
    case 'day':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
      break;
    case 'week':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
      break;
    case 'month':
      startDate = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate());
      break;
    case 'quarter':
      startDate = new Date(now.getFullYear(), now.getMonth() - 3, now.getDate());
      break;
    default:
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7);
  }

  return { startDate, endDate: now };
};

// Helper function to get real task workload data
const getTaskWorkloadData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const workloadData = await apiClient(`/api/insights/task-workload?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return workloadData;
  } catch (error) {
    console.error('Error fetching task workload data:', error);
    return [
      { institution: 'TG Antla', workload: 45, trend: 'up' },
      { institution: 'TG Bangkok', workload: 32, trend: 'down' },
      { institution: 'TG Chiang Mai', workload: 28, trend: 'stable' },
    ];
  }
};

// Helper function to get real TAT metrics
const getTatMetricsData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const tatData = await apiClient(`/api/insights/tat-metrics?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return tatData;
  } catch (error) {
    console.error('Error fetching TAT metrics:', error);
    return {
      average: '2.3 days',
      median: '2.1 days',
      trend: 'improving'
    };
  }
};

// Helper function to get real SLA compliance data
const getSlaComplianceData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const slaData = await apiClient(`/api/insights/sla-compliance?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return slaData;
  } catch (error) {
    console.error('Error fetching SLA compliance data:', error);
    return {
      compliant: 87,
      nonCompliant: 13,
      trend: 'stable'
    };
  }
};

// Helper function to get real event frequency data
const getEventFrequencyData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const eventData = await apiClient(`/api/insights/event-frequency?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return eventData;
  } catch (error) {
    console.error('Error fetching event frequency data:', error);
    return [
      { day: 'Mon', count: 12 },
      { day: 'Tue', count: 8 },
      { day: 'Wed', count: 15 },
      { day: 'Thu', count: 10 },
      { day: 'Fri', count: 7 },
      { day: 'Sat', count: 20 },
      { day: 'Sun', count: 18 },
    ];
  }
};

// Helper function to get real media output data
const getMediaOutputData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const mediaData = await apiClient(`/api/insights/media-output?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return mediaData;
  } catch (error) {
    console.error('Error fetching media output data:', error);
    return [
      { month: 'Jan', count: 45 },
      { month: 'Feb', count: 52 },
      { month: 'Mar', count: 48 },
      { month: 'Apr', count: 61 },
      { month: 'May', count: 55 },
      { month: 'Jun', count: 67 },
    ];
  }
};

// Helper function to get real team activity data
const getTeamActivityData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const teamData = await apiClient(`/api/insights/team-activity?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return teamData;
  } catch (error) {
    console.error('Error fetching team activity data:', error);
    return [
      { team: 'Video Team', activity: 95 },
      { team: 'Editing Team', activity: 87 },
      { team: 'Graphics Team', activity: 78 },
      { team: 'Management', activity: 65 },
    ];
  }
};

// Helper function to get real performance anomalies
const getPerformanceAnomaliesData = async (tenantId: string, period: string) => {
  try {
    const { startDate } = getDateRange(period);

    // Fetch data from API
    const anomalies = await apiClient(`/api/insights/performance-anomalies?tenantId=${tenantId}&period=${period}`, {
      method: 'GET'
    });

    return anomalies;
  } catch (error) {
    console.error('Error fetching performance anomalies:', error);
    return [
      {
        id: 1,
        type: 'spike',
        description: 'Spike in high-priority tasks from TG Antla this week',
        severity: 'high',
        timestamp: new Date().toISOString()
      },
      {
        id: 2,
        type: 'delay',
        description: 'Delayed deliverables from Graphics Team',
        severity: 'medium',
        timestamp: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
      }
    ];
  }
};

export default function InsightsPage() {
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedPeriod, setSelectedPeriod] = useState('week');
  const [selectedTenant, setSelectedTenant] = useState('all');

  // Fetch dashboard data
  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);

        // Fetch all real data in parallel
        const [
          productionPipeline,
          taskWorkload,
          tatMetrics,
          slaCompliance,
          eventFrequency,
          mediaOutput,
          teamActivity,
          performanceAnomalies
        ] = await Promise.all([
          getProductionPipelineStats(),
          getTaskWorkloadData(selectedTenant, selectedPeriod),
          getTatMetricsData(selectedTenant, selectedPeriod),
          getSlaComplianceData(selectedTenant, selectedPeriod),
          getEventFrequencyData(selectedTenant, selectedPeriod),
          getMediaOutputData(selectedTenant, selectedPeriod),
          getTeamActivityData(selectedTenant, selectedPeriod),
          getPerformanceAnomaliesData(selectedTenant, selectedPeriod)
        ]);

        const realData: DashboardData = {
          taskWorkload,
          tatMetrics,
          slaCompliance,
          eventFrequency,
          mediaOutput,
          teamActivity,
          productionPipeline,
          performanceAnomalies
        };

        setDashboardData(realData);
      } catch (error) {
        console.error('Failed to fetch dashboard data:', error);
        // Use mock data as fallback
        const mockData: DashboardData = {
          taskWorkload: [
            { institution: 'TG Antla', workload: 45, trend: 'up' },
            { institution: 'TG Bangkok', workload: 32, trend: 'down' },
            { institution: 'TG Chiang Mai', workload: 28, trend: 'stable' },
          ],
          tatMetrics: {
            average: '2.3 days',
            median: '2.1 days',
            trend: 'improving'
          },
          slaCompliance: {
            compliant: 87,
            nonCompliant: 13,
            trend: 'stable'
          },
          eventFrequency: [
            { day: 'Mon', count: 12 },
            { day: 'Tue', count: 8 },
            { day: 'Wed', count: 15 },
            { day: 'Thu', count: 10 },
            { day: 'Fri', count: 7 },
            { day: 'Sat', count: 20 },
            { day: 'Sun', count: 18 },
          ],
          mediaOutput: [
            { month: 'Jan', count: 45 },
            { month: 'Feb', count: 52 },
            { month: 'Mar', count: 48 },
            { month: 'Apr', count: 61 },
            { month: 'May', count: 55 },
            { month: 'Jun', count: 67 },
          ],
          teamActivity: [
            { team: 'Video Team', activity: 95 },
            { team: 'Editing Team', activity: 87 },
            { team: 'Graphics Team', activity: 78 },
            { team: 'Management', activity: 65 },
          ],
          productionPipeline: {
            inProgress: 24,
            pendingReview: 12,
            completed: 45,
            delayed: 3
          },
          performanceAnomalies: [
            {
              id: 1,
              type: 'spike',
              description: 'Spike in high-priority tasks from TG Antla this week',
              severity: 'high',
              timestamp: new Date().toISOString()
            },
            {
              id: 2,
              type: 'delay',
              description: 'Delayed deliverables from Graphics Team',
              severity: 'medium',
              timestamp: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
            }
          ]
        };

        setDashboardData(mockData);
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, [selectedPeriod, selectedTenant]);

  const exportData = async (format: string) => {
    try {
      const response = await apiClient(`/api/insights/export?format=${format}&period=${selectedPeriod}&tenant=${selectedTenant}`, {
        method: 'GET'
      });

      // Create a temporary link to download the file
      const url = response.url; // Assuming the API returns a download URL
      const a = document.createElement('a');
      a.href = url;
      a.download = `insights-report.${format === 'csv' ? 'csv' : format === 'pdf' ? 'pdf' : 'txt'}`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } catch (error) {
      console.error('Export failed:', error);
      alert(`Failed to export data in ${format} format`);
    }
  };

  const sendEmailSummary = async () => {
    try {
      const response = await apiClient('/api/insights/email-summary', {
        method: 'POST',
        body: JSON.stringify({ period: selectedPeriod, tenant: selectedTenant }),
      });

      if (response.success) {
        alert('Email summary sent successfully');
      } else {
        alert('Failed to send email summary');
      }
    } catch (error) {
      console.error('Failed to send email summary:', error);
      alert('Failed to send email summary');
    }
  };

  if (loading) {
    return <div>Loading dashboard data...</div>;
  }

  if (!dashboardData) {
    return <div>Failed to load dashboard data</div>;
  }

  return (
    <div className="insights-page p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Management Insights</h1>
        <div className="flex items-end space-x-4">
          <div className="space-y-0.5">
            <DropdownSelector 
              label="Campus"
              value={selectedTenant}
              onChange={setSelectedTenant}
              options={[
                { id: 'all', label: 'All Campuses' },
                { id: '1', label: 'TG Antla' },
                { id: '2', label: 'TG Bangkok' },
                { id: '3', label: 'TG Chiang Mai' },
              ]}
            />
          </div>
          <div className="space-y-0.5">
            <DropdownSelector 
              label="Period"
              value={selectedPeriod}
              onChange={setSelectedPeriod}
              options={[
                { id: 'day', label: 'Today' },
                { id: 'week', label: 'This Week' },
                { id: 'month', label: 'This Month' },
                { id: 'quarter', label: 'This Quarter' },
              ]}
            />
          </div>
          <button
            onClick={() => exportData('pdf')}
            className="bg-red-500 hover:bg-red-700 text-foreground px-3 py-2 rounded"
          >
            Export PDF
          </button>
          <button
            onClick={() => exportData('csv')}
            className="bg-green-500 hover:bg-green-700 text-foreground px-3 py-2 rounded"
          >
            Export CSV
          </button>
          <button
            onClick={sendEmailSummary}
            className="bg-blue-500 hover:bg-blue-700 text-foreground px-3 py-2 rounded"
          >
            Email Summary
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 mb-6">
        {/* Task Workload by Institution */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Task Workload by Institution</h2>
          <div className="space-y-2">
            {dashboardData.taskWorkload.map((item, index) => (
              <div key={index} className="flex justify-between items-center">
                <span>{item.institution}</span>
                <span className="flex items-center">
                  {item.workload} tasks
                  <span className={`ml-2 text-xs ${item.trend === 'up' ? 'text-red-500' :
                      item.trend === 'down' ? 'text-green-500' : 'text-foreground/50'
                    }`}>
                    {item.trend === 'up' ? '↑' : item.trend === 'down' ? '↓' : '→'}
                  </span>
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* TAT Metrics */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">TAT Metrics</h2>
          <div className="space-y-2">
            <div className="flex justify-between">
              <span>Average TAT:</span>
              <span className="font-bold">{dashboardData.tatMetrics.average}</span>
            </div>
            <div className="flex justify-between">
              <span>Median TAT:</span>
              <span className="font-bold">{dashboardData.tatMetrics.median}</span>
            </div>
            <div className="flex justify-between">
              <span>Trend:</span>
              <span className={
                dashboardData.tatMetrics.trend === 'improving' ? 'text-green-500' :
                  dashboardData.tatMetrics.trend === 'declining' ? 'text-red-500' : 'text-foreground/50'
              }>
                {dashboardData.tatMetrics.trend}
              </span>
            </div>
          </div>
        </div>

        {/* SLA Compliance */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">SLA Compliance</h2>
          <div className="flex items-center justify-center h-32">
            <div className="relative w-32 h-32">
              <div className="absolute inset-0 rounded-full border-8 border-gray-200"></div>
              <div
                className="absolute inset-0 rounded-full border-8 border-transparent"
                style={{
                  borderTopColor: '#10B981',
                  borderRightColor: '#10B981',
                  transform: `rotate(${dashboardData.slaCompliance.compliant * 3.6}deg)`
                }}
              ></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-xl font-bold">{dashboardData.slaCompliance.compliant}%</span>
              </div>
            </div>
          </div>
          <div className="text-center mt-2">
            <span className="text-sm text-foreground/40">
              {dashboardData.slaCompliance.compliant}% compliant,
              {dashboardData.slaCompliance.nonCompliant}% non-compliant
            </span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 mb-6">
        {/* Event Frequency Heatmap */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Event Frequency (Weekly)</h2>
          <div className="flex justify-between mb-2">
            {dashboardData.eventFrequency.map((day, index) => (
              <div key={index} className="text-center">
                <div className="text-xs text-foreground/50">{day.day}</div>
                <div
                  className="w-8 h-8 rounded flex items-center justify-center text-foreground text-xs font-bold mt-1"
                  style={{
                    backgroundColor: `rgba(59, 130, 246, ${day.count / 25})`
                  }}
                >
                  {day.count}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Media Output */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Media Output (Monthly)</h2>
          <div className="h-48 flex items-end space-x-2">
            {dashboardData.mediaOutput.map((month, index) => (
              <div key={index} className="flex flex-col items-center flex-1">
                <div
                  className="w-full bg-blue-500 rounded-t"
                  style={{ height: `${(month.count / 100) * 100}%` }}
                ></div>
                <div className="text-xs text-foreground/50 mt-1">{month.month}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {/* Team Activity Ranking */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Team Activity Ranking</h2>
          <div className="space-y-3">
            {dashboardData.teamActivity.map((team, index) => (
              <div key={index} className="flex items-center">
                <div className="w-8 h-8 rounded-full bg-blue-500 text-foreground flex items-center justify-center text-sm font-bold mr-3">
                  {index + 1}
                </div>
                <div className="flex-1">
                  <div className="flex justify-between">
                    <span>{team.team}</span>
                    <span>{team.activity}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2 mt-1">
                    <div
                      className="bg-blue-500 h-2 rounded-full"
                      style={{ width: `${team.activity}%` }}
                    ></div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Production Pipeline Summary */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Production Pipeline</h2>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-blue-100 p-3 rounded text-center">
              <div className="text-2xl font-bold">{dashboardData.productionPipeline.inProgress}</div>
              <div className="text-sm">In Progress</div>
            </div>
            <div className="bg-yellow-100 p-3 rounded text-center">
              <div className="text-2xl font-bold">{dashboardData.productionPipeline.pendingReview}</div>
              <div className="text-sm">Pending Review</div>
            </div>
            <div className="bg-green-100 p-3 rounded text-center">
              <div className="text-2xl font-bold">{dashboardData.productionPipeline.completed}</div>
              <div className="text-sm">Completed</div>
            </div>
            <div className="bg-red-100 p-3 rounded text-center">
              <div className="text-2xl font-bold">{dashboardData.productionPipeline.delayed}</div>
              <div className="text-sm">Delayed</div>
            </div>
          </div>

          {/* Performance Anomalies */}
          <div className="mt-4">
            <h3 className="font-bold mb-2">Performance Anomalies</h3>
            <div className="space-y-2">
              {dashboardData.performanceAnomalies.map((anomaly) => (
                <div
                  key={anomaly.id}
                  className={`p-3 rounded ${anomaly.severity === 'high' ? 'bg-red-50 border border-red-200' :
                      anomaly.severity === 'medium' ? 'bg-yellow-50 border border-yellow-200' :
                        'bg-blue-50 border border-blue-200'
                    }`}
                >
                  <div className={`font-bold ${anomaly.severity === 'high' ? 'text-red-800' :
                      anomaly.severity === 'medium' ? 'text-yellow-800' :
                        'text-blue-800'
                    }`}>
                    {anomaly.type.charAt(0).toUpperCase() + anomaly.type.slice(1)}
                  </div>
                  <div className="text-sm">{anomaly.description}</div>
                  <div className="text-xs text-foreground/50 mt-1">
                    {new Date(anomaly.timestamp).toLocaleDateString()}
                  </div>
                </div>
              ))}
              {dashboardData.performanceAnomalies.length === 0 && (
                <div className="text-sm text-foreground/50 italic">
                  No performance anomalies detected
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* AI Assistant */}
      <div className="mt-6">
        <InstitutionAssistant />
      </div>
    </div>
  );
}

"use client";

import React, { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/contexts/AuthContextProvider';
import AdminSidebar from '@/components/admin/AdminSidebar';
import { ShieldAlert } from 'lucide-react';

export default function AdminLayout({ children }: { children: React.ReactNode }) {
    const { user, loading } = useAuth();
    const router = useRouter();

    useEffect(() => {
        // Only redirect if auth is explicitly resolved and user is NOT an authorized role
        if (!loading) {
            const isAuthorized = ['admin', 'manager'].includes(user?.role || '');
            
            console.log('[AdminLayout] Security Audit:', { 
                authorized: isAuthorized,
                role: user?.role, 
                path: window.location.pathname 
            });
            
            if (!isAuthorized) {
                // Wait a tiny bit to avoid flickers on refresh
                const timer = setTimeout(() => {
                    console.warn('[AdminLayout] Unauthorized access attempt. Redirecting...');
                    router.replace('/home');
                }, 1500);
                return () => clearTimeout(timer);
            }
        }
    }, [user, loading, router]);

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-screen bg-[var(--bg)]">
                <div className="flex flex-col items-center gap-4">
                    <div className="w-12 h-12 border-4 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin" />
                    <p className="text-sm font-medium text-foreground/80 animate-pulse">Verifying Credentials...</p>
                </div>
            </div>
        );
    }

    if (!user || !['admin', 'manager'].includes(user.role)) {
        return (
            <div className="flex items-center justify-center min-h-screen bg-[var(--bg)] px-6">
                <div className="max-w-md w-full glass-liquid p-8 rounded-[32px] border-foreground/5 text-center space-y-6">
                    <div className="w-16 h-16 bg-red-500/10 rounded-2xl flex items-center justify-center text-red-400 mx-auto">
                        <ShieldAlert size={32} />
                    </div>
                    <div>
                        <h1 className="text-xl font-bold text-foreground mb-2">Access Restricted</h1>
                        <p className="text-sm text-foreground/80 leading-relaxed">
                            You don't have the required privileges to view this section. 
                            If you believe this is an error, please contact your system administrator.
                        </p>
                    </div>
                    <button 
                        onClick={() => router.push('/home')}
                        className="w-full py-3 px-4 bg-foreground/5 hover:bg-foreground/10 rounded-xl text-sm font-bold text-foreground transition-all border border-foreground/5"
                    >
                        Return to Safety
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="admin-context-wrapper">
            {/* Global Admin Sidebar - Only visible in this layout */}
            <AdminSidebar />
            
            <style jsx global>{`
                /* Adjust main padding for admin sidebar */
                main#main-scroll-container {
                    padding-left: var(--admin-sidebar-width, 240px) !important;
                }
                
                @media (max-width: 1024px) {
                    main#main-scroll-container {
                        padding-left: 0 !important;
                    }
                }
            `}</style>

            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                {children}
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/contexts/AuthContextProvider';
import { useRouter } from 'next/navigation';
import { supabase } from '@/lib/supabaseClient';
import { LeaveBalanceService } from '@/services/leaveBalanceService';
import { UserService } from '@/services/userService';
import { LeaveAnalytics } from '@/components/leave/LeaveAnalytics';
import { 
    Loader2, 
    Download, 
    Calendar, 
    ShieldAlert, 
    LayoutDashboard, 
    Users, 
    ClipboardCheck, 
    Settings2,
    Search,
    Filter,
    MoreHorizontal,
    CheckCircle2,
    XCircle
} from 'lucide-react';
import { toast } from 'sonner';
import { apiGet, apiPost } from '@/lib/apiClient';
import { PageLayout } from "@/components/ui/layout/PageLayout";
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '@/lib/utils';
import { LEAVE_TYPE_LABELS } from '@/types/leave';

type TabType = 'insights' | 'approvals' | 'allocations';

export default function LeaveAnalyticsPage() {
    const { user } = useAuth();
    const router = useRouter();
    const [activeTab, setActiveTab] = useState<TabType>('insights');
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [analyticsData, setAnalyticsData] = useState<any>(null);
    const [teamBalances, setTeamBalances] = useState<any[]>([]);
    const [pendingRequests, setPendingRequests] = useState<any[]>([]);
    const [pendingEdits, setPendingEdits] = useState<Record<string, Record<string, number>>>({});
    const [savingEdits, setSavingEdits] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');

    const fetchAllData = async () => {
        if (!user) return;
        setLoading(true);
        setError(null);
        try {
            const [analytics, balances, requests, allTeamMembers] = await Promise.all([
                apiGet('/api/leave/analytics'),
                LeaveBalanceService.getAllBalances(),
                apiGet('/api/leave/requests?status=pending'),
                UserService.getTeamMembers(null, user.id, { forceMediaIT: true })
            ]);
            
            const MEDIA_IT_DEPT_IDS = [103, 100, 4];
            
            // Build an array of teamBalances that includes EVERY valid team member.
            // Filter out 'manager' and 'admin' roles, as they manage others and shouldn't appear in the team allocations list.
            const unifiedBalances = allTeamMembers
                .filter(member => member.role !== 'manager' && member.role !== 'admin')
                .map(member => {
                const existingBalance = (balances || []).find((b: any) => b.user_id === member.uid);
                if (existingBalance) return existingBalance;
                
                // Provide a default structure for users who haven't had their leave initialized
                return {
                    id: `dummy-${member.uid}`,
                    user_id: member.uid,
                    balances: {
                        casual: { total: 0, taken: 0 },
                        sick: { total: 0, taken: 0 },
                        planned: { total: 0, taken: 0 },
                        unpaid: { total: 0, taken: 0 },
                        emergency: { total: 0, taken: 0 },
                        other: { total: 0, taken: 0 }
                    },
                    profiles: {
                        id: member.uid,
                        full_name: member.name,
                        avatar_url: member.avatar_url,
                        department_id: member.department_id
                    }
                };
            });
            
            const filteredRequests = (requests || []).filter((r: any) => {
                const isMediaIT = r.profiles?.department_id && MEDIA_IT_DEPT_IDS.includes(Number(r.profiles.department_id));
                const fullName = r.profiles?.full_name?.toLowerCase() || '';
                const isSystemUser = fullName.includes('admin user') || fullName.includes('super admin') || fullName.includes('generic admin');
                return isMediaIT && !isSystemUser;
            });
            
            setAnalyticsData(analytics);
            setTeamBalances(unifiedBalances);
            setPendingRequests(filteredRequests);
        } catch (err: any) {
            console.error('[LeaveAnalyticsPage] Fetch error:', err);
            setError(err.message || "Failed to load management data.");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (user) fetchAllData();
    }, [user]);

    const handleAction = async (requestId: string, status: 'approved' | 'rejected') => {
        try {
            await apiPost(`/api/leave/requests/${requestId}/status`, { status });
            toast.success(`Request ${status} successfully`);
            fetchAllData(); // Refresh
        } catch (err) {
            toast.error('Failed to process request');
        }
    };

    const handleLocalEdit = (userId: string, type: string, total: number) => {
        setPendingEdits(prev => ({
            ...prev,
            [userId]: {
                ...prev[userId],
                [type]: total
            }
        }));
    };

    const handleSaveAllocations = async () => {
        setSavingEdits(true);
        try {
            const promises: Promise<any>[] = [];
            Object.keys(pendingEdits).forEach(userId => {
                const userEdits = pendingEdits[userId];
                promises.push(LeaveBalanceService.updateUserAllocations(userId, userEdits));
            });

            await Promise.all(promises);
            toast.success("All leave allocations saved successfully");
            setPendingEdits({});
            fetchAllData(); // Refresh
        } catch (err: any) {
            console.error('[LeaveAnalyticsPage] Failed to save allocations:', err);
            toast.error(err?.message || "Failed to save some allocations");
        } finally {
            setSavingEdits(false);
        }
    };

    if (loading && !analyticsData) {
        return (
            <PageLayout mode="plain">
                <div className="flex items-center justify-center min-h-[60vh]">
                    <div className="flex flex-col items-center gap-4">
                        <Loader2 size={40} className="animate-spin text-indigo-500" />
                        <p className="text-sm font-medium text-foreground/80 animate-pulse">Initializing Dashboard...</p>
                    </div>
                </div>
            </PageLayout>
        );
    }

    const tabs: { id: TabType; label: string; icon: any }[] = [
        { id: 'insights', label: 'Operational Insights', icon: LayoutDashboard },
        { id: 'approvals', label: 'Pending Approvals', icon: ClipboardCheck },
        { id: 'allocations', label: 'Team Allocations', icon: Users },
    ];

    return (
        <PageLayout mode="plain" className="pt-8 pb-20">
            <div className="max-w-7xl mx-auto space-y-8">
                {/* Header */}
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                    <div>
                        <div className="flex items-center gap-3 mb-2">
                            <div className="p-2 bg-indigo-500/20 rounded-xl">
                                <Settings2 size={20} className="text-indigo-400" />
                            </div>
                            <h1 className="text-4xl font-bold text-foreground tracking-tight">Governance</h1>
                        </div>
                        <p className="text-foreground/80 text-sm font-medium ml-1">
                            Media & IT Department • Leave & Resource Management
                        </p>
                    </div>
                    
                    {/* Tab Navigation */}
                    <div className="flex p-1.5 bg-foreground/[0.03] border border-foreground/5 rounded-2xl backdrop-blur-sm">
                        {tabs.map((tab) => {
                            const isActive = activeTab === tab.id;
                            return (
                                <button
                                    key={tab.id}
                                    onClick={() => setActiveTab(tab.id)}
                                    className={cn(
                                        "flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 whitespace-nowrap",
                                        isActive 
                                            ? "bg-foreground/10 text-foreground shadow-xl shadow-black/20" 
                                            : "text-foreground/70 hover:text-foreground/80 hover:bg-foreground/[0.02]"
                                    )}
                                >
                                    <tab.icon size={16} className={isActive ? "text-indigo-400" : ""} />
                                    {tab.label}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Main Content Area */}
                <AnimatePresence mode="wait">
                    <motion.div
                        key={activeTab}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -20 }}
                        transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
                    >
                        {activeTab === 'insights' && (
                            <div className="space-y-8">
                                <div className="flex items-center justify-between">
                                    <h2 className="text-xl font-bold text-foreground/90">Strategic Overview</h2>
                                    <button className="flex items-center gap-2 px-4 py-2 bg-foreground/5 hover:bg-foreground/10 text-foreground/70 rounded-xl transition-all border border-foreground/5 text-xs font-bold uppercase tracking-widest">
                                        <Download size={14} />
                                        Export Report
                                    </button>
                                </div>
                                <LeaveAnalytics data={analyticsData} teamBalances={teamBalances} />
                            </div>
                        )}

                        {activeTab === 'approvals' && (
                            <div className="space-y-6">
                                <div className="flex items-center justify-between mb-2">
                                    <h2 className="text-xl font-bold text-foreground/90">Approval Queue</h2>
                                    <div className="flex items-center gap-3">
                                        <div className="px-3 py-1 bg-amber-500/10 border border-amber-500/20 rounded-full">
                                            <span className="text-[10px] font-black text-amber-400 uppercase tracking-widest">
                                                {pendingRequests.length} Pending
                                            </span>
                                        </div>
                                    </div>
                                </div>

                                {pendingRequests.length === 0 ? (
                                    <div className="glass-liquid border border-foreground/5 rounded-[32px] p-20 text-center space-y-4">
                                        <div className="w-16 h-16 bg-emerald-500/10 rounded-2xl flex items-center justify-center text-emerald-400 mx-auto">
                                            <CheckCircle2 size={32} />
                                        </div>
                                        <p className="text-foreground/80 font-medium">All clear! No pending leave requests.</p>
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        {pendingRequests.map((req) => (
                                            <motion.div 
                                                key={req.id}
                                                layout
                                                className="glass-liquid border border-foreground/10 rounded-[28px] p-6 space-y-6 relative group overflow-hidden"
                                            >
                                                <div className="flex items-start justify-between">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-12 h-12 rounded-2xl bg-indigo-500/20 flex items-center justify-center text-indigo-400 font-bold text-lg">
                                                            {req.profiles?.full_name?.[0] || '?'}
                                                        </div>
                                                        <div>
                                                            <h3 className="font-bold text-foreground text-lg">{req.profiles?.full_name}</h3>
                                                            <p className="text-xs text-foreground/70 font-bold uppercase tracking-wider">{LEAVE_TYPE_LABELS[req.type as keyof typeof LEAVE_TYPE_LABELS]}</p>
                                                        </div>
                                                    </div>
                                                    <div className="text-right">
                                                        <p className="text-xl font-black text-foreground">{req.total_days}d</p>
                                                        <p className="text-[10px] text-foreground/80 uppercase font-black">Duration</p>
                                                    </div>
                                                </div>

                                                <div className="space-y-3 bg-foreground/[0.02] p-4 rounded-2xl border border-foreground/5">
                                                    <div className="flex items-center justify-between text-xs font-bold">
                                                        <span className="text-foreground/70 uppercase tracking-widest">Period</span>
                                                        <span className="text-indigo-300">
                                                            {new Date(req.start_date).toLocaleDateString()} - {new Date(req.end_date).toLocaleDateString()}
                                                        </span>
                                                    </div>
                                                    <div className="space-y-1">
                                                        <span className="text-[10px] font-black text-foreground/70 uppercase tracking-widest">Reason</span>
                                                        <p className="text-sm text-foreground/70 line-clamp-2 italic">"{req.reason}"</p>
                                                    </div>
                                                </div>

                                                <div className="flex gap-3 pt-2">
                                                    <button 
                                                        onClick={() => handleAction(req.id, 'rejected')}
                                                        className="flex-1 py-3 rounded-xl bg-foreground/5 hover:bg-red-500/10 text-foreground/80 hover:text-red-400 font-bold text-xs uppercase tracking-widest transition-all border border-transparent hover:border-red-500/20 active:scale-95 flex items-center justify-center gap-2"
                                                    >
                                                        <XCircle size={14} />
                                                        Decline
                                                    </button>
                                                    <button 
                                                        onClick={() => handleAction(req.id, 'approved')}
                                                        className="flex-[2] py-3 rounded-xl bg-indigo-500 hover:bg-indigo-400 text-foreground font-bold text-xs uppercase tracking-widest transition-all shadow-xl shadow-indigo-500/20 active:scale-95 flex items-center justify-center gap-2"
                                                    >
                                                        <CheckCircle2 size={14} />
                                                        Grant Leave
                                                    </button>
                                                </div>
                                            </motion.div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {activeTab === 'allocations' && (
                            <div className="space-y-6">
                                <div className="flex items-center justify-between mb-4">
                                    <h2 className="text-xl font-bold text-foreground/90">Team Leave Allocations</h2>
                                    <div className="flex items-center gap-4">
                                        {Object.keys(pendingEdits).length > 0 && (
                                            <button 
                                                onClick={handleSaveAllocations}
                                                disabled={savingEdits}
                                                className="px-5 py-2.5 bg-indigo-500 hover:bg-indigo-400 text-foreground font-bold text-xs uppercase tracking-widest rounded-xl transition-all shadow-xl shadow-indigo-500/20 active:scale-95 flex items-center gap-2 animate-in fade-in slide-in-from-right-4 duration-300"
                                            >
                                                {savingEdits ? (
                                                    <>
                                                        <Loader2 size={14} className="animate-spin" />
                                                        Saving...
                                                    </>
                                                ) : (
                                                    <>
                                                        <ClipboardCheck size={14} />
                                                        Save Allocations
                                                    </>
                                                )}
                                            </button>
                                        )}
                                        <div className="relative group w-72">
                                            <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground/80 group-focus-within:text-indigo-400 transition-colors" />
                                            <input 
                                                type="text" 
                                                placeholder="Search team member..."
                                                value={searchQuery}
                                                onChange={(e) => setSearchQuery(e.target.value)}
                                                className="w-full bg-foreground/[0.03] border border-foreground/5 rounded-xl py-2.5 pl-12 pr-4 text-sm text-foreground focus:outline-none focus:border-indigo-500/30 transition-all"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="glass-liquid border border-foreground/5 rounded-[32px] overflow-hidden">
                                    <table className="w-full text-left">
                                        <thead className="bg-foreground/5 border-b border-foreground/5">
                                            <tr>
                                                <th className="px-8 py-5 text-[10px] font-black text-foreground/70 uppercase tracking-[0.2em]">Team Member</th>
                                                {Object.keys(LEAVE_TYPE_LABELS).map(type => (
                                                    <th key={type} className="px-6 py-5 text-[10px] font-black text-foreground/70 uppercase tracking-[0.2em] text-center">
                                                        {LEAVE_TYPE_LABELS[type as keyof typeof LEAVE_TYPE_LABELS]} (Total)
                                                    </th>
                                                ))}
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-white/5">
                                            {teamBalances
                                                .filter(item => item.profiles?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()))
                                                .map((item) => (
                                                <tr key={item.id} className="hover:bg-foreground/[0.02] transition-colors group">
                                                    <td className="px-8 py-6">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-400 font-bold text-sm">
                                                                {item.profiles?.full_name?.[0] || '?'}
                                                            </div>
                                                            <div>
                                                                <p className="font-bold text-foreground">{item.profiles?.full_name}</p>
                                                                <p className="text-[10px] text-foreground/80 font-black uppercase tracking-widest">ID: {item.user_id.substring(0, 8)}</p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    {Object.keys(LEAVE_TYPE_LABELS).map(type => {
                                                        const taken = item.balances?.[type]?.taken || 0;
                                                        const currentTotal = pendingEdits[item.user_id]?.[type] !== undefined
                                                            ? pendingEdits[item.user_id][type]
                                                            : (item.balances?.[type]?.total || 0);
                                                        const remaining = currentTotal - taken;
                                                        
                                                        return (
                                                            <td key={type} className="px-6 py-6 text-center">
                                                                <div className="inline-flex flex-col items-center gap-1 group/input">
                                                                    <input 
                                                                        type="number"
                                                                        value={currentTotal}
                                                                        onChange={(e) => {
                                                                            const val = parseInt(e.target.value) || 0;
                                                                            handleLocalEdit(item.user_id, type, val);
                                                                        }}
                                                                        className="w-16 bg-foreground/5 border border-foreground/10 rounded-lg py-1.5 text-center text-sm font-bold text-foreground focus:outline-none focus:border-indigo-500/50 transition-all hover:bg-foreground/10"
                                                                    />
                                                                    
                                                                    {/* Compact Used & Left indicator */}
                                                                    <div className="mt-1.5 flex flex-col items-center gap-0.5 text-[9px] font-black uppercase tracking-tighter">
                                                                        <span className="text-foreground/40 leading-none">
                                                                            Used: {taken}
                                                                        </span>
                                                                        <span className={cn(
                                                                            "leading-none font-bold",
                                                                            remaining > 0 ? "text-emerald-400" : "text-rose-400/80"
                                                                        )}>
                                                                            Left: {remaining}
                                                                        </span>
                                                                    </div>
                                                                </div>
                                                            </td>
                                                        );
                                                    })}
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}
                    </motion.div>
                </AnimatePresence>
            </div>
        </PageLayout>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { apiClient } from '@/lib/apiClient';
import { DropdownSelector } from '@/components/ui/selectors/DropdownSelector';

interface SystemStats {
  uptime: string;
  cpuUsage: number;
  memoryUsage: number;
  diskUsage: number;
  activeUsers: number;
  totalRequests: number;
  errorRate: number;
  responseTime: number;
}

interface AuditStats {
  actionCounts: { action: string; count: number }[];
  resourceTypeCounts: { resourceType: string; count: number }[];
  dailyCounts: { date: string; count: number }[];
  topUsers: { userId: number; count: number; user: any }[];
}

export default function SystemMonitoringPage() {
  const [systemStats, setSystemStats] = useState<SystemStats | null>(null);
  const [auditStats, setAuditStats] = useState<AuditStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedPeriod, setSelectedPeriod] = useState('week');
  const [selectedTenant, setSelectedTenant] = useState('all');

  // Fetch system stats
  useEffect(() => {
    const fetchStats = async () => {
      try {
        // Fetch system stats
        const systemData = await apiClient('/api/monitoring/system/stats', {
          method: 'GET'
        });
        setSystemStats(systemData);

        // Fetch audit stats
        const auditData = await apiClient(`/api/audit-log/stats?period=${selectedPeriod}&tenant=${selectedTenant}`, {
          method: 'GET'
        });
        setAuditStats(auditData);
      } catch (error) {
        console.error('Failed to fetch monitoring data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();

    // Refresh stats every 30 seconds
    const interval = setInterval(fetchStats, 30000);
    return () => clearInterval(interval);
  }, [selectedPeriod, selectedTenant]);

  if (loading) {
    return <div>Loading monitoring data...</div>;
  }

  if (!systemStats || !auditStats) {
    return <div>Failed to load monitoring data</div>;
  }

  return (
    <div className="system-monitoring-page p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">System Monitoring</h1>
        <div className="flex space-x-4">
          <div className="space-y-0.5">
            <DropdownSelector 
              label="Campus"
              value={selectedTenant}
              onChange={setSelectedTenant}
              options={[
                { id: 'all', label: 'All Campuses' },
                { id: '1', label: 'TG Antla' },
                { id: '2', label: 'TG Bangkok' },
                { id: '3', label: 'TG Chiang Mai' },
              ]}
            />
          </div>
          <div className="space-y-0.5">
            <DropdownSelector 
              label="Period"
              value={selectedPeriod}
              onChange={setSelectedPeriod}
              options={[
                { id: 'day', label: 'Today' },
                { id: 'week', label: 'This Week' },
                { id: 'month', label: 'This Month' },
              ]}
            />
          </div>
        </div>
      </div>

      {/* System Health Overview */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Uptime</h2>
          <div className="text-3xl font-bold text-green-600">{systemStats.uptime}</div>
        </div>

        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">CPU Usage</h2>
          <div className="flex items-center">
            <div className="text-3xl font-bold">{systemStats.cpuUsage}%</div>
            <div className="ml-4 w-full bg-gray-200 rounded-full h-2">
              <div
                className={`h-2 rounded-full ${systemStats.cpuUsage > 80 ? 'bg-red-500' :
                  systemStats.cpuUsage > 60 ? 'bg-yellow-500' : 'bg-green-500'
                  }`}
                style={{ width: `${systemStats.cpuUsage}%` }}
              ></div>
            </div>
          </div>
        </div>

        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Memory Usage</h2>
          <div className="flex items-center">
            <div className="text-3xl font-bold">{systemStats.memoryUsage}%</div>
            <div className="ml-4 w-full bg-gray-200 rounded-full h-2">
              <div
                className={`h-2 rounded-full ${systemStats.memoryUsage > 80 ? 'bg-red-500' :
                  systemStats.memoryUsage > 60 ? 'bg-yellow-500' : 'bg-green-500'
                  }`}
                style={{ width: `${systemStats.memoryUsage}%` }}
              ></div>
            </div>
          </div>
        </div>

        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Active Users</h2>
          <div className="text-3xl font-bold text-blue-600">{systemStats.activeUsers}</div>
        </div>
      </div>

      {/* Request Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Total Requests</h2>
          <div className="text-3xl font-bold">{systemStats.totalRequests.toLocaleString()}</div>
        </div>

        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Error Rate</h2>
          <div className="flex items-center">
            <div className="text-3xl font-bold">{systemStats.errorRate}%</div>
            <div className="ml-4 w-full bg-gray-200 rounded-full h-2">
              <div
                className={`h-2 rounded-full ${systemStats.errorRate > 5 ? 'bg-red-500' :
                  systemStats.errorRate > 2 ? 'bg-yellow-500' : 'bg-green-500'
                  }`}
                style={{ width: `${Math.min(100, systemStats.errorRate * 10)}%` }}
              ></div>
            </div>
          </div>
        </div>

        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Avg Response Time</h2>
          <div className="text-3xl font-bold">{systemStats.responseTime}ms</div>
        </div>
      </div>

      {/* Audit Log Analytics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 mb-6">
        {/* Top Actions */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Top Actions</h2>
          <div className="space-y-2">
            {auditStats.actionCounts.map((action, index) => (
              <div key={index} className="flex justify-between items-center">
                <span>{action.action}</span>
                <span className="bg-blue-100 text-blue-800 px-2 py-1 rounded text-sm">
                  {action.count}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Top Resource Types */}
        <div className="bg-white shadow rounded p-4">
          <h2 className="text-lg font-bold mb-3">Top Resource Types</h2>
          <div className="space-y-2">
            {auditStats.resourceTypeCounts.map((resource, index) => (
              <div key={index} className="flex justify-between items-center">
                <span>{resource.resourceType}</span>
                <span className="bg-green-100 text-green-800 px-2 py-1 rounded text-sm">
                  {resource.count}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Daily Activity */}
      <div className="bg-white shadow rounded p-4 mb-6">
        <h2 className="text-lg font-bold mb-3">Daily Activity</h2>
        <div className="h-64 flex items-end space-x-2">
          {auditStats.dailyCounts.map((day, index) => (
            <div key={index} className="flex flex-col items-center flex-1">
              <div
                className="w-full bg-blue-500 rounded-t"
                style={{ height: `${(day.count / Math.max(...auditStats.dailyCounts.map(d => d.count))) * 100}%` }}
              ></div>
              <div className="text-xs text-foreground/50 mt-1">
                {new Date(day.date).toLocaleDateString('en-US', { weekday: 'short' })}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Top Users */}
      <div className="bg-white shadow rounded p-4">
        <h2 className="text-lg font-bold mb-3">Top Active Users</h2>
        <div className="space-y-3">
          {auditStats.topUsers.map((user, index) => (
            <div key={index} className="flex items-center">
              <div className="w-8 h-8 rounded-full bg-blue-500 text-foreground flex items-center justify-center text-sm font-bold mr-3">
                {index + 1}
              </div>
              <div className="flex-1">
                <div className="font-medium">{user.user.fullName}</div>
                <div className="text-sm text-foreground/50">{user.user.email}</div>
              </div>
              <div className="bg-purple-100 text-purple-800 px-3 py-1 rounded-full text-sm">
                {user.count} actions
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

'use client';


import React, { useEffect, useState } from "react";
import { PageLayout } from "@/components/ui/layout/PageLayout";
import { PageHeader } from "@/components/ui/layout/PageHeader";
import { Button } from "@/components/ui/button";
import { ArrowLeft, Shield, Lock, Users, Eye, Database, Globe, Check, X } from "lucide-react";
import { useRouter } from "next/navigation";
import { apiClient, apiPost } from '@/lib/apiClient';
import { nativeNavigate } from "@/lib/utils";
import { toast } from "sonner";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

interface SystemSettings {
    allowMemberTasks: boolean;
    publicFilesDefault: boolean;
    driveAutoScan: boolean;
}

export default function SecurityRulesPage() {
    const router = useRouter();
    const [settings, setSettings] = useState<SystemSettings | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchSettings();
    }, []);

    const fetchSettings = async () => {
        try {
            const data = await apiClient<{ settings: SystemSettings }>('/api/admin/settings');
            setSettings(data.settings);
        } catch (error) {
            console.error("Failed to load settings:", error);
            toast.error("Failed to load security settings");
        } finally {
            setLoading(false);
        }
    };

    const handleToggle = async (key: keyof SystemSettings, currentValue: boolean) => {
        const newValue = !currentValue;

        // Optimistic update
        setSettings(prev => prev ? { ...prev, [key]: newValue } : null);

        try {
            await apiPost('/api/admin/settings', { key, value: newValue });
            toast.success("Security rule updated");
        } catch (error) {
            console.error("Failed to update setting:", error);
            toast.error("Failed to update rule");
            // Revert
            setSettings(prev => prev ? { ...prev, [key]: currentValue } : null);
        }
    };

    return (
        <PageLayout mode="plain">
            <PageHeader
                title="Security Rules"
                description="Manage system access policies and protection rules."
                actions={
                    <Button variant="ghost" onClick={() => nativeNavigate('/admin', router, 'SecurityRules (Back)')} className="gap-2 text-foreground/60 hover:text-foreground">
                        <ArrowLeft size={16} />
                        Back to Command Center
                    </Button>
                }
            />

            <div className="max-w-5xl mx-auto pb-20 space-y-8">

                {/* Section 1: Read-Only Overview */}
                <div className="glass-liquid border-foreground/10 rounded-[32px] p-8 shadow-2xl space-y-6">
                    <div className="space-y-1">
                        <h2 className="text-xl font-bold flex items-center gap-2 text-foreground">
                            <Shield className="w-5 h-5 text-primary" />
                            Security Overview (Read-Only)
                        </h2>
                        <p className="text-foreground/60 text-sm">
                            Current enforcement policies hardcoded into the system core.
                        </p>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-foreground/5">
                        <div className="space-y-4">
                            <h3 className="text-sm font-black text-foreground/80 uppercase tracking-widest flex items-center gap-2">
                                <Users className="w-4 h-4 text-primary" /> Role Access Model
                            </h3>
                             <div className="space-y-2.5">
                                <RoleBadge role="Admin" access="Full Access" color="bg-purple-500/10 text-purple-400 border-purple-500/20" />
                                <RoleBadge role="Manager" access="Full Access (Strategic)" color="bg-indigo-500/10 text-indigo-400 border-indigo-500/20" />
                                <RoleBadge role="Team" access="Operational Access (Execution)" color="bg-blue-500/10 text-blue-400 border-blue-500/20" />
                                <RoleBadge role="Member" access="Request Only (Pending Approval)" color="bg-emerald-500/10 text-emerald-400 border-emerald-500/20" />
                            </div>
                        </div>
 
                        <div className="space-y-4">
                            <h3 className="text-sm font-black text-foreground/80 uppercase tracking-widest flex items-center gap-2">
                                <Lock className="w-4 h-4 text-primary" /> Data Protection
                            </h3>
                            <ul className="space-y-3 text-sm text-foreground/60">
                                <li className="flex items-center gap-2.5">
                                    <Check className="w-3.5 h-3.5 text-primary" />
                                    <span>System Activity is <strong>Immutable</strong> (Append-Only)</span>
                                </li>
                                <li className="flex items-center gap-2.5">
                                    <Check className="w-3.5 h-3.5 text-primary" />
                                    <span>API Routes enforce <strong>Server-Side Validation</strong></span>
                                </li>
                                <li className="flex items-center gap-2.5">
                                    <Check className="w-3.5 h-3.5 text-primary" />
                                    <span>Client Writes restricted via <strong>Firestore Rules</strong></span>
                                </li>
                            </ul>
                        </div>
                    </div>
                </div>
 
                {/* Section 2: Active Controls */}
                <div className="space-y-4">
                    <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
                        <Globe className="w-5 h-5 text-primary" />
                        Active Security Controls
                    </h2>
                    <p className="text-foreground/60 text-sm">
                        Toggle these rules to adjust system behavior in real-time.
                        <strong> All changes are logged as CRITICAL security events.</strong>
                    </p>
 
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <SecurityToggle
                            label="Member Task Creation"
                            description="Allow members to submit tasks for approval."
                            checked={settings?.allowMemberTasks ?? true}
                            onChange={(checked: boolean) => handleToggle('allowMemberTasks', !checked)}
                            icon={<Users className="w-5 h-5 text-primary" />}
                            loading={loading}
                        />

                        <SecurityToggle
                            label="Public File Default"
                            description="Newly uploaded files are public by default."
                            checked={settings?.publicFilesDefault ?? true}
                            onChange={(checked: boolean) => handleToggle('publicFilesDefault', !checked)}
                            icon={<Eye className="w-5 h-5 text-primary" />}
                            loading={loading}
                        />

                        <SecurityToggle
                            label="Auto-Drive Scanning"
                            description="Automatically ingest files from Google Drive."
                            checked={settings?.driveAutoScan ?? true}
                            onChange={(checked: boolean) => handleToggle('driveAutoScan', !checked)}
                            icon={<Database className="w-5 h-5 text-primary" />}
                            loading={loading}
                        />
                    </div>
                </div>

            </div>
        </PageLayout>
    );
}

function RoleBadge({ role, access, color }: { role: string, access: string, color: string }) {
    return (
        <div className={`flex items-center justify-between px-4 py-2.5 rounded-full border text-xs font-semibold ${color}`}>
            <span className="uppercase tracking-wider">{role}</span>
            <span className="opacity-80">{access}</span>
        </div>
    );
}

function SecurityToggle({ label, description, checked, onChange, icon, loading }: any) {
    return (
        <div className="glass-liquid border border-foreground/10 p-5 rounded-[24px] flex flex-col justify-between gap-4 shadow-lg backdrop-blur-md">
            <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-foreground/5 rounded-full">{icon}</div>
                    <div>
                        <h4 className="font-bold text-foreground text-sm">{label}</h4>
                    </div>
                </div>
                <Switch checked={checked} onCheckedChange={onChange} disabled={loading} className="data-[state=checked]:bg-primary" />
            </div>
            <p className="text-xs text-foreground/60 leading-relaxed font-medium">{description}</p>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { FEATURE_REGISTRY, FeatureKey } from '@/system/features/featureRegistry';
import { PageLayout } from '@/components/ui/layout/PageLayout';
import { PageHeader } from '@/components/ui/layout/PageHeader';
import { Button } from '@/components/ui/button';
import { 
    Save, 
    ShieldAlert,
    RefreshCcw,
    Sliders
} from 'lucide-react';
import { toast } from 'sonner';

const ROLES = ['admin', 'manager', 'team', 'member'] as const;
type RoleType = typeof ROLES[number];

export default function FeaturePermissionsClient() {
    const [overrides, setOverrides] = useState<Record<string, string>>({});
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        fetchOverrides();
    }, []);

    const fetchOverrides = async () => {
        try {
            setLoading(true);
            const res = await fetch('/api/admin/features');
            if (!res.ok) throw new Error('Failed to fetch overrides');
            const data = await res.json();
            setOverrides(data.featureOverrides || {});
        } catch (error) {
            console.error(error);
            toast.error('Failed to load feature configurations.');
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        try {
            setSaving(true);
            const res = await fetch('/api/admin/features', {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ featureOverrides: overrides })
            });

            if (!res.ok) throw new Error('Failed to save');
            
            toast.success('Feature permissions updated successfully!');
            
            // Reload page to refresh the workspace context
            setTimeout(() => {
                window.location.reload();
            }, 1000);
        } catch (error) {
            console.error(error);
            toast.error('Failed to save configurations.');
        } finally {
            setSaving(false);
        }
    };

    const handleOverrideChange = (feature: string, newRole: string) => {
        setOverrides(prev => {
            const next = { ...prev };
            // If the user selects the default role, we can remove the override to keep JSON small
            const defaultRole = FEATURE_REGISTRY[feature as FeatureKey].minRole || 'member';
            if (newRole === defaultRole) {
                delete next[feature];
            } else {
                next[feature] = newRole;
            }
            return next;
        });
    };

    const handleReset = (feature: string) => {
        setOverrides(prev => {
            const next = { ...prev };
            delete next[feature];
            return next;
        });
    };

    const featuresList = Object.entries(FEATURE_REGISTRY).map(([key, config]) => ({
        id: key,
        ...config
    }));

    return (
        <PageLayout>
            <PageHeader
                title="Feature Config"
                description="Manage access levels and permissions for all application modules"
                actions={
                    <div className="flex items-center gap-3">
                        <Button
                            variant="ghost"
                            onClick={fetchOverrides}
                            disabled={loading || saving}
                            className="text-foreground/80 hover:text-foreground border border-foreground/10 hover:bg-foreground/5 backdrop-blur-md rounded-full px-5 py-2 transition-all duration-200 active:scale-95 text-xs font-bold"
                        >
                            <RefreshCcw size={16} className={`mr-2 ${loading ? 'animate-spin' : ''}`} />
                            Refresh
                        </Button>
                        <Button 
                            onClick={handleSave} 
                            disabled={loading || saving}
                            className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-full px-6 py-2 transition-all duration-200 active:scale-95 shadow-lg shadow-primary/20 text-xs font-bold tracking-wide"
                        >
                            <Save size={16} className="mr-2" />
                            {saving ? 'Saving...' : 'Save Changes'}
                        </Button>
                    </div>
                }
            />
            <div className="max-w-[1200px] mx-auto pt-6">
                
                <div className="glass-liquid border border-foreground/10 rounded-[32px] overflow-hidden shadow-2xl backdrop-blur-md">
                    <div className="p-6 border-b border-foreground/5 bg-foreground/[0.02]">
                        <div className="flex items-start gap-4">
                            <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center text-primary shrink-0 mt-1 shadow-inner">
                                <ShieldAlert size={20} />
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-foreground tracking-tight">Global Overrides</h2>
                                <p className="text-sm text-foreground/60 mt-1 leading-relaxed font-medium">
                                    Adjusting these settings will immediately affect all users within this tenant. 
                                    Setting a feature to a higher role (e.g., Admin) will instantly hide it from lower roles.
                                </p>
                            </div>
                        </div>
                    </div>
                    
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="border-b border-foreground/5 bg-foreground/[0.01]">
                                    <th className="px-6 py-4 text-xs font-black text-foreground/70 uppercase tracking-[0.2em]">Module / Feature</th>
                                    <th className="px-6 py-4 text-xs font-black text-foreground/70 uppercase tracking-[0.2em]">Default Required Role</th>
                                    <th className="px-6 py-4 text-xs font-black text-foreground/70 uppercase tracking-[0.2em]">Current Override</th>
                                    <th className="px-6 py-4 text-xs font-black text-foreground/70 uppercase tracking-[0.2em] text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-foreground/5">
                                {loading ? (
                                    <tr>
                                        <td colSpan={4} className="px-6 py-12 text-center text-foreground/80 text-sm font-medium">
                                            Loading configurations...
                                        </td>
                                    </tr>
                                ) : featuresList.map(feature => {
                                    const defaultRole = feature.minRole || 'member';
                                    const currentOverride = overrides[feature.id];
                                    const isOverridden = !!currentOverride;
                                    const activeRole = currentOverride || defaultRole;

                                    return (
                                        <tr key={feature.id} className="hover:bg-foreground/[0.02] transition-colors group">
                                            <td className="px-6 py-4">
                                                <div className="flex items-center gap-3">
                                                    <span className="text-sm font-bold text-foreground capitalize">
                                                        {feature.id.replace(/([A-Z])/g, ' $1').trim()}
                                                    </span>
                                                    {feature.isLabs && (
                                                        <span className="px-2 py-0.5 rounded-md bg-indigo-500/20 text-indigo-400 text-[10px] font-bold tracking-wider uppercase">
                                                            Labs
                                                        </span>
                                                    )}
                                                    {isOverridden && (
                                                        <span className="px-2 py-0.5 rounded-md bg-amber-500/20 text-amber-400 text-[10px] font-bold tracking-wider uppercase">
                                                            Modified
                                                        </span>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className="text-sm font-medium text-foreground/80 capitalize">
                                                    {defaultRole}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4">
                                                <select
                                                    value={activeRole}
                                                    onChange={(e) => handleOverrideChange(feature.id, e.target.value)}
                                                    className={`border rounded-full px-4 py-1.5 text-xs font-bold capitalize outline-none focus:ring-2 focus:ring-primary/40 transition-all ${
                                                        isOverridden ? 'border-primary/30 text-primary bg-primary/10 shadow-sm' : 'border-foreground/10 text-foreground/90 bg-foreground/[0.03]'
                                                    }`}
                                                >
                                                    {ROLES.map(role => (
                                                        <option key={role} value={role} className="bg-popover text-foreground">
                                                            {role} {role === defaultRole ? '(Default)' : ''}
                                                        </option>
                                                    ))}
                                                </select>
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                <Button
                                                    variant="ghost"
                                                    size="sm"
                                                    disabled={!isOverridden}
                                                    onClick={() => handleReset(feature.id)}
                                                    className={`text-xs rounded-full ${isOverridden ? 'text-rose-400 hover:text-rose-300 hover:bg-rose-500/10' : 'text-foreground/70'}`}
                                                >
                                                    Reset to Default
                                                </Button>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </PageLayout>
    );
}

'use client';



import React, { useEffect, useState } from "react";
import { PageLayout } from "@/components/ui/layout/PageLayout";
import { PageHeader } from "@/components/ui/layout/PageHeader";
import { Button } from "@/components/ui/button";
import { ArrowLeft, Activity, Database, Server, RefreshCw, FileText, HardDrive } from "lucide-react";
import { useRouter } from "next/navigation";
import { apiClient } from "@/lib/apiClient";
import { nativeNavigate } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";

interface HealthStats {
    api: 'healthy' | 'degraded' | 'down' | 'unknown';
    db: 'healthy' | 'degraded' | 'down' | 'unknown';
    drive: 'healthy' | 'degraded' | 'down' | 'unknown';
    logger: 'healthy' | 'degraded' | 'down' | 'unknown';
    lastScan: string | null;
    lastLog: string | null;
    generatedAt: string;
}

export default function SystemHealthPage() {
    const router = useRouter();
    const [stats, setStats] = useState<HealthStats | null>(null);
    const [loading, setLoading] = useState(true);
    const [refreshing, setRefreshing] = useState(false);

    const fetchHealth = async () => {
        setRefreshing(true);
        try {
            const data = await apiClient<{ health: HealthStats }>('/api/admin/health');
            setStats(data.health);
        } catch (error) {
            console.error("Failed to fetch health:", error);
        } finally {
            setLoading(false);
            setRefreshing(false);
        }
    };

    useEffect(() => {
        fetchHealth();
        // Auto-refresh every 30s
        const interval = setInterval(fetchHealth, 30000);
        return () => clearInterval(interval);
    }, []);

    return (
        <PageLayout mode="plain">
            <PageHeader
                title="System Health"
                description="Live operational status of core system components."
                actions={
                    <div className="flex items-center gap-2">
                        <Button variant="ghost" onClick={fetchHealth} disabled={refreshing} className="text-muted hover:text-foreground">
                            <RefreshCw size={16} className={cn("mr-2", refreshing && "animate-spin")} />
                            Refresh
                        </Button>
                        <Button variant="ghost" onClick={() => nativeNavigate('/admin', router, 'SystemHealth (Back)')} className="gap-2 text-muted hover:text-foreground">
                            <ArrowLeft size={16} />
                            Back
                        </Button>
                    </div>
                }
            />

            <div className="max-w-5xl mx-auto pb-20">

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                    <HealthCard
                        title="API Response"
                        status={stats?.api || 'unknown'}
                        icon={<Server className="w-5 h-5" />}
                        description="Next.js API Routes"
                        detail={stats ? "Responding normally" : "Checking..."}
                        loading={loading}
                    />
                    <HealthCard
                        title="Database"
                        status={stats?.db || 'unknown'}
                        icon={<Database className="w-5 h-5" />}
                        description="Supabase Postgres"
                        detail={stats?.db === 'healthy' ? "Read/Write available" : "Connectivity lost"}
                        loading={loading}
                    />
                    <HealthCard
                        title="Assignment Sync"
                        status={(stats as any)?.sync || 'unknown'}
                        icon={<RefreshCw className="w-5 h-5" />}
                        description="JSONB ↔ Relational"
                        detail={(stats as any)?.driftCount > 0 ? `${(stats as any).driftCount} tasks drifted` : "No drift detected"}
                        loading={loading}
                    />
                    <HealthCard
                        title="Activity Logger"
                        status={stats?.logger || 'unknown'}
                        icon={<FileText className="w-5 h-5" />}
                        description="Audit Trail System"
                        detail={stats?.lastLog ? `Last Log: ${formatDistanceToNow(new Date(stats.lastLog))} ago` : "Operational"}
                        loading={loading}
                    />
                </div>

                <div className="bg-surface border border-soft rounded-xl p-6 shadow-sm">
                    <h3 className="text-lg font-medium text-foreground mb-4 flex items-center gap-2">
                        <Activity className="w-5 h-5 text-blue-500" />
                        Health Logic Explanation
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-sm text-muted">
                        <ul className="space-y-3">
                            <li className="flex gap-3">
                                <div className="w-2 h-2 rounded-full bg-green-500 mt-1.5 shrink-0" />
                                <div>
                                    <strong className="text-foreground">API Response:</strong> Checks if the internal API can receive and process requests without error.
                                </div>
                            </li>
                            <li className="flex gap-3">
                                <div className="w-2 h-2 rounded-full bg-green-500 mt-1.5 shrink-0" />
                                <div>
                                    <strong className="text-foreground">Database:</strong> Verifies connectivity to Firestore via the MOCK_KEY Admin SDK.
                                </div>
                            </li>
                        </ul>
                        <ul className="space-y-3">
                            <li className="flex gap-3">
                                <div className="w-2 h-2 rounded-full bg-green-500 mt-1.5 shrink-0" />
                                <div>
                                    <strong className="text-foreground">Assignment Sync:</strong> Monitors drift between the `tasks.assigned_to` JSONB array and the `task_assignments` relational table. If counts don't match, the system flags it as degraded.
                                </div>
                            </li>
                            <li className="flex gap-3">
                                <div className="w-2 h-2 rounded-full bg-green-500 mt-1.5 shrink-0" />
                                <div>
                                    <strong className="text-foreground">Activity Logger:</strong> Checks if the system is successfully writing to the audit log. Critical for security and data integrity.
                                </div>
                            </li>
                        </ul>
                    </div>
                </div>

            </div>
        </PageLayout>
    );
}

function HealthCard({ title, status, icon, description, detail, loading }: any) {
    const statusColor = {
        healthy: "bg-green-500",
        degraded: "bg-amber-500",
        down: "bg-red-500",
        unknown: "bg-slate-500"
    };

    const statusText = {
        healthy: "Operational",
        degraded: "Degraded",
        down: "Down",
        unknown: "Hidden"
    };

    return (
        <div className="bg-surface border border-soft p-5 rounded-xl relative overflow-hidden group hover:border-muted/30 transition-colors shadow-sm">
            {loading ? (
                <div className="animate-pulse space-y-3">
                    <div className="h-4 w-24 bg-muted/20 rounded" />
                    <div className="h-8 w-16 bg-muted/20 rounded" />
                </div>
            ) : (
                <>
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-2 bg-muted/10 rounded-lg text-muted">
                            {icon}
                        </div>
                        <div className={`flex items-center gap-1.5 px-2 py-1 rounded-full bg-accent-primary-soft border border-soft text-[10px] uppercase font-bold tracking-wider ${status === 'healthy' ? 'text-green-500' : status === 'degraded' ? 'text-amber-500' : 'text-red-500'}`}>
                            <div className={`w-1.5 h-1.5 rounded-full ${statusColor[status as keyof typeof statusColor]} animate-pulse`} />
                            {statusText[status as keyof typeof statusText]}
                        </div>
                    </div>

                    <h3 className="text-lg font-semibold text-foreground mb-1">{title}</h3>
                    <p className="text-xs text-muted mb-4">{description}</p>

                    <div className="pt-4 border-t border-soft">
                        <p className="text-xs text-muted font-mono">{detail}</p>
                    </div>
                </>
            )}
        </div>
    );

}

