'use client';

import React, { useState, useEffect } from 'react';
import { apiClient } from '@/lib/apiClient';

interface Tenant {
    id: number;
    name: string;
    domain: string;
    settings?: any;
    created_at: string;
    updated_at: string;
}

export default function TenantsClient() {
    const [tenants, setTenants] = useState<Tenant[]>([]);
    const [loading, setLoading] = useState(true);
    const [showCreateForm, setShowCreateForm] = useState(false);
    const [editingTenant, setEditingTenant] = useState<Tenant | null>(null);

    // Form state
    const [tenantForm, setTenantForm] = useState({
        name: '',
        domain: '',
        settings: ''
    });

    // Fetch tenants
    useEffect(() => {
        // Skip during SSG
        if (typeof window === 'undefined') return;

        const fetchTenants = async () => {
            try {
                const data = await apiClient('/api/tenants', {
                    method: 'GET'
                });
                setTenants(data.tenants);
            } catch (error) {
                console.error('Failed to fetch tenants:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchTenants();
    }, []);

    // Create or update a tenant
    const handleSaveTenant = async (e: React.FormEvent) => {
        e.preventDefault();

        try {
            const url = editingTenant ? `/api/tenants/${editingTenant.id}` : '/api/tenants';
            const method = editingTenant ? 'PUT' : 'POST';

            const data = await apiClient(url, {
                method,
                body: JSON.stringify({
                    name: tenantForm.name,
                    domain: tenantForm.domain,
                    settings: tenantForm.settings ? JSON.parse(tenantForm.settings) : {}
                }),
            });

            if (editingTenant) {
                setTenants(tenants.map(tenant => tenant.id === editingTenant.id ? data.tenant : tenant));
            } else {
                setTenants([...tenants, data.tenant]);
            }
            resetForm();
        } catch (error) {
            console.error('Failed to save tenant:', error);
        }
    };

    // Edit a tenant
    const editTenant = (tenant: Tenant) => {
        setEditingTenant(tenant);
        setTenantForm({
            name: tenant.name,
            domain: tenant.domain,
            settings: tenant.settings ? JSON.stringify(tenant.settings, null, 2) : ''
        });
        setShowCreateForm(true);
    };

    // Delete a tenant
    const deleteTenant = async (tenantId: number) => {
        if (!confirm('Are you sure you want to delete this tenant? This action cannot be undone.')) {
            return;
        }

        try {
            await apiClient(`/api/tenants/${tenantId}`, {
                method: 'DELETE',
            });

            setTenants(tenants.filter(tenant => tenant.id !== tenantId));
        } catch (error) {
            console.error('Failed to delete tenant:', error);
        }
    };

    // Reset form
    const resetForm = () => {
        setTenantForm({
            name: '',
            domain: '',
            settings: ''
        });
        setEditingTenant(null);
        setShowCreateForm(false);
    };

    if (loading) {
        return <div>Loading tenants...</div>;
    }

    return (
        <div className="tenants-page p-6">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold">Tenant Management</h1>
                <button
                    onClick={() => setShowCreateForm(!showCreateForm)}
                    className="bg-blue-500 hover:bg-blue-700 text-foreground font-bold py-2 px-4 rounded"
                >
                    {showCreateForm ? 'Cancel' : 'Create New Tenant'}
                </button>
            </div>

            {showCreateForm && (
                <div className="bg-white shadow-md rounded px-8 pt-6 pb-8 mb-4">
                    <h2 className="text-xl font-bold mb-4">
                        {editingTenant ? 'Edit Tenant' : 'Create New Tenant'}
                    </h2>
                    <form onSubmit={handleSaveTenant}>
                        <div className="mb-4">
                            <label className="block text-foreground/30 text-sm font-bold mb-2" htmlFor="name">
                                Tenant Name
                            </label>
                            <input
                                id="name"
                                type="text"
                                value={tenantForm.name}
                                onChange={(e) => setTenantForm({ ...tenantForm, name: e.target.value })}
                                className="shadow appearance-none border rounded w-full py-2 px-3 text-foreground/30 leading-tight focus:outline-none focus:shadow-outline"
                                required
                            />
                        </div>

                        <div className="mb-4">
                            <label className="block text-foreground/30 text-sm font-bold mb-2" htmlFor="domain">
                                Domain
                            </label>
                            <input
                                id="domain"
                                type="text"
                                value={tenantForm.domain}
                                onChange={(e) => setTenantForm({ ...tenantForm, domain: e.target.value })}
                                className="shadow appearance-none border rounded w-full py-2 px-3 text-foreground/30 leading-tight focus:outline-none focus:shadow-outline"
                                required
                            />
                            <p className="text-foreground/40 text-xs mt-1">The unique domain for this tenant (e.g., campus1.thaibagarden.edu)</p>
                        </div>

                        <div className="mb-6">
                            <label className="block text-foreground/30 text-sm font-bold mb-2" htmlFor="settings">
                                Settings (JSON)
                            </label>
                            <textarea
                                id="settings"
                                value={tenantForm.settings}
                                onChange={(e) => setTenantForm({ ...tenantForm, settings: e.target.value })}
                                className="shadow appearance-none border rounded w-full py-2 px-3 text-foreground/30 leading-tight focus:outline-none focus:shadow-outline"
                                rows={4}
                                placeholder='{"branding": {"primaryColor": "#007bff"}, "features": {"notifications": true}}'
                            />
                        </div>

                        <div className="flex items-center justify-between">
                            <button
                                type="button"
                                onClick={resetForm}
                                className="bg-gray-500 hover:bg-gray-700 text-foreground font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                className="bg-blue-500 hover:bg-blue-700 text-foreground font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
                            >
                                {editingTenant ? 'Update Tenant' : 'Create Tenant'}
                            </button>
                        </div>
                    </form>
                </div>
            )}

            <div className="bg-white shadow-md rounded">
                <table className="min-w-full">
                    <thead>
                        <tr>
                            <th className="px-6 py-3 border-b border-gray-200 bg-gray-50 text-left text-xs leading-4 font-medium text-foreground/50 uppercase tracking-wider">
                                Name
                            </th>
                            <th className="px-6 py-3 border-b border-gray-200 bg-gray-50 text-left text-xs leading-4 font-medium text-foreground/50 uppercase tracking-wider">
                                Domain
                            </th>
                            <th className="px-6 py-3 border-b border-gray-200 bg-gray-50 text-left text-xs leading-4 font-medium text-foreground/50 uppercase tracking-wider">
                                Created
                            </th>
                            <th className="px-6 py-3 border-b border-gray-200 bg-gray-50 text-left text-xs leading-4 font-medium text-foreground/50 uppercase tracking-wider">
                                Actions
                            </th>
                        </tr>
                    </thead>
                    <tbody>
                        {tenants.map((tenant) => (
                            <tr key={tenant.id}>
                                <td className="px-6 py-4 whitespace-no-wrap border-b border-gray-200">
                                    <div className="text-sm leading-5 font-medium text-foreground/20">{tenant.name}</div>
                                </td>
                                <td className="px-6 py-4 whitespace-no-wrap border-b border-gray-200">
                                    <div className="text-sm leading-5 text-foreground/20">{tenant.domain}</div>
                                </td>
                                <td className="px-6 py-4 whitespace-no-wrap border-b border-gray-200 text-sm leading-5 text-foreground/50">
                                    {new Date(tenant.created_at).toLocaleDateString()}
                                </td>
                                <td className="px-6 py-4 whitespace-no-wrap border-b border-gray-200 text-sm leading-5 font-medium">
                                    <button
                                        onClick={() => editTenant(tenant)}
                                        className="text-blue-600 hover:text-blue-900 mr-3"
                                    >
                                        Edit
                                    </button>
                                    <button
                                        onClick={() => deleteTenant(tenant.id)}
                                        className="text-red-600 hover:text-red-900"
                                    >
                                        Delete
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                {tenants.length === 0 && (
                    <div className="text-center py-8">
                        <p className="text-foreground/50">No tenants found.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { PageLayout } from "@/components/ui/layout/PageLayout";
import { PageHeader } from "@/components/ui/layout/PageHeader";
import { UserService, User } from '@/services/userService';
import { AdminService } from '@/services/adminService';
import { StructureService } from '@/services/structureService';
import { Institution } from '@/types/structure';
import { 
    Search, 
    Loader2, 
    Users, 
    Shield, 
    Building2, 
    Mail, 
    Plus, 
    Trash2,
    ShieldCheck,
    UserCircle,
    ChevronRight,
    MapPin,
    AlertTriangle
} from 'lucide-react';
import { toast } from 'sonner';
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { cn } from "@/lib/utils";
import { motion, AnimatePresence } from 'framer-motion';
import { InviteUserModal } from '@/components/admin/users/InviteUserModal';
import { ConfirmationDialog } from "@/components/ui/ConfirmationDialog";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { useRouter } from 'next/navigation';
import { usePermissions } from '@/hooks/usePermissions';
import { useAuth } from '@/contexts/AuthContextProvider';
import { 
    Command,
    CommandInput,
    CommandList,
    CommandEmpty,
    CommandGroup,
    CommandItem
} from "@/components/ui/command";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
} from "@/components/ui/dialog";

export default function AdminUsersPage() {
    const router = useRouter();
    const { user, authResolved } = useAuth();
    const { role: currentRole } = usePermissions();
    
    // Check if user has global admin role or workspace admin role
    const isAdmin = user?.role === 'admin' || currentRole === 'admin';

    useEffect(() => {
        if (authResolved && !isAdmin) {
            router.push('/home');
        }
    }, [isAdmin, authResolved, router]);

    if (!authResolved || !isAdmin) return null;

    const [viewMode, setViewMode] = useState<'users' | 'invites'>('users');
    const [users, setUsers] = useState<User[]>([]);
    const [invites, setInvites] = useState<any[]>([]);
    const [institutions, setInstitutions] = useState<Institution[]>([]);
    const [departments, setDepartments] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isAddWorkspaceOpen, setIsAddWorkspaceOpen] = useState(false);
    const [search, setSearch] = useState('');
    const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
    const [selectedInviteId, setSelectedInviteId] = useState<string | null>(null);
    const [workspaceAccess, setWorkspaceAccess] = useState<any[]>([]);
    const [loadingAccess, setLoadingAccess] = useState(false);
    const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);

    // Confirmation Dialog State
    const [confirmConfig, setConfirmConfig] = useState<{
        open: boolean;
        title: string;
        description: string;
        action: () => void | Promise<void>;
        variant?: 'danger' | 'primary';
    }>({
        open: false,
        title: '',
        description: '',
        action: () => { },
    });

    const selectedUser = users.find(u => u.uid === selectedUserId);
    const selectedInvite = invites.find(i => i.id === selectedInviteId);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [usersData, instData, inviteData, deptData] = await Promise.all([
                UserService.getAllUsers(),
                StructureService.getInstitutions(),
                AdminService.getInvitations(),
                StructureService.getDepartments()
            ]);
            setUsers(usersData);
            setInstitutions(instData.institutions || []);
            setInvites(inviteData);
            setDepartments(deptData.departments || []);
            
            if (viewMode === 'users' && usersData.length > 0 && (!selectedUserId || !usersData.find(u => u.uid === selectedUserId))) {
                setSelectedUserId(usersData[0].uid);
            } else if (viewMode === 'invites' && inviteData.length > 0 && (!selectedInviteId || !inviteData.find(i => i.id === selectedInviteId))) {
                setSelectedInviteId(inviteData[0].id);
            }
        } catch (error) {
            toast.error("Failed to load data");
        } finally {
            setLoading(false);
        }
    };

    const fetchAccess = async (uid: string) => {
        setLoadingAccess(true);
        try {
            const access = await AdminService.getUserWorkspaceAccess(uid);
            setWorkspaceAccess(access);
        } catch (error) {
            toast.error("Failed to load access details");
        } finally {
            setLoadingAccess(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, [viewMode]);

    useEffect(() => {
        if (selectedUserId && viewMode === 'users') {
            fetchAccess(selectedUserId);
        }
    }, [selectedUserId, viewMode]);

    const filteredUsers = users.filter(u =>
        (u.name?.toLowerCase().includes(search.toLowerCase())) ||
        (u.email?.toLowerCase().includes(search.toLowerCase()))
    );

    const handleUpdateRole = async (instId: string, newRole: string) => {
        if (!selectedUserId || !selectedUser) return;
        
        const inst = institutions.find(i => i.id === instId);
        
        setConfirmConfig({
            open: true,
            title: "Confirm Role Change",
            description: `Are you sure you want to change ${selectedUser.name}'s role to ${newRole.toUpperCase()} in ${inst?.name || instId}? This will immediately update their access level.`,
            variant: 'primary',
            action: async () => {
                try {
                    await AdminService.setUserWorkspaceRole(selectedUserId, instId, newRole);
                    toast.success("Workspace role updated");
                    fetchAccess(selectedUserId);
                } catch (error) {
                    toast.error("Update failed");
                }
            }
        });
    };

    const handleRemoveDepartment = async () => {
        if (!selectedUserId || !selectedUser) return;
        
        setConfirmConfig({
            open: true,
            title: "Remove Department Access",
            description: `Are you sure you want to remove ${selectedUser.name} from the ${departments.find(d => String(d.id) === String(selectedUser.department_id))?.name || 'current'} department?`,
            variant: 'danger',
            action: async () => {
                try {
                    await UserService.updateUser(selectedUserId, { department_id: null as any });
                    toast.success("Department access removed");
                    fetchData();
                } catch (error) {
                    toast.error("Failed to remove department");
                }
            }
        });
    };

    const handleRemoveAccess = async (instId: string) => {
        if (!selectedUserId || !selectedUser) return;
        
        const inst = institutions.find(i => i.id === instId);

        setConfirmConfig({
            open: true,
            title: "Revoke Workspace Access",
            description: `Are you sure you want to completely remove ${selectedUser.name}'s access to ${inst?.name || instId}? They will no longer be able to see or interact with this workspace.`,
            variant: 'danger',
            action: async () => {
                try {
                    await AdminService.removeUserWorkspaceAccess(selectedUserId, instId);
                    toast.success("Access revoked");
                    fetchAccess(selectedUserId);
                } catch (error) {
                    toast.error("Action failed");
                }
            }
        });
    };

    const handleUpdateGlobalRole = async (newRole: string) => {
        if (!selectedUserId || !selectedUser) return;
        
        setConfirmConfig({
            open: true,
            title: "Change Global Role",
            description: `Are you sure you want to change ${selectedUser.name}'s global role to ${newRole.toUpperCase()}? This affects their base access level across the entire platform.`,
            variant: 'primary',
            action: async () => {
                try {
                    await UserService.updateUser(selectedUserId, { role: newRole as any });
                    toast.success("Global role updated");
                    fetchData(); // Refresh list to update role label
                } catch (error) {
                    toast.error("Update failed");
                }
            }
        });
    };

    const handleDeactivate = async () => {
        if (!selectedUser) return;
        
        setConfirmConfig({
            open: true,
            title: "Deactivate User Account",
            description: `Are you sure you want to deactivate ${selectedUser.name}'s global account? They will be locked out of the entire platform until reactivated.`,
            variant: 'danger',
            action: async () => {
                toast.info("Deactivation service not yet fully linked. Pending backend update.");
            }
        });
    };

    const handleAddAccess = (id: string, type: 'institution' | 'department') => {
        if (!id || !selectedUserId) return;
        
        setIsAddWorkspaceOpen(false);

        const action = type === 'institution' 
            ? AdminService.setUserWorkspaceRole(selectedUserId, id, 'member')
            : UserService.updateUser(selectedUserId, { department_id: Number(id) as any });

        toast.promise(
            action,
            {
                loading: `Adding ${type}...`,
                success: () => {
                    if (type === 'institution') fetchAccess(selectedUserId);
                    else fetchData();
                    return `${type === 'institution' ? 'Workspace' : 'Department'} access granted`;
                },
                error: `Failed to add ${type}`
            }
        );
    };

    const filteredInvites = invites.filter(i =>
        i.email?.toLowerCase().includes(search.toLowerCase())
    );

    const handleCancelInvite = async (id: string) => {
        const invite = invites.find(i => i.id === id);
        setConfirmConfig({
            open: true,
            title: "Cancel Invitation",
            description: `Are you sure you want to cancel the invitation for ${invite?.email || 'this user'}? The link will be immediately invalidated.`,
            variant: 'danger',
            action: async () => {
                try {
                    await AdminService.cancelInvitation(id);
                    toast.success("Invitation cancelled");
                    fetchData();
                } catch (error) {
                    toast.error("Failed to cancel invitation");
                }
            }
        });
    };

    return (
        <PageLayout mode="plain">
            <PageHeader
                title="User Management"
                description="Control global access and institutional permissions."
                actions={
                    <button 
                        onClick={() => setIsInviteModalOpen(true)}
                        className="h-10 px-6 rounded-full bg-primary text-primary-foreground text-sm font-bold flex items-center gap-2 hover:bg-primary/90 transition-all duration-200 active:scale-95 shadow-lg shadow-primary/20"
                    >
                        <Plus size={16} /> Invite User
                    </button>
                }
            />

            <div className="flex flex-col lg:flex-row gap-8 h-auto lg:h-[calc(100vh-16rem)] min-h-[500px]">
                {/* Left Panel: User List / Invite List */}
                <div className="w-full lg:w-[380px] flex flex-col gap-4">
                    <div className="flex bg-foreground/[0.03] p-1 rounded-full border border-foreground/10 backdrop-blur-md">
                        <button 
                            onClick={() => setViewMode('users')}
                            className={cn(
                                "flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-full transition-all border border-transparent",
                                viewMode === 'users' 
                                    ? "bg-primary/10 text-primary border-primary/20 shadow-sm" 
                                    : "text-foreground/60 hover:text-foreground/90 hover:bg-foreground/5"
                            )}
                        >
                            Active Users
                        </button>
                        <button 
                            onClick={() => setViewMode('invites')}
                            className={cn(
                                "flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-full transition-all relative border border-transparent",
                                viewMode === 'invites' 
                                    ? "bg-primary/10 text-primary border-primary/20 shadow-sm" 
                                    : "text-foreground/60 hover:text-foreground/90 hover:bg-foreground/5"
                            )}
                        >
                            Invitations
                            {invites.filter(i => i.status === 'pending').length > 0 && (
                                <span className="absolute top-2.5 right-4 w-1.5 h-1.5 bg-primary rounded-full animate-pulse shadow-[0_0_8px_var(--accent-primary)]" />
                            )}
                        </button>
                    </div>

                    <div className="relative">
                        <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-foreground/40" size={16} />
                        <input
                            placeholder={viewMode === 'users' ? "Search users..." : "Search invites..."}
                            className="w-full h-11 pl-10 pr-4 bg-foreground/[0.03] border border-foreground/10 rounded-full text-sm text-foreground placeholder:text-foreground/40 focus:outline-none focus:border-primary transition-all"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>

                    <div className="flex-1 overflow-y-auto pr-2 space-y-2 no-scrollbar max-h-[400px] lg:max-h-none">
                        {loading ? (
                            <div className="flex justify-center py-12"><Loader2 className="animate-spin text-foreground/80" /></div>
                        ) : viewMode === 'users' ? (
                            filteredUsers.map(user => (
                                <button
                                    key={user.uid}
                                    onClick={() => setSelectedUserId(user.uid)}
                                    className={cn(
                                        "w-full p-4 rounded-3xl flex items-center gap-4 border transition-all text-left group",
                                        selectedUserId === user.uid 
                                            ? "bg-foreground/10 border-foreground/10 shadow-lg" 
                                            : "bg-transparent border-transparent hover:bg-foreground/5"
                                    )}
                                >
                                    <Avatar className="h-10 w-10 border border-foreground/10">
                                        <AvatarImage src={user.avatar_url || user.photoURL} />
                                        <AvatarFallback className="bg-indigo-500/10 text-indigo-400 font-bold">
                                            {user.name?.[0] || 'U'}
                                        </AvatarFallback>
                                    </Avatar>
                                    <div className="flex-1 min-w-0">
                                        <h4 className={cn("text-sm font-bold truncate", selectedUserId === user.uid ? "text-foreground" : "text-foreground/80")}>
                                            {user.name || 'Anonymous'}
                                        </h4>
                                        <p className="text-[10px] text-foreground/70 font-medium truncate uppercase tracking-widest">
                                            {user.role} • {user.email}
                                        </p>
                                    </div>
                                    <ChevronRight size={14} className={cn("transition-transform", selectedUserId === user.uid ? "text-indigo-400 translate-x-0" : "text-foreground/70 -translate-x-2 opacity-0 group-hover:opacity-100 group-hover:translate-x-0")} />
                                </button>
                            ))
                        ) : (
                            filteredInvites.map(invite => (
                                <button
                                    key={invite.id}
                                    onClick={() => setSelectedInviteId(invite.id)}
                                    className={cn(
                                        "w-full p-4 rounded-3xl flex items-center gap-4 border transition-all text-left group",
                                        selectedInviteId === invite.id 
                                            ? "bg-foreground/10 border-foreground/10 shadow-lg" 
                                            : "bg-transparent border-transparent hover:bg-foreground/5"
                                    )}
                                >
                                    <div className={cn(
                                        "w-10 h-10 rounded-2xl flex items-center justify-center transition-colors",
                                        invite.status === 'accepted' ? "bg-emerald-500/10 text-emerald-400" :
                                        invite.status === 'expired' ? "bg-rose-500/10 text-rose-400" :
                                        "bg-blue-500/10 text-blue-400"
                                    )}>
                                        <Mail size={18} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h4 className={cn("text-sm font-bold truncate", selectedInviteId === invite.id ? "text-foreground" : "text-foreground/80")}>
                                            {invite.email}
                                        </h4>
                                        <div className="flex items-center gap-2">
                                            <span className={cn(
                                                "text-[8px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded",
                                                invite.status === 'accepted' ? "bg-emerald-500/20 text-emerald-400" :
                                                invite.status === 'expired' ? "bg-rose-500/20 text-rose-400" :
                                                "bg-blue-500/20 text-blue-400"
                                            )}>
                                                {invite.status}
                                            </span>
                                            <p className="text-[9px] text-foreground/80 font-medium truncate uppercase tracking-widest">
                                                {new Date(invite.created_at).toLocaleDateString()}
                                            </p>
                                        </div>
                                    </div>
                                    <ChevronRight size={14} className={cn("transition-transform", selectedInviteId === invite.id ? "text-indigo-400 translate-x-0" : "text-foreground/70 -translate-x-2 opacity-0 group-hover:opacity-100 group-hover:translate-x-0")} />
                                </button>
                            ))
                        )}
                    </div>
                </div>

                {/* Right Panel: Detail View */}
                <div className="flex-1 flex flex-col rounded-[40px] glass-liquid border-foreground/5 overflow-hidden min-h-[600px] lg:min-h-0">
                    <AnimatePresence mode="wait">
                        {viewMode === 'users' && selectedUserId && selectedUser ? (
                            <motion.div 
                                key={`user-${selectedUserId}`}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="flex-1 flex flex-col p-8 overflow-y-auto no-scrollbar"
                            >
                                {/* Header Info */}
                                <div className="flex items-start justify-between mb-8">
                                    <div className="flex items-center gap-6">
                                        <div className="relative">
                                            <Avatar className="h-24 w-24 border-2 border-foreground/10 shadow-2xl">
                                                <AvatarImage src={selectedUser.avatar_url || selectedUser.photoURL} />
                                                <AvatarFallback className="text-3xl font-black bg-indigo-500/10 text-indigo-400">
                                                    {selectedUser.name?.[0]}
                                                </AvatarFallback>
                                            </Avatar>
                                            <div className="absolute -bottom-1 -right-1 w-8 h-8 rounded-xl bg-indigo-500 flex items-center justify-center text-foreground shadow-lg border-4 border-background">
                                                <ShieldCheck size={16} />
                                            </div>
                                        </div>
                                        <div>
                                            <h2 className="text-2xl font-black text-foreground tracking-tight mb-1">{selectedUser.name}</h2>
                                            <div className="flex flex-wrap gap-3">
                                                <div className="px-3 py-1 rounded-lg bg-foreground/5 border border-foreground/5 flex items-center gap-2 text-[10px] font-black text-foreground/80 uppercase tracking-widest">
                                                    <Mail size={12} /> {selectedUser.email}
                                                </div>
                                                <DropdownMenu>
                                                    <DropdownMenuTrigger asChild>
                                                        <button className="px-3 py-1 rounded-lg bg-indigo-500/10 border border-indigo-500/20 flex items-center gap-2 text-[10px] font-black text-indigo-400 uppercase tracking-widest hover:bg-indigo-500/20 transition-colors">
                                                            <Shield size={12} /> Global {selectedUser.role}
                                                        </button>
                                                    </DropdownMenuTrigger>
                                                    <DropdownMenuContent align="start" className="bg-popover border-border text-foreground min-w-[140px]">
                                                        {['admin', 'manager', 'team', 'member'].map((r) => (
                                                            <DropdownMenuItem 
                                                                key={r}
                                                                onClick={() => handleUpdateGlobalRole(r)}
                                                                className={cn(
                                                                    "text-[10px] font-black uppercase tracking-widest cursor-pointer",
                                                                    selectedUser.role === r ? "text-indigo-400 bg-indigo-500/10" : "text-foreground/80"
                                                                )}
                                                            >
                                                                {r}
                                                            </DropdownMenuItem>
                                                        ))}
                                                    </DropdownMenuContent>
                                                </DropdownMenu>

                                                {selectedUser.department_id && (
                                                    <div className="px-3 py-1 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center gap-2 text-[10px] font-black text-emerald-400 uppercase tracking-widest">
                                                        <MapPin size={12} /> {departments.find(d => String(d.id) === String(selectedUser.department_id))?.name || 'Department'}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <button 
                                            onClick={handleDeactivate}
                                            className="h-10 px-4 rounded-xl border border-foreground/10 text-xs font-bold text-foreground/80 hover:bg-foreground/5 transition-colors"
                                        >
                                            Deactivate
                                        </button>
                                        <button 
                                            onClick={() => {
                                                if (!selectedUser) return;
                                                setConfirmConfig({
                                                    open: true,
                                                    title: "Permanently Delete User",
                                                    description: `Are you sure you want to permanently delete ${selectedUser.name}? This action is IRREVERSIBLE and will remove all their data from the system.`,
                                                    variant: 'danger',
                                                    action: async () => {
                                                        try {
                                                            await AdminService.deleteUser(selectedUser.uid);
                                                            toast.success("User permanently deleted");
                                                            setSelectedUserId(null);
                                                            fetchData();
                                                        } catch (error: any) {
                                                            toast.error(error.message || "Deletion failed");
                                                        }
                                                    }
                                                });
                                            }}
                                            className="h-10 w-10 rounded-xl border border-rose-500/20 text-rose-400 flex items-center justify-center hover:bg-rose-500/10 transition-colors"
                                        >
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>

                                {/* Workspace Access Section */}
                                <div className="space-y-6">
                                    <div className="flex items-center justify-between">
                                        <h3 className="text-sm font-black text-foreground/80 uppercase tracking-widest flex items-center gap-2">
                                            <Building2 size={14} /> Workspace Access Control
                                        </h3>
                                        <button 
                                            onClick={() => setIsAddWorkspaceOpen(true)}
                                            className="text-[10px] font-bold text-indigo-400 hover:text-indigo-300 transition-colors uppercase tracking-widest flex items-center gap-1"
                                        >
                                            <Plus size={12} /> Add Workspace
                                        </button>
                                    </div>

                                    <div className="space-y-3">
                                        {loadingAccess ? (
                                            <div className="py-12 flex justify-center"><Loader2 className="animate-spin text-foreground/70" /></div>
                                        ) : (workspaceAccess.length === 0 && !selectedUser.department_id) ? (
                                            <div className="p-12 rounded-[32px] border-2 border-dashed border-foreground/5 flex flex-col items-center justify-center text-center">
                                                <MapPin className="text-foreground/70 mb-4" size={40} />
                                                <p className="text-sm font-bold text-foreground/80">No access granted</p>
                                                <p className="text-xs text-foreground/80 mt-1">This user can only access global resources.</p>
                                            </div>
                                        ) : (
                                            <>
                                                {/* Department Access */}
                                                {selectedUser.department_id && (
                                                    <div className="p-5 rounded-[28px] bg-emerald-500/5 border border-emerald-500/10 flex items-center justify-between group hover:bg-emerald-500/10 transition-all">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-400">
                                                                <MapPin size={18} />
                                                            </div>
                                                            <div>
                                                                <h4 className="text-sm font-bold text-foreground">
                                                                    {departments.find(d => String(d.id) === String(selectedUser.department_id))?.name || 'Unknown Department'}
                                                                </h4>
                                                                <p className="text-[10px] text-emerald-400/40 font-medium uppercase tracking-widest">Primary Department</p>
                                                            </div>
                                                        </div>

                                                        <div className="flex items-center gap-4">
                                                            <div className="px-3 py-1.5 rounded-lg bg-emerald-500 text-foreground text-[10px] font-black uppercase tracking-widest shadow-lg">
                                                                Assignee
                                                            </div>
                                                            <button 
                                                                onClick={handleRemoveDepartment}
                                                                className="w-8 h-8 rounded-lg text-foreground/70 hover:text-rose-400 hover:bg-rose-500/10 flex items-center justify-center transition-all"
                                                            >
                                                                <Trash2 size={14} />
                                                            </button>
                                                        </div>
                                                    </div>
                                                )}

                                                {/* Institution Access */}
                                                {workspaceAccess.map(access => (
                                                    <div key={access.id} className="p-5 rounded-[28px] bg-foreground/5 border border-foreground/5 flex items-center justify-between group hover:bg-foreground/[0.07] transition-all">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-400">
                                                                <Building2 size={18} />
                                                            </div>
                                                            <div>
                                                                <h4 className="text-sm font-bold text-foreground">{access.institutions?.name}</h4>
                                                                <p className="text-[10px] text-foreground/80 font-medium uppercase tracking-widest">Workspace Access</p>
                                                            </div>
                                                        </div>

                                                        <div className="flex items-center gap-4">
                                                            <div className="flex bg-foreground/[0.03] p-1 rounded-full border border-foreground/10 backdrop-blur-md">
                                                                {['admin', 'manager', 'team', 'member'].map(r => (
                                                                    <button
                                                                        key={r}
                                                                        onClick={() => handleUpdateRole(access.institution_id, r)}
                                                                        className={cn(
                                                                            "px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all border border-transparent",
                                                                            access.role === r 
                                                                                ? "bg-primary/10 text-primary border-primary/20 shadow-sm" 
                                                                                : "text-foreground/60 hover:text-foreground/80 hover:bg-foreground/5"
                                                                        )}
                                                                    >
                                                                        {r}
                                                                    </button>
                                                                ))}
                                                            </div>
                                                            <button 
                                                                onClick={() => handleRemoveAccess(access.institution_id)}
                                                                className="w-8 h-8 rounded-lg text-foreground/70 hover:text-rose-400 hover:bg-rose-500/10 flex items-center justify-center transition-all"
                                                            >
                                                                <Trash2 size={14} />
                                                            </button>
                                                        </div>
                                                    </div>
                                                ))}
                                            </>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        ) : viewMode === 'invites' && selectedInviteId && selectedInvite ? (
                            <motion.div 
                                key={`invite-${selectedInviteId}`}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="flex-1 flex flex-col p-8 overflow-y-auto no-scrollbar"
                            >
                                <div className="flex items-start justify-between mb-8">
                                    <div className="flex items-center gap-6">
                                        <div className="w-20 h-20 rounded-3xl bg-blue-500/10 border border-blue-500/20 flex items-center justify-center text-blue-400">
                                            <Mail size={40} />
                                        </div>
                                        <div>
                                            <h2 className="text-2xl font-black text-foreground tracking-tight mb-1">{selectedInvite.email}</h2>
                                            <div className="flex flex-wrap gap-3">
                                                <div className={cn(
                                                    "px-3 py-1 rounded-lg border flex items-center gap-2 text-[10px] font-black uppercase tracking-widest",
                                                    selectedInvite.status === 'accepted' ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-400" :
                                                    selectedInvite.status === 'expired' ? "bg-rose-500/10 border-rose-500/20 text-rose-400" :
                                                    "bg-blue-500/10 border-blue-500/20 text-blue-400"
                                                )}>
                                                    {selectedInvite.status}
                                                </div>
                                                <div className="px-3 py-1 rounded-lg bg-foreground/5 border border-foreground/5 flex items-center gap-2 text-[10px] font-black text-foreground/80 uppercase tracking-widest">
                                                    Expires: {new Date(selectedInvite.expires_at).toLocaleDateString()}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        {selectedInvite.status !== 'accepted' && (
                                            <button 
                                                onClick={() => handleCancelInvite(selectedInvite.id)}
                                                className="h-10 px-4 rounded-xl border border-rose-500/20 text-rose-400 hover:bg-rose-500/10 transition-colors text-xs font-bold"
                                            >
                                                Cancel Invite
                                            </button>
                                        )}
                                    </div>
                                </div>

                                <div className="space-y-6">
                                    <h3 className="text-sm font-black text-foreground/80 uppercase tracking-widest flex items-center gap-2">
                                        <Building2 size={14} /> Invited Workspace Access
                                    </h3>
                                    
                                    <div className="space-y-3">
                                        {Object.entries(selectedInvite.metadata?.invited_workspaces || {}).map(([id, role]: [any, any]) => {
                                            const inst = institutions.find(i => i.id === id);
                                            return (
                                                <div key={id} className="p-4 rounded-2xl bg-foreground/[0.03] border border-foreground/5 flex items-center justify-between">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-8 h-8 rounded-lg bg-foreground/5 flex items-center justify-center text-foreground/80">
                                                            <Building2 size={16} />
                                                        </div>
                                                        <div>
                                                            <p className="text-xs font-bold text-foreground">{inst?.name || 'Unknown Workspace'}</p>
                                                            <p className="text-[9px] text-foreground/70 uppercase tracking-widest font-black">{id}</p>
                                                        </div>
                                                    </div>
                                                    <div className="px-3 py-1 rounded-lg bg-blue-500/10 text-blue-400 text-[10px] font-black uppercase tracking-widest">
                                                        {role}
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>

                                    <div className="p-6 rounded-[32px] bg-indigo-500/5 border border-indigo-500/10 space-y-4">
                                        <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Invitation Link</p>
                                        <div className="flex gap-2">
                                            <input 
                                                readOnly
                                                value={`${window.location.origin}/accept-invite?token=${selectedInvite.token}`}
                                                className="flex-1 bg-black/40 border border-foreground/5 rounded-xl px-4 py-2 text-xs text-foreground/80 focus:outline-none"
                                            />
                                            <button 
                                                onClick={() => {
                                                    navigator.clipboard.writeText(`${window.location.origin}/accept-invite?token=${selectedInvite.token}`);
                                                    toast.success("Link copied to clipboard");
                                                }}
                                                className="px-4 bg-indigo-500 hover:bg-indigo-400 text-foreground rounded-xl text-xs font-bold transition-colors"
                                            >
                                                Copy
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        ) : (
                            <div className="flex-1 flex flex-col items-center justify-center text-center p-12">
                                <UserCircle size={64} className="text-foreground/5 mb-6" />
                                <h3 className="text-xl font-black text-foreground/80 uppercase tracking-tighter">
                                    {viewMode === 'users' ? 'Select a user to manage' : 'Select an invitation to track'}
                                </h3>
                                <p className="text-sm text-foreground/70 mt-2 max-w-xs">
                                    {viewMode === 'users' 
                                        ? 'Adjust global roles or assign specific institutional permissions.'
                                        : 'View pending access requests and copy secure invitation links.'}
                                </p>
                            </div>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            <InviteUserModal 
                isOpen={isInviteModalOpen}
                onClose={() => setIsInviteModalOpen(false)}
                onSuccess={fetchData}
            />

            <ConfirmationDialog 
                open={confirmConfig.open}
                onOpenChange={(open) => setConfirmConfig(prev => ({ ...prev, open }))}
                title={confirmConfig.title}
                description={confirmConfig.description}
                variant={confirmConfig.variant}
                onConfirm={confirmConfig.action}
            />
            <Dialog open={isAddWorkspaceOpen} onOpenChange={setIsAddWorkspaceOpen}>
                <DialogContent className="p-0 bg-background border-border overflow-hidden max-w-md shadow-2xl">
                    <DialogHeader className="p-6 pb-2">
                        <DialogTitle className="text-foreground text-xl font-black uppercase tracking-widest">Add Workspace</DialogTitle>
                        <DialogDescription className="text-foreground/80 text-xs font-medium uppercase tracking-widest">Select an institution to grant access.</DialogDescription>
                    </DialogHeader>
                    
                    <Command className="bg-transparent border-none">
                        <CommandInput 
                            placeholder="Search workspaces..." 
                            className="text-foreground border-foreground/5 h-14"
                        />
                        <CommandList className="max-h-[400px] border-foreground/5 scrollbar-thin scrollbar-thumb-white/10">
                            <CommandEmpty className="py-10 text-foreground/80 text-[10px] uppercase tracking-widest font-black text-center">No workspaces found.</CommandEmpty>
                            
                            <CommandGroup heading="Departments" className="px-2 pb-2 text-[10px] font-black uppercase tracking-widest text-emerald-400/40">
                                {departments
                                    .filter(dept => !selectedUser || String(dept.id) !== String(selectedUser.department_id))
                                    .map(dept => (
                                        <CommandItem
                                            key={dept.id}
                                            onSelect={() => handleAddAccess(String(dept.id), 'department')}
                                            className="flex flex-col items-start gap-1 py-3 px-4 rounded-xl data-[selected=true]:bg-emerald-500/10 cursor-pointer transition-all"
                                        >
                                            <span className="text-sm font-bold text-foreground tracking-tight">{dept.name}</span>
                                            <span className="text-[9px] text-emerald-400/40 font-medium uppercase tracking-widest">Organizational Unit</span>
                                        </CommandItem>
                                    ))}
                            </CommandGroup>

                            <CommandGroup heading="Institutions" className="px-2 pb-4 text-[10px] font-black uppercase tracking-widest text-indigo-400/40 border-t border-foreground/5 mt-2 pt-2">
                                {institutions
                                    .filter(inst => !workspaceAccess.some(acc => acc.institution_id === inst.id))
                                    .map(inst => (
                                        <CommandItem
                                            key={inst.id}
                                            onSelect={() => handleAddAccess(inst.id, 'institution')}
                                            className="flex flex-col items-start gap-1 py-3 px-4 rounded-xl data-[selected=true]:bg-indigo-500/10 cursor-pointer transition-all"
                                        >
                                            <span className="text-sm font-bold text-foreground tracking-tight">{inst.name}</span>
                                            <span className="text-[9px] text-indigo-400/40 font-medium uppercase tracking-widest">Physical Workspace</span>
                                        </CommandItem>
                                    ))}
                            </CommandGroup>
                        </CommandList>
                    </Command>
                </DialogContent>
            </Dialog>
        </PageLayout>
    );
}

