                        <TooltipProvider>
                            <div className="flex bg-foreground/[0.03] border border-foreground/10 rounded-full p-1 backdrop-blur-md shadow-2xl">
                                {(['month', 'week', 'timeline', 'list'] as const).map((mode) => {
                                    const { icon: Icon, label, tooltip } = {
                                        month: { icon: CalendarIcon, label: 'Month', tooltip: 'Monthly overview' },
                                        week: { icon: CalendarDays, label: 'Week', tooltip: 'Weekly schedule' },
                                        timeline: { icon: GitBranch, label: 'Timeline', tooltip: 'Chronological events' },
                                        list: { icon: List, label: 'List', tooltip: 'Event list' }
                                    }[mode];

                                    return (
                                        <Tooltip key={mode}>
                                            <TooltipTrigger asChild>
                                                <button
                                                    onClick={() => setViewMode(mode)}
                                                    className={cn(
                                                        "px-4 py-2 text-[10px] font-black uppercase tracking-[0.2em] rounded-full transition-all duration-200 flex items-center border border-transparent",
                                                        viewMode === mode ? "bg-primary/10 text-primary border-primary/20 shadow-sm shadow-primary/5" : "text-foreground/80 hover:text-foreground/75"
                                                    )}
                                                >
                                                    <Icon 
                                                        size={16} 
                                                        className={cn(
                                                            "mr-[6px] transition-all duration-200",
                                                            viewMode === mode ? "opacity-100 text-primary" : "opacity-60"
                                                        )} 
                                                    />
                                                    {label}
                                                </button>
                                            </TooltipTrigger>
                                            <TooltipContent side="bottom" sideOffset={8}>
                                                {tooltip}
                                            </TooltipContent>
                                        </Tooltip>
                                    );
                                })}
                            </div>
                        </TooltipProvider>
                        {canCreate && (
                            <Button
                                onClick={() => nativeNavigate('/events/new', router, 'Events (New)')}
                                className="bg-primary hover:opacity-90 text-foreground border-none shadow-lg shadow-primary/25 font-bold rounded-full"
                            >
                                <Plus size={16} className="mr-2" />
                                New Event
                            </Button>
                        )}
                    </div>
                }
            />

            {loading ? (
                <div className="flex items-center justify-center h-64">
                    <div className="text-foreground/70 animate-pulse font-mono text-xs">SYNCING EVENTS...</div>
                </div>
            ) : (
                <div className="mt-6">
                    {viewMode === 'month' && (
                        <CalendarView
                            events={events}
                            currentDate={currentDate}
                            onDateChange={setCurrentDate}
                            onDateClick={(date) => {
                                const isoDate = date.toISOString();
                                nativeNavigate(`/events/new?start_at=${isoDate}`, router, `CalendarCell:${isoDate}`);
                            }}
                            onDateRangeSelect={(start, end) => {
                                const startIso = start.toISOString();
                                const endIso = end.toISOString();
                                nativeNavigate(`/events/new?start_at=${startIso}&end_at=${endIso}`, router, `CalendarRange:${startIso}-${endIso}`);
                            }}
                            onEventClick={(event: any) => router.push(`/events/${event.id}`)}
                        />
                    )}

                    {viewMode === 'week' && (
                        <WeekTimelineView
                            events={events}
                            currentDate={currentDate}
                            onDateChange={setCurrentDate}
                            onEventClick={(event: any) => router.push(`/events/${event.id}`)}
                            onEventUpdate={async (id, updates) => {
                                try {
                                    await EventService.updateEvent(id, updates, user?.uid || '', undefined, undefined);
                                    // Subscription will handle the update in state
                                } catch (error) {
                                    console.error("Failed to update event via week timeline", error);
                                }
                            }}
                            onCreateEvent={(date, startTime, endTime) => {
                                // For week view, we might have specific times. Map them to start_at.
                                const isoDate = date.toISOString();
                                nativeNavigate(`/events/new?start_at=${isoDate}`, router, 'WeekTimeline:NewEvent');
                            }}
                            onRangeSelect={(start, end) => {
                                const startIso = start.toISOString();
                                const endIso = end.toISOString();
                                nativeNavigate(`/events/new?start_at=${startIso}&end_at=${endIso}`, router, `WeekTimeline:RangeSelect`);
                            }}
                        />
                    )}

                    {viewMode === 'timeline' && (
                        <TimelineView
                            events={timelineEvents}
                            tasks={tasks}
                            loading={loading}
                            onCreateEvent={() => nativeNavigate('/events/new', router, 'Events (New)')}
                            filter="all" // Default to showing all. Could add filter toggle if needed.
                        />
                    )}

                    {viewMode === 'list' && (
                        <EventListView
                            events={events}
                            onEventClick={(event: any) => router.push(`/events/${event.id}`)}
                        />
                    )}
                </div>
            )}

            {/* Modal removed from here as it's now handled by parallel routing and standalone pages */}
        </PageLayout>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { EventDetailsModal } from '@/components/events/EventDetailsModal';
import { EventService } from '@/features/events/services/eventService';
import { Event } from '@/features/events/types/event';
import { PageLayout } from '@/components/ui/layout/PageLayout';
import { toast } from 'sonner';

export default function EventStandalonePage() {
    const params = useParams();
    const router = useRouter();
    const id = params.id as string;
    const [event, setEvent] = useState<Event | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!id) return;

        const fetchEvent = async () => {
            try {
                const data = await EventService.getEventById(id);
                if (data) {
                    setEvent(data);
                } else {
                    toast.error("Event not found");
                    router.push('/events');
                }
            } catch (err) {
                console.error("Failed to fetch event for standalone page", err);
                toast.error("An error occurred while loading the event");
                router.push('/events');
            } finally {
                setLoading(false);
            }
        };

        fetchEvent();
    }, [id, router]);

    if (loading) {
        return (
            <PageLayout mode="plain">
                <div className="flex items-center justify-center min-h-[60vh]">
                    <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-primary"></div>
                </div>
            </PageLayout>
        );
    }

    if (!event) return null;

    return (
        <PageLayout mode="plain">
            <EventDetailsModal 
                event={event}
                isOpen={true}
                onClose={() => router.push('/events')}
                onEdit={() => router.push(`/events/edit?id=${event.id}`)}
            />
        </PageLayout>
    );
}

