    // Save persistence
    useEffect(() => {
        if (typeof window !== 'undefined' && formData.selectedInstitutionId) {
            sessionStorage.setItem('task-inst-pref', formData.selectedInstitutionId);
        }
        if (typeof window !== 'undefined' && formData.selectedDepartmentId) {
            sessionStorage.setItem('task-dept-pref', formData.selectedDepartmentId);
        }
    }, [formData.selectedInstitutionId, formData.selectedDepartmentId]);

    // Fetch Organizations
    useEffect(() => {
        const fetchOrgs = async () => {
            try {
                const [deptData, instData] = await Promise.all([
                    StructureService.getDepartments(),
                    StructureService.getInstitutions()
                ]);
                setDepartmentsList(deptData.departments);
                setInstitutionsList(instData.institutions);
            } catch (e) {
                console.error("Failed to fetch organizations", e);
            }
        };
        fetchOrgs();
    }, []);

    // Auto-fill from user defaults
    // We use a separate effect for this to ensure it runs when either User defaults exist OR when lists are loaded.
    // We explicitly check length inside to avoid adding the arrays themselves to the dependency list if they are causing strict mode issues,
    // though typically state arrays are stable. The error "changed size" suggests something else might be going on, 
    // so we will stringify the dependence or just use the length as a proxy for "loaded".
    useEffect(() => {
        if (departmentsList.length === 0 && institutionsList.length === 0) return;

        const userDeptId = user.department_id;
        const userInstId = user.institution_id;

        if (userDeptId && !formData.selectedDepartmentId) {
            const dept = departmentsList.find(d => String(d.id) === String(userDeptId));
            if (dept) setSelectedDepartmentId(String(dept.id));
        }

        if (userInstId && !formData.selectedInstitutionId) {
            const inst = institutionsList.find(i => String(i.id) === String(userInstId));
            if (inst) setSelectedInstitutionId(String(inst.id));
        }
    }, [user.department_id, user.institution_id, departmentsList.length, institutionsList.length]);

    // Role derived above to ensure consistency across the component lifecycle
    console.log("[TasksNew] User Role Detection (Active Context):", { role: currentRole, isAdmin, isTeam, isMember });

    // Fetch real team members from Firestore
    useEffect(() => {
        const fetchTeamMembers = async () => {
            // Use the user's current institution/workspace context, not the 'Requested By' selection.
            // This ensures you can always assign tasks to your own team members.
            const contextId = currentWorkspaceId;
            const members = await UserService.getTeamMembers(contextId, user.uid, { forceMediaIT: true });

            const isManagerLocal = currentRole?.toLowerCase() === 'manager';
            const isAdminLocal = currentRole?.toLowerCase() === 'admin';
            const isTeamLocal = currentRole?.toLowerCase() === 'team';
            const canAssignOthers = isAdminLocal || isManagerLocal;

            // Context-Aware Filter
            const filtered = members.filter(m => {
                const role = (m as any).role?.toLowerCase().trim();
                const isSelf = m.uid === user?.uid;
                const isMediaAdmin = m.name === 'Media Admin';
                
                // Allow standard operational roles for assignment
                const isValidRole = ['manager', 'team'].includes(role);

                if (!isValidRole || isMediaAdmin) return false;

                if (canAssignOthers) return true;
                if (isTeamLocal && isSelf) return true;
                
                return false;
            });
            
            setTeamMembers(filtered);
        };
        fetchTeamMembers();
    }, [user?.uid, currentWorkspaceId, selectedInstitutionId, selectedDepartmentId]);
    // ...
    // ...


    const submitTask = async () => {
        setError(null);
        
        // Comprehensive Validation Check
        if (!title.trim()) {
            throw new Error("Task title is required.");
        }
        if (!due_date) {
            throw new Error("Please select a due date.");
        }
        if (!formData.selectedInstitutionId && !formData.selectedDepartmentId) {
            throw new Error("Please select either an Institution or a Department.");
        }

        try {
            const { tenantId } = await tenantContext();
            let finalAssignedTo: { uid: string; name: string }[] = [];

            if (isAdmin || isTeam) {
                finalAssignedTo = assignedToIds.map(id => {
                    // Let's rely on finding them in the combined list or just constructing if we have info.
                    // Actually, earlier code had `mockMembers` error.
                    // We should use `teamMembers` + `user`.

                    const member = teamMembers.find(m => m.uid === id);
                    if (member) return { uid: member.uid, name: member.name };
                    return null;
                }).filter(Boolean) as { uid: string; name: string }[];

                // Fallback: If no one selected, assign to self
                if (finalAssignedTo.length === 0) {
                    finalAssignedTo = [{ uid: user.uid, name: user.name || 'Unknown' }];
                }
            }
            // Member: finalAssignedTo remains empty array (Admin assigns later)
 
            // Prepare On Behalf Of Data
            let onBehalfOfData = undefined;
            const userDeptId = user.department_id ? String(user.department_id) : null;
            const userInstId = user.institution_id ? String(user.institution_id) : null;
            
            if (formData.selectedInstitutionId !== userInstId || formData.selectedDepartmentId !== userDeptId) {
                const inst = institutionsList.find(i => String(i.id) === formData.selectedInstitutionId);
                const dept = departmentsList.find(d => String(d.id) === formData.selectedDepartmentId);
                onBehalfOfData = {
                    institution: inst ? { id: inst.id, name: inst.name } : null,
                    department: dept ? { id: dept.id, name: dept.name } : null
                };
            }
 
            // Resolve Structure IDs
            const institution_id = formData.selectedInstitutionId || null;
            const department_id = formData.selectedDepartmentId ? parseInt(formData.selectedDepartmentId) : null;
            const dept = departmentsList.find(d => String(d.id) === formData.selectedDepartmentId);
            const departmentName = dept ? dept.name : '';
 
            const newTaskData = {
                title,
                description,
                status: isMember ? 'pending' : 'todo',
                priority: isMember ? 'low' : priority,
                due_date: due_date ? (typeof due_date === 'string' ? new Date(due_date).toISOString() : (due_date as Date).toISOString()) : new Date().toISOString(),
                department: departmentName,
                department_id: department_id,
                institution_id: institution_id,
                tenant_id: tenantId,
                assigned_by: user.uid,
                created_by: user.uid,
                assigned_to: finalAssignedTo.length > 0 ? finalAssignedTo : undefined,
                campaign_id: campaign_id || undefined,
                on_behalf_of: onBehalfOfData,
                is_demo_data: is_demo_data
            };
 
            const { data: newTask, error: insertError } = await CanonicalDataService.createRecord('tasks', newTaskData, 'task');
            if (insertError) { 
                // In offline mode, createRecord might return data: null and error: null if enqueued
                // But we should check if it was actually enqueued. safeQuery returns { data: fallbackData, error: null }
                // if it's offline.
                if (!navigator.onLine) {
                    toast.info("Working offline. Task queued for sync.");
                } else {
                    throw new Error(insertError.message || "Failed to create task");
                }
            }
            
            const newTaskId = newTask?.id || uuidv4(); // Fallback ID for offline attachments if needed
 
            // Trigger Background Work (Notifications)
            // We do NOT await this to ensure the UI closes immediately as requested.
            // Trigger Background Work (Notifications) - Offloaded to macrotask
            if (isMember) {
                setTimeout(async () => {
                    try {
                        const { pushNotification } = await import('@/services/alertService');
                        const [admins, managers] = await Promise.all([
                            UserService.getAdmins(),
                            UserService.getManagers()
                        ]);

                        const recipients = [...admins, ...managers];

                        await Promise.all(recipients.map(recipient =>
                            pushNotification({
                                user_id: recipient.uid,
                                created_by: user.uid,
                                type: 'task_assigned',
                                title: 'Task Assignment Required',
                                body: `${user.official_name || user.name || 'A member'} has created "${title}" and a team member needs to be assigned to the task`,
                                entity_type: 'task',
                                entity_id: newTaskId,
                                action_url: `/tasks/view?id=${newTaskId}`,
                                priority: 'medium'
                            })
                        ));
                    } catch (e) {
                        console.error("[TasksNew] Background notification failed:", e);
                    }
                }, 0);
            }

            // Phase 28: Immediate Navigation for better UX
            // If no files, navigate NOW. Side effects (notifications) will finish in background.
            if (files.length === 0) {
                clearDraft();
                toast.success(COPY.toasts.taskCreated);
                const returnTo = searchParams.get('returnTo');
                if (returnTo === 'home') router.push('/home');
                else router.push('/tasks');
                return; // Early return to trigger onSuccess immediately
            }

            // Handle Attachments (We keep the user on page for these to ensure transfer completes)
            setUploadProgress(`0/${files.length}`);
            let uploadedCount = 0;
            let finalFiles = [];
            for (const file of files) {
                try {
                    const fileExt = file.name.split('.').pop();
                    const fileName = `${uuidv4()}.${fileExt}`;
                    const filePath = `${newTaskId}/${fileName}`;
                    await supabase.storage.from('task_attachments').upload(filePath, file);
                    const { data: publicUrlData } = supabase.storage.from('task_attachments').getPublicUrl(filePath);

                    finalFiles.push({
                        id: uuidv4(),
                        name: file.name,
                        mimeType: file.type,
                        size: file.size,
                        url: publicUrlData.publicUrl,
                        uploaded_by: { uid: user.uid, name: user.name, role: user.role },
                        uploaded_at: new Date().toISOString(),
                        section: 'requester-inputs'
                    });
                    uploadedCount++;
                    setUploadProgress(`${uploadedCount}/${files.length}`);
                } catch (e) {
                    console.error(`Failed to upload ${file.name}`, e);
                }
            }
            if (finalFiles.length > 0) {
                await supabase.from('tasks').update({ files: finalFiles }).eq('id', newTaskId);
            }
        } catch (err: any) {
            console.error("[TasksNew] Submission failed:", err);
            throw err; 
        }
    };
 
    const { isSubmitting, handleSubmit: handleProtectedSubmit } = useFormSubmit({
        onSubmit: submitTask,
        onSuccess: () => {
            clearDraft();
            toast.success(COPY.toasts.taskCreated);
            const returnTo = searchParams.get('returnTo');
            if (returnTo === 'home') router.push('/home');
            else router.push('/tasks');
        },
        onError: (err) => {
            setError(err.message || COPY.errors.generic);
        }
    });
 
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        await handleProtectedSubmit(undefined);
    };
 
    const handleRetry = async () => {
        await handleProtectedSubmit(undefined);
    };
 
    // Power User: Cmd/Ctrl + Enter to Submit
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
                e.preventDefault();
                handleProtectedSubmit(undefined);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);
 
    // Escape to Cancel (Task 79)
    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                const returnTo = searchParams.get('returnTo');
                if (returnTo === 'home') {
                    router.push('/home');
                } else {
                    router.push('/tasks');
                }
            }
        };
        window.addEventListener('keydown', handleEscape);
        return () => window.removeEventListener('keydown', handleEscape);
    }, [router, searchParams]);
 
    // Date Shortcuts (Task 75)
    useEffect(() => {
        const handleDateShortcut = (e: KeyboardEvent) => {
            if (e.altKey && (e.key === 'ArrowRight' || e.key === 'ArrowLeft')) {
                e.preventDefault(); // Prevent browser nav (Alt+Left is Back)
 
                const current = due_date ? new Date(due_date) : new Date();
                // If invalid date, start today
                if (isNaN(current.getTime())) {
                    setDueDate(new Date());
                    return;
                }
 
                // Add/Sub day
                const change = e.key === 'ArrowRight' ? 1 : -1;
                current.setDate(current.getDate() + change);
 
                setDueDate(current);
 
                // Quiet Feedback
                toast.dismiss(); // Prevent stacking
                toast(`Due: ${format(current, 'EEE, MMM d')}`, {
                    duration: 2000,
                    icon: '📅'
                });
            }
        };
        window.addEventListener('keydown', handleDateShortcut);
        return () => window.removeEventListener('keydown', handleDateShortcut);
    }, [due_date]);
 
    return (
        <PageLayout mode="plain">
            <div className="flex flex-col items-center">
                {/* Centered Card */}
                <div className="w-full max-w-xl">
                    <div className="glass-liquid rounded-[32px] p-6 sm:p-8 shadow-[0_32px_64px_-16px_rgba(0,0,0,0.8)] border border-foreground/5">
                        {/* Header */}
                        <div className="flex items-center justify-between mb-8 pb-4 border-b border-foreground/5">
                            <button
                                onClick={() => {
                                    const returnTo = searchParams.get('returnTo');
                                    if (returnTo === 'home') {
                                        router.push('/home');
                                    } else {
                                        router.push('/tasks');
                                    }
                                }}
                                className="text-red-400/80 font-medium hover:text-red-300 transition-colors text-sm hover:bg-foreground/5 px-3 py-1.5 rounded-full"
                            >
                                {COPY.actions.cancel}
                            </button>
                            <h1 className="text-lg font-bold text-foreground tracking-wide">New Task</h1>
                            <DraftIndicator isSaved={isDraftSaved} className="w-[80px] justify-end" />
                        </div>
 
                        {campaignName && (
                            <div className="mb-6 p-3 bg-blue-500/10 border border-blue-500/20 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
                                <div className="w-8 h-8 rounded-full bg-blue-500/20 flex items-center justify-center text-blue-400">
                                    <Building size={16} />
                                </div>
                                <div>
                                    <p className="text-xs text-blue-300 font-semibold uppercase tracking-wider">Attached to Campaign</p>
                                    <p className="text-sm text-foreground font-bold">{campaignName}</p>
                                </div>
                            </div>
                        )}
 
                        {/* Form */}
                        <form onSubmit={handleSubmit} className="relative">
                            <fieldset disabled={isSubmitting} className="space-y-6">
 
                            {/* Title & Desc Group */}
                            <div className="space-y-5">
                                <div className="space-y-2">
                                    <label className="block text-sm font-medium text-foreground/70 mb-2">Task Title</label>
                                    <input
                                        type="text"
                                        value={title}
                                        onChange={e => setTitle(e.target.value)}
                                        placeholder={COPY.placeholders.taskTitle}
                                        spellCheck={true}
                                        className="w-full bg-black/20 backdrop-blur-sm p-4 rounded-2xl border border-foreground/5 shadow-inner focus:bg-black/40 focus:ring-2 focus:ring-primary/30 focus:border-primary/50 outline-none transition-all placeholder:text-foreground/30 font-medium text-foreground text-lg"
                                    />
                                </div>
 
                                <div className="space-y-2">
                                    <label className="block text-sm font-medium text-foreground/70 mb-2">{COPY.labels.description}</label>
                                    <textarea
                                        value={description}
                                        onChange={e => setDescription(e.target.value)}
                                        placeholder={COPY.placeholders.taskDescription}
                                        rows={4}
                                        spellCheck={true}
                                        className="w-full bg-black/20 backdrop-blur-sm p-4 rounded-2xl border border-foreground/5 shadow-inner focus:bg-black/40 focus:ring-2 focus:ring-primary/30 focus:border-primary/50 outline-none transition-all placeholder:text-foreground/30 resize-none text-foreground/90 leading-relaxed"
                                        tabIndex={2}
                                    />
                                </div>
                            </div>
 
                            {/* Date \u0026 Department/Institution Grid */}
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2">
                                <div className="space-y-0.5">
                                    <DateSelector 
                                        label="Due Date"
                                        date={due_date}
                                        onChange={setDueDate}
                                    />
                                </div>
 
                                {/* Institution \u0026 Department Selectors */}
                                <div className="space-y-4 pt-2">
                                    {(formData.selectedInstitutionId || canCreateOnBehalf) && (
                                        <div className="space-y-2">
                                            <div className="flex items-center justify-between">
                                                <label className="block text-sm font-medium text-foreground/70">Institution</label>
                                                {canCreateOnBehalf && !formData.isDelegating && (
                                                    <button 
                                                        type="button"
                                                        onClick={() => setIsDelegating(true)}
                                                        className="text-[10px] uppercase tracking-wider text-blue-400/60 hover:text-blue-400 font-bold transition-colors"
                                                    >
                                                        Change Entity
                                                    </button>
                                                )}
                                            </div>
                                                <DropdownSelector 
                                                    label=""
                                                    value={formData.selectedInstitutionId}
                                                    onChange={(val) => {
                                                        setSelectedInstitutionId(val);
                                                        if (val) setSelectedDepartmentId(''); // Mutual Exclusivity
                                                    }}
                                                    options={[{id: '', label: 'None'}, ...institutionsList.map(inst => ({ id: String(inst.id), label: inst.name, icon: <Building size={14} /> }))]}
                                                    disabled={!formData.isDelegating}
                                                />
                                        </div>
                                    )}

                                    {(formData.selectedDepartmentId || canCreateOnBehalf) && (
                                        <div className="space-y-2">
                                            <label className="block text-sm font-medium text-foreground/70">Department</label>
                                            <DropdownSelector 
                                                label=""
                                                value={formData.selectedDepartmentId}
                                                onChange={(val) => {
                                                    setSelectedDepartmentId(val);
                                                    if (val) setSelectedInstitutionId(''); // Mutual Exclusivity
                                                }}
                                                options={[{id: '', label: 'None'}, ...departmentsList.map(dept => ({ id: String(dept.id), label: dept.name, icon: <Briefcase size={14} /> }))]}
                                                disabled={!formData.isDelegating}
                                            />
                                        </div>
                                    )}
                                    
                                    {formData.isDelegating && (
                                        <button 
                                            type="button"
                                            onClick={() => {
                                                setIsDelegating(false);
                                                setSelectedInstitutionId(String(user.institution_id || ''));
                                                setSelectedDepartmentId(String(user.department_id || ''));
                                            }}
                                            className="w-full py-2 text-[10px] uppercase tracking-wider text-blue-400/60 hover:text-blue-400 font-bold transition-colors text-center border border-dashed border-foreground/10 rounded-xl mt-2"
                                        >
                                            Reset to My Defaults
                                        </button>
                                    )}
                                </div>
                            </div>

                            {/* Priority - Admin, Manager, and Team */}
                            {(isAdmin || isTeam) && (
                                <div className="space-y-3 pt-4 border-t border-foreground/5">
                                    <label className="block text-sm font-medium text-foreground/70 mb-2">
                                        Priority
                                    </label>
                                    <div className="grid grid-cols-3 gap-2">
                                        {(['low', 'medium', 'high'] as const).map((p) => (
                                            <button
                                                key={p}
                                                type="button"
                                                onClick={() => setPriority(p)}
                                                className={`relative overflow-hidden py-3 rounded-xl text-sm font-medium transition-all duration-300 ${priority === p
                                                    ? p === 'high' ? 'bg-gradient-to-br from-red-500/20 to-red-600/10 border border-red-500/30 text-red-300 shadow-[0_0_15px_rgba(239,68,68,0.2)]' :
                                                        p === 'medium' ? 'bg-gradient-to-br from-orange-500/20 to-orange-600/10 border border-orange-500/30 text-orange-300 shadow-[0_0_15px_rgba(249,115,22,0.2)]' :
                                                            'bg-gradient-to-br from-blue-500/20 to-blue-600/10 border border-blue-500/30 text-blue-300 shadow-[0_0_15px_rgba(59,130,246,0.2)]'
                                                    : 'bg-foreground/5 border border-foreground/5 text-foreground/50 hover:bg-foreground/10 hover:text-foreground/60'
                                                    }`}
                                            >
                                                {p.charAt(0).toUpperCase() + p.slice(1)}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Assigned To - Admin, Manager, and Team Only */}
                            {(isAdmin || isTeam) && (
                                <div className="space-y-3 pt-2">
                                    <label className="block text-sm font-medium text-foreground/70 mb-2">
                                        Assign To Team Members
                                    </label>
                                    <MultiSelect
                                        placeholder="Add assignees..."
                                        options={teamMembers.map(m => ({ id: m.uid, label: m.name }))}
                                        selected={assignedToIds}
                                        onChange={setAssignedToIds}
                                        className="w-full"
                                    />
                                </div>
                            )}

                            {/* Attachments Section */}
                            <div className="space-y-3 pt-4 border-t border-foreground/5">
                                <label className="block text-sm font-medium text-foreground/70 mb-2">
                                    Attachments <span className="text-foreground/80 text-xs">(Optional)</span>
                                </label>
                                <div className="bg-foreground/5 rounded-2xl border border-dashed border-foreground/10 p-6 text-center hover:bg-foreground/10 transition-colors relative group">
                                    <input
                                        type="file"
                                        multiple
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                        onChange={(e) => {
                                            if (e.target.files) {
                                                setFiles(prev => [...prev, ...Array.from(e.target.files!)]);
                                            }
                                        }}
                                    />
                                    <div className="flex flex-col items-center gap-2 pointer-events-none">
                                        <div className="w-10 h-10 rounded-full bg-blue-500/10 flex items-center justify-center text-blue-400 group-hover:scale-110 transition-transform">
                                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" /><polyline points="17 8 12 3 7 8" /><line x1="12" x2="12" y1="3" y2="15" /></svg>
                                        </div>
                                        <p className="text-sm text-foreground/60 group-hover:text-foreground">
                                            Click or drag files here
                                        </p>
                                    </div>
                                </div>
                                {/* File List */}
                                {files.length > 0 && (
                                    <div className="space-y-2 mt-2">
                                        {files.map((file, i) => (
                                            <div key={i} className="flex items-center justify-between p-2 bg-foreground/5 rounded-lg border border-foreground/5">
                                                <span className="text-xs text-foreground truncate max-w-[200px]">{file.name}</span>
                                                <button
                                                    type="button"
                                                    onClick={() => setFiles(files.filter((_, idx) => idx !== i))}
                                                    className="text-foreground/50 hover:text-red-400 p-1"
                                                >
                                                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18" /><path d="m6 6 12 12" /></svg>
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>

                            {/* Read Only Info */}
                            <div className="pt-6 mt-2 border-t border-foreground/5 flex items-center justify-between opacity-60">
                                <div className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-foreground/5 flex items-center justify-center text-xs font-bold text-foreground/50">
                                        {(user.name || 'U').charAt(0)}
                                    </div>
                                    <div className="text-xs text-foreground/50">
                                        Creating as <span className="text-foreground">
                                            {user.name || 'Unknown'}
                                        </span>
                                    </div>
                                </div>
                            </div>

                            {/* Demo Data Toggle */}
                            {(isAdmin || isTeam) && canAccessFeature('testDemoData', user?.role as any) && (
                                <div className="p-4 rounded-2xl bg-amber-500/5 border border-amber-500/10 mb-4 mt-2">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-full bg-amber-500/10 flex items-center justify-center text-amber-500">
                                                <TestTube2 size={16} />
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-amber-200">Test / Demo Data</p>
                                                <p className="text-[10px] text-amber-500/60 uppercase tracking-widest font-bold">Exclude from official reports</p>
                                            </div>
                                        </div>
                                        <Switch
                                            checked={is_demo_data}
                                            onCheckedChange={setIsDemoData}
                                        />
                                    </div>
                                </div>
                            )}

                            {/* Phase 28 Inline Recovery */}
                            {error && (
                                <div className="flex items-center justify-center gap-3 py-2 animate-in fade-in slide-in-from-bottom-2">
                                    <span className="text-sm text-red-400 font-medium">{error}</span>
                                    <div className="w-1 h-1 bg-foreground/10 rounded-full" />
                                    <button
                                        type="button"
                                        onClick={handleRetry}
                                        className="text-xs font-bold text-foreground/70 uppercase tracking-widest hover:text-foreground transition-colors"
                                    >
                                        Edit & Retry
                                    </button>
                                </div>
                            )}

                            <button
                                type="submit"
                                disabled={isSubmitting}
                                tabIndex={3}
                                className="w-full bg-primary hover:bg-primary/90 text-foreground font-extrabold text-lg py-4 rounded-2xl shadow-[0_0_20px_rgba(var(--accent-primary-rgb),0.3)] hover:shadow-[0_0_30px_rgba(var(--accent-primary-rgb),0.5)] active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                {isSubmitting ? (
                                    <>
                                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-black/30 border-t-black" />
                                        <span>Creating...</span>
                                        {uploadProgress && <span className="text-xs font-normal opacity-70 ml-1">({uploadProgress})</span>}
                                    </>
                                ) : (
                                    'Create Task'
                                )}
                            </button>

                            </fieldset>
                        </form>
                    </div>
                </div>
            </div>
        </PageLayout>
    );
}

