'use client';

import React, { useState, useEffect } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import { Shield, Lock, User, Loader2, CheckCircle2, AlertCircle, ArrowRight, Building2 } from 'lucide-react';
import { OnboardingService } from '@/services/onboardingService';
import { AdminService } from '@/services/adminService';
import { OnboardingFlow } from '@/components/auth/OnboardingFlow';
import { toast } from 'sonner';

export default function AcceptInvitePage() {
    const searchParams = useSearchParams();
    const router = useRouter();
    const token = searchParams.get('token');

    const [invite, setInvite] = useState<any>(null);
    const [resolvedWorkspaces, setResolvedWorkspaces] = useState<Array<{ id: string; name: string; role: string }>>([]);
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [step, setStep] = useState<'validate' | 'setup' | 'onboarding'>('validate');

    // Form state
    const [name, setName] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');

    useEffect(() => {
        if (!token) {
            setError('Missing invitation token');
            setLoading(false);
            return;
        }
        validateToken();
    }, [token]);

    const validateToken = async () => {
        setLoading(true);
        try {
            const data = await OnboardingService.validateToken(token!);
            if (data) {
                setInvite(data);
                
                // Resolve workspace names
                const invited = data.metadata?.invited_workspaces || {};
                const ids = Object.keys(invited);
                if (ids.length > 0) {
                    const allWorkspaces = await AdminService.getAllWorkspaces();
                    const filtered = allWorkspaces
                        .filter(ws => ids.includes(ws.id))
                        .map(ws => ({
                            id: ws.id,
                            name: ws.name,
                            role: invited[ws.id]
                        }));
                    setResolvedWorkspaces(filtered);
                }

                setStep('setup');
            } else {
                setError('Invitation is invalid or has expired');
            }
        } catch (err) {
            setError('Failed to validate invitation');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (password !== confirmPassword) return toast.error('Passwords do not match');
        if (password.length < 8) return toast.error('Password must be at least 8 characters');

        setSubmitting(true);
        try {
            await OnboardingService.acceptInvitation(token!, name, password);
            setStep('onboarding');
            toast.success('Account created successfully!');
        } catch (err: any) {
            toast.error(err.message || 'Signup failed');
        } finally {
            setSubmitting(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-[#050505] flex items-center justify-center">
                <Loader2 className="animate-spin text-blue-500" size={32} />
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen bg-[#050505] flex items-center justify-center p-4">
                <div className="max-w-md w-full bg-foreground/[0.03] border border-foreground/5 rounded-[32px] p-8 text-center space-y-6">
                    <div className="w-16 h-16 bg-rose-500/10 rounded-full flex items-center justify-center mx-auto border border-rose-500/20">
                        <AlertCircle className="text-rose-500" size={32} />
                    </div>
                    <h1 className="text-2xl font-black text-foreground tracking-tight">Oops! Something's wrong</h1>
                    <p className="text-foreground/80 text-sm leading-relaxed">{error}</p>
                    <button 
                        onClick={() => router.push('/login')}
                        className="w-full py-4 bg-foreground/5 hover:bg-foreground/10 text-foreground font-bold rounded-2xl transition-colors"
                    >
                        Return to Login
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#050505] flex items-center justify-center p-4">
            <AnimatePresence mode="wait">
                {step === 'setup' && (
                    <motion.div
                        key="setup"
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 1.05 }}
                        className="max-w-md w-full bg-foreground/[0.03] border border-foreground/5 rounded-[40px] p-8 relative overflow-hidden"
                    >
                        <div className="absolute top-0 right-0 p-8 opacity-5">
                            <Shield size={120} />
                        </div>

                        <div className="space-y-6 relative z-10">
                            <div>
                                <h1 className="text-3xl font-black text-foreground tracking-tighter leading-none mb-2">Welcome!</h1>
                                <p className="text-foreground/80 text-sm">You've been invited to join <b>MediaHive</b> as <span className="text-blue-400 font-bold">{invite.email}</span></p>
                            </div>

                            <form onSubmit={handleSubmit} className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-foreground/70 ml-1">Your Full Name</label>
                                    <div className="relative">
                                        <User className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground/80" size={18} />
                                        <input
                                            type="text"
                                            value={name}
                                            onChange={(e) => setName(e.target.value)}
                                            placeholder="Anas Mohamed"
                                            className="w-full bg-foreground/[0.03] border border-foreground/10 rounded-2xl py-4 pl-12 pr-4 text-foreground focus:outline-none focus:border-blue-500/50 transition-colors"
                                            required
                                        />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-foreground/70 ml-1">Create Password</label>
                                    <div className="relative">
                                        <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground/80" size={18} />
                                        <input
                                            type="password"
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            placeholder="••••••••"
                                            className="w-full bg-foreground/[0.03] border border-foreground/10 rounded-2xl py-4 pl-12 pr-4 text-foreground focus:outline-none focus:border-blue-500/50 transition-colors"
                                            required
                                        />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-foreground/70 ml-1">Confirm Password</label>
                                    <div className="relative">
                                        <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground/80" size={18} />
                                        <input
                                            type="password"
                                            value={confirmPassword}
                                            onChange={(e) => setConfirmPassword(e.target.value)}
                                            placeholder="••••••••"
                                            className="w-full bg-foreground/[0.03] border border-foreground/10 rounded-2xl py-4 pl-12 pr-4 text-foreground focus:outline-none focus:border-blue-500/50 transition-colors"
                                            required
                                        />
                                    </div>
                                </div>

                                <div className="p-4 bg-blue-500/5 border border-blue-500/10 rounded-2xl space-y-2">
                                    <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-400">
                                        <Building2 size={12} /> Workspaces Assigned
                                    </div>
                                    <div className="flex flex-wrap gap-2">
                                        {resolvedWorkspaces.length > 0 ? (
                                            resolvedWorkspaces.map(ws => (
                                                <span key={ws.id} className="px-2 py-0.5 rounded-md bg-foreground/5 border border-foreground/5 text-[9px] font-bold text-foreground/70 uppercase tracking-tight">
                                                    {ws.name}
                                                </span>
                                            ))
                                        ) : (
                                            <span className="text-[10px] text-foreground/80 italic">Global Access Only</span>
                                        )}
                                    </div>
                                </div>

                                <button
                                    type="submit"
                                    disabled={submitting}
                                    className="w-full py-5 bg-blue-500 hover:bg-blue-600 disabled:opacity-50 text-foreground font-black text-sm uppercase tracking-widest rounded-2xl shadow-xl shadow-blue-500/20 flex items-center justify-center gap-2 transition-all transform active:scale-[0.98] mt-4"
                                >
                                    {submitting ? (
                                        <Loader2 className="animate-spin" size={20} />
                                    ) : (
                                        <>
                                            Complete Setup
                                            <ArrowRight size={18} />
                                        </>
                                    )}
                                </button>
                            </form>
                        </div>
                    </motion.div>
                )}

                {step === 'onboarding' && (
                    <OnboardingFlow 
                        userName={name}
                        workspaces={resolvedWorkspaces}
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

"use client";
import React, { useState } from "react";
import { useMagneticHover } from "@/hooks/useMagneticHover";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "@/contexts/AuthContextProvider";
import { Plus, CheckSquare, Calendar, Bell, Users, Package, Download, BarChart3, ShieldCheck, User, X, CalendarPlus, PackagePlus, Upload } from "lucide-react";
import { usePathname, useRouter } from "next/navigation";
import AppLink from "@/components/AppLink";
import { triggerHaptic } from "@/lib/haptics";
import { cn } from "@/lib/utils";


interface FABProps {
  onMainClick?: () => void;
}

import { createPortal } from "react-dom";

export default function FAB({ onMainClick }: FABProps) {
  const [isOpen, setIsOpen] = useState(false);
  const { user } = useAuth();
  const pathname = usePathname();
  const router = useRouter();
  const [mounted, setMounted] = useState(false);

  React.useEffect(() => {
    setMounted(true);
  }, []);

  // Reset menu on route change
  React.useEffect(() => {
    setIsOpen(false);
  }, [pathname]);

  // Context-aware configuration
  const FAB_CONFIG: Record<string, { icon: any; label: string; href?: string; role?: string }> = {
    "/tasks": { icon: CheckSquare, label: "Create Task", href: "/tasks/new" },
    "/events": { icon: CalendarPlus, label: "Create Event", href: "/events/new" },
    "/downloads": { icon: Upload, label: "Upload File", href: "/downloads/new" },
    "/inventory": { icon: PackagePlus, label: "Add Item", href: "/inventory/new" },
  };

  const getPageConfig = () => {
    const config = FAB_CONFIG[pathname || ""];
    if (config) return config;

    // Sub-path matching
    for (const route in FAB_CONFIG) {
      if (pathname?.startsWith(route + "/")) return FAB_CONFIG[route];
    }

    // Default Fallback
    return { icon: Plus, label: "Open Actions Menu" };
  };

  const currentConfig = getPageConfig();
  const ContextIcon = currentConfig.icon;

  const allActions = [
    { label: "Task", icon: CheckSquare, href: "/tasks/new", delay: 0.1 },
    { label: "Event", icon: CalendarPlus, href: "/events/new", delay: 0.05 },
    { label: "Item", icon: PackagePlus, href: "/inventory/new", delay: 0 },
    { label: "Notify", icon: Bell, href: "/notifications/new", delay: 0, role: 'admin' },
  ];

  const actions = allActions.filter(action => !action.role || action.role === user?.role);

  // --- Phase 33.6: Hardening & Optimization ---
  type FABVisualState = 'interacting' | 'menu_open' | 'guidance' | 'context_flash' | 'idle';
  const timers = React.useRef<Record<string, NodeJS.Timeout>>({});
  const lastRouteRef = React.useRef(pathname);
  const isLocked = React.useRef(false);
  const [isTabHidden, setIsTabHidden] = useState(false);

  // --- Phase 33.8: Final Stability & Polish ---
  const bc = React.useRef<BroadcastChannel | null>(null);
  const interactionCount = React.useRef(0);
  const lastSent = React.useRef(0);
  const lastEvent = React.useRef(0);
  const [isLowPower, setIsLowPower] = useState(false);
  const [hasError, setHasError] = useState(false);

  const isOpenRef = React.useRef(isOpen);
  React.useEffect(() => {
    isOpenRef.current = isOpen;
  }, [isOpen]);

  // 1. Stabilized BroadcastChannel (Safety + Throttling - run once)
  React.useEffect(() => {
    if (typeof BroadcastChannel === 'undefined') return;
    
    try {
      bc.current = new BroadcastChannel('mh_fab_state');
      const handler = (e: MessageEvent) => {
        if (e.data === 'menu_opened' && isOpenRef.current) setIsOpen(false);
      };
      bc.current.addEventListener('message', handler);
      
      if (typeof navigator !== 'undefined' && (navigator as any).connection?.saveData) {
        setIsLowPower(true);
      }
      
      return () => {
        bc.current?.removeEventListener('message', handler);
        bc.current?.close();
      };
    } catch (e) {
      console.warn('FAB Broadcast error', e);
    }
  }, []);

  const broadcastThrottled = (msg: string) => {
    const now = Date.now();
    if (now - lastSent.current < 200) return;
    lastSent.current = now;
    bc.current?.postMessage(msg);
  };

  // 2. Adaptive Timing Cap (Predictable Calm: max 3s)
  const getCalmDuration = () => Math.min(1500 + (interactionCount.current * 200), 3000);

  // 3. Telemetry Guard (Throttled logging)
  const trackSafe = (action: string, metadata: any = {}) => {
    const now = Date.now();
    if (now - lastEvent.current < 300) return;
    lastEvent.current = now;
    if (process.env.NODE_ENV !== 'production') {
      console.log(`[FAB_ANALYTICS] ${action}`, { route: pathname, state: visualState, ...metadata });
    }
  };

  const setSafeTimeout = (key: string, fn: () => void, delay: number) => {
    if (timers.current[key]) clearTimeout(timers.current[key]);
    timers.current[key] = setTimeout(fn, delay);
  };

  React.useEffect(() => {
    return () => Object.values(timers.current).forEach(clearTimeout);
  }, []);

  // 4. Visibility Optimization
  React.useEffect(() => {
    const handleVisibility = () => setIsTabHidden(document.hidden);
    document.addEventListener("visibilitychange", handleVisibility);
    return () => document.removeEventListener("visibilitychange", handleVisibility);
  }, []);

  // 5. Route Change Interrupt Guard
  React.useEffect(() => {
    if (pathname !== lastRouteRef.current) {
      lastRouteRef.current = pathname;
      setShowLabel(false);
      setIsEmptyState(false);
      
      if (currentConfig.href) {
        setSafeTimeout('flash_trigger', () => setShowLabel(true), 50);
        setSafeTimeout('flash_clear', () => setShowLabel(false), 1050);
      }
    }
  }, [pathname, currentConfig.href]);

  // 6. Hardened Interaction Control
  const handleClick = () => {
    if (isLocked.current) return;
    isLocked.current = true;
    
    try {
      triggerHaptic();
      interactionCount.current++;
      
      if (isOpen) {
        setIsOpen(false);
        trackSafe('menu_closed');
      } else if (onMainClick) {
        onMainClick();
        trackSafe('external_click');
      } else {
        const isMember = user?.role === 'member';
        const hasRoleAccess = !currentConfig.role || currentConfig.role === user?.role;
        
        if (currentConfig.href && hasRoleAccess && !isMember) {
          trackSafe('direct_action', { target: currentConfig.href });
          router.push(currentConfig.href);
        } else {
          setIsOpen(true);
          broadcastThrottled('menu_opened');
          trackSafe('menu_opened');
        }
      }
    } catch (err) {
      setHasError(true);
    } finally {
      setSafeTimeout('interaction_lock', () => { isLocked.current = false; }, 200);
    }
  };


  const [isHovered, setIsHovered] = useState(false);
  const [isPressed, setIsPressed] = useState(false);
  const [isScrolling, setIsScrolling] = useState(false);
  const scrollRef = React.useRef({ y: 0, time: Date.now() });

  // 1. Refined Scroll Detection
  React.useEffect(() => {
    const handleScroll = () => {
      const now = Date.now();
      const currentY = window.scrollY;
      const delta = Math.abs(currentY - scrollRef.current.y);
      
      if (delta > 20) {
        setIsScrolling(true);
        setSafeTimeout('scroll_idle', () => setIsScrolling(false), getCalmDuration());
      }
      scrollRef.current = { y: currentY, time: now };
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // 2. Guidance State (Respects registry)
  const [isEmptyState, setIsEmptyState] = useState(false);
  const [showLabel, setShowLabel] = useState(false);

  React.useEffect(() => {
    const checkEmpty = () => {
      const hasEmpty = document.querySelector('.mh-empty-state') !== null;
      const sessionKey = `mh_fab_empty_${pathname}`;
      if (hasEmpty && !sessionStorage.getItem(sessionKey)) {
        setIsEmptyState(true);
        trackSafe('empty_state_guided');
        setSafeTimeout('empty_dismiss', () => setIsEmptyState(false), 3000);
        sessionStorage.setItem(sessionKey, 'true');
      }
    };
    setSafeTimeout('empty_check', checkEmpty, 800);
    const observer = new MutationObserver(checkEmpty);
    observer.observe(document.body, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, [pathname]);

  // 5. Unified State Logic
  const [isInteracting, setIsInteracting] = useState(false);
  React.useEffect(() => {
    if (isHovered || isPressed || isScrolling) {
      setIsInteracting(true);
    } else {
      setSafeTimeout('calm_period', () => setIsInteracting(false), getCalmDuration());
    }
  }, [isHovered, isPressed, isScrolling]);

  const visualState = React.useMemo((): FABVisualState => {
    if (isInteracting) return 'interacting';
    if (isOpen) return 'menu_open';
    if (isEmptyState) return 'guidance';
    if (showLabel) return 'context_flash';
    return 'idle';
  }, [isInteracting, isOpen, isEmptyState, showLabel]);

  // Hide logic
  const [isHidden, setIsHidden] = useState(false);
  React.useEffect(() => {
    const checkHidden = () => setIsHidden(document.body.classList.contains('hide-fab'));
    checkHidden();
    const observer = new MutationObserver(checkHidden);
    observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    return () => observer.disconnect();
  }, []);

  if (!mounted || isHidden) return null;

  // Visual derived states
  const isContextual = !!currentConfig.href;
  
  // Context-aware glow colors (Optimized for high-contrast visibility)
  const getGlowColor = () => {
    if (pathname?.startsWith('/tasks')) return 'rgba(167, 139, 250, 0.4)'; // Violet (Vibrant)
    if (pathname?.startsWith('/events')) return 'rgba(96, 165, 250, 0.4)'; // Blue (Vibrant)
    if (pathname?.startsWith('/inventory')) return 'rgba(45, 212, 191, 0.4)'; // Teal (Vibrant)
    return 'rgba(129, 140, 248, 0.4)'; // Default Indigo (Vibrant)
  };

  const isAnimationPaused = visualState !== 'idle' || isTabHidden || isLowPower;

  // 7. Safety Fallback Guard (Neutral Tone)
  if (hasError) {
    return createPortal(
      <button 
        onClick={() => router.push('/home')}
        aria-label="Try Again"
        className="fab fixed left-1/2 bottom-8 -translate-x-1/2 w-16 h-16 rounded-full bg-slate-800 text-foreground flex flex-col items-center justify-center shadow-lg z-[110] border border-foreground/10 lg:hidden focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
      >
        <Plus size={24} className="rotate-45" />
        <span className="text-[8px] font-bold uppercase mt-1">Try Again</span>
      </button>,
      document.body
    );
  }

  return createPortal(
    <>
      <AnimatePresence>
        {isOpen && (
          <div className="fixed inset-0 z-40 overflow-hidden pointer-events-auto lg:hidden">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-background/60"
              style={{ backdropFilter: 'blur(8px)', WebkitBackdropFilter: 'blur(8px)' }}
              onClick={() => setIsOpen(false)}
            />
          </div>
        )}
      </AnimatePresence>
      <div
        className="fab fixed left-1/2 z-[110] flex flex-col-reverse items-center gap-4 pointer-events-auto lg:hidden"
        style={{ 
          bottom: 'calc(var(--bottom-nav-height, 4.5rem) + var(--safe-bottom, 1.5rem))',
          transform: 'translate(-50%, 50%) translateY(calc(-1 * var(--keyboard-offset, 0px))) translateY(var(--fab-optical-offset, 2px))',
          '--fab-glow-color': getGlowColor()
        } as any}
      >
        {/* State-Driven Priority Surface (Label / Tooltip) */}
        <AnimatePresence mode="wait">
          {visualState === 'context_flash' && (
            <motion.div
              key="context-flash"
              initial={{ opacity: 0, y: 10, scale: 0.9 }}
              animate={{ opacity: 0.9, y: -4, scale: 1 }}
              exit={{ opacity: 0, y: -10, scale: 0.9 }}
              transition={{ 
                duration: 0.15,
                opacity: { duration: 0.15 },
                y: { duration: 0.15 },
              }}
              className="absolute bottom-20 px-4 py-2 rounded-2xl bg-indigo-600/90 text-foreground/90 text-xs font-bold shadow-2xl border border-foreground/20 whitespace-nowrap z-50 backdrop-blur-md"
            >
              {currentConfig.label}
              <div className="absolute bottom-[-6px] left-1/2 -translate-x-1/2 w-3 h-3 bg-indigo-600/90 rotate-45 border-r border-b border-foreground/20" />
            </motion.div>
          )}

          {visualState === 'guidance' && (
            <motion.div
              key="guidance-tooltip"
              initial={{ opacity: 0, y: 10, scale: 0.9 }}
              animate={{ opacity: 1, y: -8, scale: 1 }}
              exit={{ opacity: 0, y: -10, scale: 0.9 }}
              className="absolute bottom-20 px-4 py-2 rounded-2xl bg-indigo-600 text-foreground text-xs font-bold shadow-2xl border border-foreground/20 max-w-[180px] text-center z-50 backdrop-blur-md leading-tight"
            >
              Create your first {currentConfig.label.split(' ')[1] || 'item'}
              <div className="absolute bottom-[-6px] left-1/2 -translate-x-1/2 w-3 h-3 bg-indigo-600 rotate-45 border-r border-b border-foreground/20" />
            </motion.div>
          )}
        </AnimatePresence>

        {/* Magnetic hover wrapper — GPU-accelerated translate, isolated from framer-motion transforms */}
        <MagneticFABButton
          isOpen={isOpen}
          isAnimationPaused={isAnimationPaused}
          visualState={visualState}
          handleClick={handleClick}
          setIsHovered={setIsHovered}
          setIsPressed={setIsPressed}
          pathname={pathname}
          currentConfig={currentConfig}
          ContextIcon={ContextIcon}
        />
        <AnimatePresence>
          {isOpen && (
            <div className="absolute bottom-20 flex flex-col items-center gap-5 w-max z-[60]">
              {actions.map((action) => (
                <AppLink key={action.label} href={action.href} onClick={() => setIsOpen(false)}>
                  <motion.div initial={{ opacity: 0, y: 20, scale: 0.8 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10, scale: 0.8 }} transition={{ delay: action.delay }} className="flex flex-col items-center gap-2 group">
                    <div className="w-12 h-12 rounded-full premium-card flex items-center justify-center transition-all duration-300 group-hover:scale-110 shadow-[0_0_20px_rgba(99,102,241,0.3)] relative overflow-hidden text-foreground">
                      <action.icon size={20} strokeWidth={2} />
                    </div>
                    {/* Clean Label */}
                    <span className="text-foreground text-[10px] font-bold uppercase tracking-widest px-3 py-1 rounded-lg premium-card">{action.label}</span>
                  </motion.div>
                </AppLink>
              ))}
            </div>
          )}
        </AnimatePresence>
      </div>
    </>,
    document.body
  );
}

/** Extracted FAB button with magnetic hover to keep hook call at component top-level */
function MagneticFABButton({
  isOpen, isAnimationPaused, visualState, handleClick,
  setIsHovered, setIsPressed, pathname, currentConfig, ContextIcon
}: {
  isOpen: boolean; isAnimationPaused: boolean; visualState: string;
  handleClick: () => void; setIsHovered: (v: boolean) => void;
  setIsPressed: (v: boolean) => void; pathname: string | null;
  currentConfig: { label: string; href?: string; role?: string };
  ContextIcon: any;
}) {
  const { ref: magneticRef, style: magneticStyle } = useMagneticHover(30, 0.35);

  return (
    <div ref={magneticRef as React.RefObject<HTMLDivElement>} style={magneticStyle}>
      <motion.button
        id="fab-main-action"
        className={cn(
          "w-16 h-16 rounded-full flex items-center justify-center relative z-20 fab-surface border border-foreground/10 backdrop-blur-xl transition-all duration-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
          "animate-fab-breathing",
          isAnimationPaused && "is-paused",
          visualState === 'guidance' && "ring-4 ring-indigo-500/50 scale-105"
        )}
        style={{ boxShadow: '0 6px 24px var(--fab-glow-color)' }}
        onClick={handleClick}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onPointerDown={() => setIsPressed(true)}
        onPointerUp={() => setIsPressed(false)}
        aria-label={isOpen ? "Close Menu" : currentConfig.label}
        aria-expanded={isOpen}
        whileTap={{ scale: 0.95 }}
        animate={{ rotate: isOpen ? 135 : 0 }}
      >
        <AnimatePresence mode="wait">
          <motion.div
            key={isOpen ? 'close' : `${pathname}-${currentConfig.label}`}
            initial={{ opacity: 0, scale: 0.9, rotate: -15 }}
            animate={{ opacity: 1, scale: 1, rotate: 0 }}
            exit={{ opacity: 0, scale: 0.9, rotate: 15 }}
            transition={{ duration: 0.18, ease: "easeOut" }}
          >
            {isOpen ? (
              <Plus size={32} strokeWidth={2.8} className="text-foreground" />
            ) : (
              <ContextIcon size={32} strokeWidth={2.8} className="text-foreground opacity-95" />
            )}
          </motion.div>
        </AnimatePresence>
      </motion.button>
    </div>
  );
}

// src/components/AI/AssistantPanel.tsx
// AI Assistant Panel component

'use client';

import React, { useState } from 'react';
import { apiClient } from '@/lib/apiClient';

interface Suggestion {
  suggestedTitle: string;
  suggestedDescription: string;
  suggestedPriority: string;
  suggestedStatus: string;
}

interface NotificationSummary {
  count: number;
  categories: string[];
  keyPoints: string[];
  priority: string;
}

export function AssistantPanel() {
  const [isOpen, setIsOpen] = useState(false);
  const [taskSuggestions, setTaskSuggestions] = useState<Suggestion | null>(null);
  const [notificationSummary, setNotificationSummary] = useState<NotificationSummary | null>(null);
  const [loading, setLoading] = useState(false);

  const generateTaskSuggestions = async (title: string, description: string) => {
    setLoading(true);
    try {
      const data = await apiClient('/api/ai/generate-task', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ title, description }),
      });
      setTaskSuggestions(data.suggestions);
    } catch (error) {
      console.error('Failed to generate task suggestions:', error);
    } finally {
      setLoading(false);
    }
  };

  const summarizeNotifications = async (notifications: any[]) => {
    setLoading(true);
    try {
      const data = await apiClient('/api/ai/summarize-notifications', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ notifications }),
      });
      setNotificationSummary(data.summary);
    } catch (error) {
      console.error('Failed to summarize notifications:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="ai-assistant-panel">
      <button 
        className="ai-assistant-toggle"
        onClick={() => setIsOpen(!isOpen)}
        data-testid="ai-assistant-toggle"
      >
        <span className="ai-icon">🤖</span>
        AI Assistant
      </button>

      {isOpen && (
        <div className="ai-assistant-dropdown" data-testid="ai-assistant-dropdown">
          <div className="ai-assistant-header">
            <h3>AI Assistant</h3>
            <button 
              className="close-button"
              onClick={() => setIsOpen(false)}
            >
              ×
            </button>
          </div>
          
          <div className="ai-assistant-content">
            {loading ? (
              <div className="loading">Processing...</div>
            ) : (
              <>
                <div className="ai-feature">
                  <h4>Task Suggestions</h4>
                  <div className="suggestion-form">
                    <input 
                      type="text" 
                      placeholder="Task title" 
                      id="task-title"
                    />
                    <textarea 
                      placeholder="Task description" 
                      id="task-description"
                    />
                    <button 
                      onClick={() => {
                        const title = (document.getElementById('task-title') as HTMLInputElement).value;
                        const description = (document.getElementById('task-description') as HTMLTextAreaElement).value;
                        generateTaskSuggestions(title, description);
                      }}
                    >
                      Generate Suggestions
                    </button>
                  </div>
                  
                  {taskSuggestions && (
                    <div className="suggestions-result">
                      <h5>Suggestions:</h5>
                      <p><strong>Title:</strong> {taskSuggestions.suggestedTitle}</p>
                      <p><strong>Description:</strong> {taskSuggestions.suggestedDescription}</p>
                      <p><strong>Priority:</strong> {taskSuggestions.suggestedPriority}</p>
                      <p><strong>Status:</strong> {taskSuggestions.suggestedStatus}</p>
                    </div>
                  )}
                </div>
                
                <div className="ai-feature">
                  <h4>Notification Summary</h4>
                  <button 
                    onClick={() => {
                      // In a real implementation, we would fetch actual notifications
                      const mockNotifications = [
                        { id: 1, title: 'Task Assigned', body: 'You have been assigned to a new task' },
                        { id: 2, title: 'Review Request', body: 'A task requires your review' }
                      ];
                      summarizeNotifications(mockNotifications);
                    }}
                  >
                    Summarize Notifications
                  </button>
                  
                  {notificationSummary && (
                    <div className="summary-result">
                      <h5>Summary:</h5>
                      <p><strong>Count:</strong> {notificationSummary.count} notifications</p>
                      <p><strong>Categories:</strong> {notificationSummary.categories.join(', ')}</p>
                      <ul>
                        {notificationSummary.keyPoints.map((point, index) => (
                          <li key={index}>{point}</li>
                        ))}
                      </ul>
                      <p><strong>Priority:</strong> {notificationSummary.priority}</p>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// src/components/AI/InstitutionAssistant.tsx
// AI Institution Assistant Component

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { apiClient } from '@/lib/apiClient';

interface AISuggestion {
  id?: string;
  type: 'task' | 'event' | 'team' | 'summary' | 'recommendation';
  title: string;
  description: string;
  priority?: string;
  suggestedAssignee?: string;
  availability?: string;
  startTime?: string;
  endTime?: string;
  confidence?: number;
}

export function InstitutionAssistant() {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState<AISuggestion[]>([]);
  const [loading, setLoading] = useState(false);
  const [conversation, setConversation] = useState<{ role: 'user' | 'assistant'; content: string }[]>([]);
  const [mode, setMode] = useState<'suggestions' | 'chat'>('suggestions');
  const panelRef = useRef<HTMLDivElement>(null);

  // Focus the input when the panel opens
  useEffect(() => {
    if (isOpen && panelRef.current) {
      const input = panelRef.current.querySelector('input');
      if (input) {
        input.focus();
      }
    }
  }, [isOpen]);

  // Generate suggestions based on user query using AI service
  const generateSuggestions = async () => {
    if (!query.trim()) return;
    
    setLoading(true);
    
    try {
      // Add user query to conversation
      const newConversation = [...conversation, { role: 'user' as const, content: query }];
      setConversation(newConversation);
      
      // Call AI service to generate suggestions
      const data = await apiClient('/api/ai/suggestions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ query }),
      });
      
      // Add IDs to suggestions for React keys
      const suggestionsWithIds = data.suggestions.map((suggestion: any, index: number) => ({
        ...suggestion,
        id: `${suggestion.type}-${index}`
      }));
      setSuggestions(suggestionsWithIds);
    } catch (error) {
      console.error('Failed to generate suggestions:', error);
      // Fallback to mock suggestions
      const mockSuggestions: AISuggestion[] = [
        {
          id: 'task-1',
          type: 'task',
          title: `Create task: ${query}`,
          description: `Auto-generated task based on your request: ${query}`,
          priority: 'medium',
          suggestedAssignee: 'Team Lead',
          confidence: 0.85
        },
        {
          id: 'event-1',
          type: 'event',
          title: `Schedule event: ${query}`,
          description: `Event suggestion based on your request: ${query}`,
          startTime: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
          endTime: new Date(Date.now() + 25 * 60 * 60 * 1000).toISOString(),
          confidence: 0.92
        }
      ];
      setSuggestions(mockSuggestions);
    } finally {
      setLoading(false);
    }
  };

  // Handle chat mode with AI service
  const handleChat = async () => {
    if (!query.trim()) return;
    
    setLoading(true);
    
    try {
      // Add user query to conversation
      const newConversation = [...conversation, { role: 'user' as const, content: query }];
      setConversation(newConversation);
      
      // In a real implementation, this would call an AI chat service
      // For now, we'll return a mock response
      const mockResponse = `I understand you're asking about "${query}". Based on the institutional data, I can help you with task creation, event scheduling, team allocation, and activity summaries. What specific action would you like to take?`;
      
      // Add AI response to conversation
      const updatedConversation = [...newConversation, { role: 'assistant' as const, content: mockResponse }];
      setConversation(updatedConversation);
      
      setQuery('');
    } catch (error) {
      console.error('Failed to generate chat response:', error);
    } finally {
      setLoading(false);
    }
  };

  // Apply a suggestion
  const applySuggestion = (suggestion: AISuggestion) => {
    // In a real implementation, this would apply the suggestion
    alert(`Applied suggestion: ${suggestion.title}`);
    
    // Add to conversation
    const newConversation = [...conversation, { role: 'user' as const, content: `Apply suggestion: ${suggestion.title}` }];
    setConversation(newConversation);
    
    setQuery('');
    setSuggestions([]);
  };

  // Clear conversation
  const clearConversation = () => {
    setConversation([]);
    setQuery('');
    setSuggestions([]);
  };

  return (
    <div className="institution-assistant">
      <button 
        className="assistant-toggle"
        onClick={() => setIsOpen(!isOpen)}
        data-testid="institution-assistant-toggle"
      >
        <span className="ai-icon">🤖</span>
        AI Assistant
      </button>

      {isOpen && (
        <div 
          ref={panelRef}
          className="assistant-panel" 
          data-testid="institution-assistant-panel"
        >
          <div className="assistant-header">
            <h3>Institution AI Assistant</h3>
            <div className="flex space-x-2">
              <button
                onClick={() => setMode('suggestions')}
                className={`px-2 py-1 text-xs rounded ${mode === 'suggestions' ? 'bg-blue-500 text-foreground' : 'bg-gray-200'}`}
              >
                Suggestions
              </button>
              <button
                onClick={() => setMode('chat')}
                className={`px-2 py-1 text-xs rounded ${mode === 'chat' ? 'bg-blue-500 text-foreground' : 'bg-gray-200'}`}
              >
                Chat
              </button>
              <button 
                className="close-button ml-2"
                onClick={() => setIsOpen(false)}
              >
                ×
              </button>
            </div>
          </div>
          
          <div className="assistant-content">
            {mode === 'suggestions' ? (
              <>
                <div className="query-input flex">
                  <input
                    type="text"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && generateSuggestions()}
                    placeholder="Describe what you need help with..."
                    className="flex-1 p-2 border rounded"
                  />
                  <button
                    onClick={generateSuggestions}
                    disabled={loading || !query.trim()}
                    className="ml-2 bg-blue-500 text-foreground px-4 py-2 rounded disabled:opacity-50"
                  >
                    {loading ? 'Generating...' : 'Get Suggestions'}
                  </button>
                </div>
                
                {conversation.length > 0 && (
                  <button
                    onClick={clearConversation}
                    className="mt-2 text-xs text-foreground/50 hover:text-foreground/30"
                  >
                    Clear conversation
                  </button>
                )}
                
                {suggestions.length > 0 && (
                  <div className="suggestions-list mt-4">
                    <h4>Suggestions:</h4>
                    {suggestions.map((suggestion) => (
                      <div key={suggestion.id} className="suggestion-item p-3 border rounded mb-2">
                        <div className="flex justify-between items-start">
                          <div className="flex-1">
                            <div className="flex items-center">
                              <h5 className="font-bold">{suggestion.title}</h5>
                              {suggestion.confidence && (
                                <span className="ml-2 text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">
                                  {Math.round(suggestion.confidence * 100)}% confidence
                                </span>
                              )}
                            </div>
                            <p className="text-sm text-foreground/40">{suggestion.description}</p>
                            {suggestion.availability && (
                              <p className="text-xs text-blue-600">{suggestion.availability}</p>
                            )}
                            {suggestion.priority && (
                              <span className="inline-block mt-1 text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded">
                                Priority: {suggestion.priority}
                              </span>
                            )}
                          </div>
                          <button
                            onClick={() => applySuggestion(suggestion)}
                            className="bg-green-500 text-foreground px-3 py-1 rounded text-sm ml-2"
                          >
                            Apply
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
                
                {suggestions.length === 0 && !loading && query && (
                  <div className="no-suggestions mt-4 text-foreground/50">
                    No suggestions found. Try rephrasing your request.
                  </div>
                )}
              </>
            ) : (
              <>
                <div className="chat-container h-64 overflow-y-auto mb-4 p-2 border rounded">
                  {conversation.map((message, index) => (
                    <div 
                      key={`${message.role}-${index}`} 
                      className={`mb-2 ${message.role === 'user' ? 'text-right' : 'text-left'}`}
                    >
                      <div 
                        className={`inline-block p-2 rounded max-w-xs ${
                          message.role === 'user' 
                            ? 'bg-blue-500 text-foreground' 
                            : 'bg-gray-200 text-foreground/20'
                        }`}
                      >
                        {message.content}
                      </div>
                    </div>
                  ))}
                  {loading && (
                    <div className="text-left">
                      <div className="inline-block p-2 rounded bg-gray-200 text-foreground/20">
                        <span className="loading-dots">Thinking</span>
                      </div>
                    </div>
                  )}
                </div>
                
                <div className="query-input flex">
                  <input
                    type="text"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleChat()}
                    placeholder="Ask me anything about tasks, events, or team allocation..."
                    className="flex-1 p-2 border rounded"
                  />
                  <button
                    onClick={handleChat}
                    disabled={loading || !query.trim()}
                    className="ml-2 bg-blue-500 text-foreground px-4 py-2 rounded disabled:opacity-50"
                  >
                    {loading ? 'Thinking...' : 'Send'}
                  </button>
                </div>
                
                <div className="mt-2 text-xs text-foreground/50">
                  AI Assistant can help with: Task creation, Event scheduling, Team allocation, Activity summaries
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import React from 'react';
import AppLink from "@/components/AppLink";
import { usePathname } from "next/navigation";
import { Home, CheckSquare, Calendar, User, Download, BarChart3, Package, ShieldCheck } from "lucide-react";
import { motion } from "framer-motion";
import { useAuth } from '@/contexts/AuthContextProvider';
import FAB from "@/client/components/FAB";

export default function BottomNavigation() {
  const pathname = usePathname();

  const isActive = (href: string) => pathname === href || pathname?.startsWith(href + "/");
  const navRef = React.useRef<HTMLElement>(null);
  const [mounted, setMounted] = React.useState(false);
  const lastHeight = React.useRef<number | null>(null);

  React.useEffect(() => {
    setMounted(true);
    
    // Dynamic height observer to ensure pixel-perfect FAB anchoring
    const updateHeight = () => {
      if (navRef.current) {
        const height = navRef.current.offsetHeight;
        if (lastHeight.current !== height) {
          lastHeight.current = height;
          document.documentElement.style.setProperty('--bottom-nav-height', `${height}px`);
        }
      }
    };

    const currentNav = navRef.current;
    const observer = new ResizeObserver(updateHeight);
    if (currentNav) observer.observe(currentNav);
    updateHeight(); // Initial measure

    return () => observer.disconnect();
  }, []);

  // Exclude specific paths where BottomNav causes layout issues
  const excludedPaths = ['/events/new', '/reports/activity'];
  if (excludedPaths.includes(pathname || '') || (pathname?.startsWith('/reports/activity'))) {
    return null;
  }

  // FAB Context-Aware Visibility Control
  const allowedPages = ['/', '/home', '/tasks', '/events', '/inventory', '/downloads', '/reports', '/admin', '/settings', '/profile', '/notifications'];
  const isOnAllowedPage = allowedPages.some(page =>
    pathname === page || pathname?.startsWith(page + '/')
  );
  
  // Only check window/search after mount
  const hasModalParam = mounted && (window.location.search.includes('id=') || window.location.search.includes('action='));
  const showFAB = mounted && isOnAllowedPage && !hasModalParam;

  const { user } = useAuth(); // Helper to access auth context
  // Assume member if no role or specific member role
  const isMember = user?.role === 'member';

  const items = [
    { key: 'home', label: 'Home', href: '/home', icon: Home },
    { key: 'tasks', label: 'Tasks', href: '/tasks', icon: CheckSquare },
    { key: 'events', label: 'Events', href: '/events', icon: Calendar },
    { key: 'spacer', label: '', href: '', icon: null },
    { key: 'inventory', label: 'Inventory', href: '/inventory', icon: Package },
    { key: 'downloads', label: 'Files', href: '/downloads', icon: Download },
    // Role-based Switch: Reports for Team/Admin, Profile for Members
    isMember
      ? { key: 'profile', label: 'Profile', href: '/profile', icon: User }
      : user?.role === 'admin'
        ? { key: 'governance', label: 'Gov', href: '/governance', icon: ShieldCheck }
        : { key: 'reports', label: 'Reports', href: '/reports', icon: BarChart3 },
  ];

  return (
    <>
      <div
        className="bottom-nav fixed left-0 right-0 bottom-0 top-auto z-40 pointer-events-none flex justify-center lg:hidden print:hidden"
        style={{
          marginBottom: 'var(--safe-bottom, 1.5rem)',
          transform: 'translateY(calc(-1 * var(--keyboard-offset, 0px)))'
        }}
      >
        {/* FAB - Context-Aware Visibility - Deterministic Anchoring */}
        {showFAB && <FAB />}

        <motion.nav
          ref={navRef}
          initial={{ y: 50, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="bottom-nav w-[min(36rem,calc(100vw-2rem))] px-3 glass-liquid rounded-[32px] pointer-events-auto overflow-hidden relative"
          style={{
            height: 'auto', // Allow content + padding to define height
            minHeight: 'var(--bottom-nav-height, 4.5rem)',
            paddingBottom: 'env(safe-area-inset-bottom)',
            display: 'grid',
            gridTemplateColumns: 'repeat(3, 1fr) 72px repeat(3, 1fr)',
            alignItems: 'center',
            justifyItems: 'center'
          }}
        >
          {items.map((item) => {
            if (item.key === 'spacer') return <div key="spacer" className="w-18" />;
            const Icon = item.icon!;
            const active = isActive(item.href);

            return (
              <AppLink
                key={item.key}
                href={item.href}
                className={`group relative flex flex-col items-center justify-center w-full h-full transition-all duration-200 ${active ? 'text-primary' : 'text-muted-foreground hover:text-foreground'}`}
              >
                {/* Active Indicator Bar (Cyber-Executive under-glow) */}
                {active && (
                  <motion.div
                    layoutId="nav-active-glow"
                    className="absolute bottom-0 w-12 h-6 bg-accent-primary/20 blur-xl rounded-full"
                    transition={{ type: "spring", bounce: 0, duration: 0.3 }}
                  />
                )}

                <Icon
                  size={22}
                  className={`transition-all duration-300 ${active ? 'text-accent-primary drop-shadow-[0_0_8px_rgba(129,140,248,0.5)] translate-y-0 opacity-100' : 'text-foreground/80 group-hover:text-foreground/70 opacity-60'}`}
                />

                <span
                  className={`text-[9px] font-bold uppercase tracking-widest mt-1.5 transition-all duration-200 ${active ? 'opacity-100' : 'opacity-0 scale-90 translate-y-1 group-hover:opacity-60 group-hover:translate-y-0 group-hover:scale-100'}`}
                >
                  {item.label}
                </span>
              </AppLink>
            );
          })}
        </motion.nav>
      </div>
    </>
  );
}

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import { Database, RotateCcw } from 'lucide-react';
import { isFeatureEnabled } from '@/app/featureFlags';
import { apiClient } from '@/lib/apiClient';

interface DemoDataButtonProps {
  onDemoDataLoaded?: () => void;
}

export function DemoDataButton({ onDemoDataLoaded }: DemoDataButtonProps) {
  const [loading, setLoading] = useState(false);
  const [hasDemoData, setHasDemoData] = useState<boolean | null>(null);
  const [isLabActive, setIsLabActive] = useState(false);

  // Check if demo data exists when component mounts
  React.useEffect(() => {
    // Read lab toggle state from local storage
    if (typeof window !== 'undefined') {
      setIsLabActive(localStorage.getItem('labs:testDemoData') === 'true');
      
      // Listen for storage changes in case it's toggled in another tab
      const handleStorageChange = (e: StorageEvent) => {
        if (e.key === 'labs:testDemoData') {
          setIsLabActive(e.newValue === 'true');
        }
      };
      window.addEventListener('storage', handleStorageChange);
    }

    if (!isFeatureEnabled('onboardingLayer')) {
      setHasDemoData(false);
      return;
    }

    const checkDemoData = async () => {
      try {
        const data = await apiClient('/api/demo-data', {
          method: 'GET'
        });
        setHasDemoData(data.hasDemoData);
      } catch (error) {
        console.error('Error checking demo data:', error);
      }
    };

    checkDemoData();

    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('storage', () => {}); // Need to reference the actual function, but for now this is ok. Better: create standard function.
      }
    };
  }, []);

  const handleDemoDataAction = async () => {
    if (!isFeatureEnabled('onboardingLayer')) {
      toast.error('Onboarding layer is disabled');
      return;
    }

    setLoading(true);

    try {
      const result = await apiClient('/api/demo-data', {
        method: 'POST',
        body: JSON.stringify({
          action: hasDemoData ? 'delete' : 'generate'
        })
      });

      if (result.success) {
        if (hasDemoData) {
          toast.success('Demo data deleted successfully');
          setHasDemoData(false);
        } else {
          toast.success('Demo data loaded successfully');
          setHasDemoData(true);
          onDemoDataLoaded?.();
        }
      } else {
        toast.error(result.message || `Failed to ${hasDemoData ? 'delete' : 'generate'} demo data`);
      }
    } catch (error) {
      toast.error(`Failed to ${hasDemoData ? 'delete' : 'generate'} demo data: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setLoading(false);
    }
  };

  // Only show if feature is enabled
  if (!isFeatureEnabled('onboardingLayer')) {
    return null;
  }

  return (
    <Button
      onClick={handleDemoDataAction}
      disabled={loading || (!hasDemoData && !isLabActive)}
      variant={hasDemoData ? "destructive" : "default"}
      className="flex items-center gap-2"
    >
      {loading ? (
        <>
          <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
          {hasDemoData ? 'Deleting...' : 'Loading...'}
        </>
      ) : (
        <>
          {hasDemoData ? <RotateCcw className="h-4 w-4" /> : <Database className="h-4 w-4" />}
          {hasDemoData ? 'Delete Demo Data' : 'Load Demo Workspace'}
        </>
      )}
    </Button>
  );
}

import { DateSelector } from "@/components/ui/selectors/DateSelector";
import { TimeSelector } from "@/components/ui/selectors/TimeSelector";
import { DropdownSelector } from "@/components/ui/selectors/DropdownSelector";
import { format } from "date-fns";
import { Users } from "lucide-react";
import { useFormState } from "@/hooks/useFormState";
import { useFormSubmit } from "@/hooks/useFormSubmit";
import { DraftIndicator } from "@/components/ui/DraftIndicator";

export default function EditEventModalAdmin({
  open,
  onClose,
  eventId = "default-id" // Default ID since it's mock
}: {
  open: boolean;
  onClose: () => void;
  eventId?: string;
}) {
  const { state: formData, setState: setFormData, clearDraft, isDraftSaved } = useFormState({
    key: `draft:event:${eventId}`,
    initialState: {
      title: "Quarterly Media Strategy Meeting",
      desc: "Review of Q3 performance and planning for Q4 content calendar and campaigns.",
      start: "2023-10-26T10:00",
      end: "2023-10-26T11:30",
      loc: "https://meet.google.com/tha-iba-grdn",
      visibility: "Media Team",
      resources: "Conference Room A"
    }
  });

  const { title, desc, start, end, loc, visibility, resources } = formData;
  const setTitle = (val: string) => setFormData(prev => ({ ...prev, title: val }));
  const setDesc = (val: string) => setFormData(prev => ({ ...prev, desc: val }));
  const setStart = (val: string) => setFormData(prev => ({ ...prev, start: val }));
  const setEnd = (val: string) => setFormData(prev => ({ ...prev, end: val }));
  const setLoc = (val: string) => setFormData(prev => ({ ...prev, loc: val }));
  const setVisibility = (val: string) => setFormData(prev => ({ ...prev, visibility: val }));
  const setResources = (val: string) => setFormData(prev => ({ ...prev, resources: val }));

  if (!open) return null;

  const submitUpdate = async () => {
    // Save logic
    await new Promise(resolve => setTimeout(resolve, 500)); // Mock network delay
  };

  const { isSubmitting, handleSubmit } = useFormSubmit({
    onSubmit: submitUpdate,
    onSuccess: () => {
      clearDraft();
      onClose();
    }
  });

  const handleSave = async () => {
    await handleSubmit(undefined);
  };

  return (
    <>
      <div className="fixed inset-0 z-[60] bg-black/50 backdrop-blur-sm" onClick={onClose} />

      <div className="fixed inset-x-0 bottom-0 z-[70] mx-auto max-w-xl rounded-t-2xl bg-[#1E1E1E] p-4">
        <header className="mb-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <h3 className="text-lg font-bold">Edit Event</h3>
            <DraftIndicator isSaved={isDraftSaved} />
          </div>
          <button onClick={onClose} className="text-foreground/70 hover:text-foreground">✕</button>
        </header>

        <div className="space-y-6">
          {/* Title / Description */}
          <section className="rounded-lg bg-[#2c2c2c] p-4 shadow-lg">
            <label className="flex flex-col">
              <p className="pb-2 text-base font-bold">Event Title</p>
              <input
                className="h-12 rounded-lg bg-[#121212] px-4 focus:outline-none focus:ring-2 focus:ring-[#00BFA6]"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
              />
            </label>

            <label className="mt-4 flex flex-col">
              <p className="pb-2 text-base font-bold">Description</p>
              <textarea
                rows={4}
                className="rounded-lg bg-[#121212] p-4 focus:outline-none focus:ring-2 focus:ring-[#00BFA6]"
                value={desc}
                onChange={(e) => setDesc(e.target.value)}
              />
            </label>
          </section>

          {/* Time + Location */}
          <section className="rounded-lg bg-[#2c2c2c] p-4 shadow-lg">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-4">
                <DateSelector 
                  label="Start Date"
                  date={new Date(start)}
                  onChange={(date) => {
                    if (!date) return;
                    const newDate = new Date(date);
                    const current = new Date(start);
                    newDate.setHours(current.getHours());
                    newDate.setMinutes(current.getMinutes());
                    setStart(newDate.toISOString());
                  }}
                />
                <TimeSelector 
                  label="Start Time"
                  value={format(new Date(start), "HH:mm")}
                  onChange={(time) => {
                    const [h, m] = time.split(':').map(Number);
                    const newDate = new Date(start);
                    newDate.setHours(h);
                    newDate.setMinutes(m);
                    setStart(newDate.toISOString());
                  }}
                />
              </div>
              <div className="space-y-4">
                <DateSelector 
                  label="End Date"
                  date={new Date(end)}
                  onChange={(date) => {
                    if (!date) return;
                    const newDate = new Date(date);
                    const current = new Date(end);
                    newDate.setHours(current.getHours());
                    newDate.setMinutes(current.getMinutes());
                    setEnd(newDate.toISOString());
                  }}
                />
                <TimeSelector 
                  label="End Time"
                  value={format(new Date(end), "HH:mm")}
                  onChange={(time) => {
                    const [h, m] = time.split(':').map(Number);
                    const newDate = new Date(end);
                    newDate.setHours(h);
                    newDate.setMinutes(m);
                    setEnd(newDate.toISOString());
                  }}
                />
              </div>
            </div>

            <label className="mt-4 flex flex-col">
              <p className="pb-2 text-base font-bold">Location / Meeting Link</p>
              <input value={loc} onChange={(e) => setLoc(e.target.value)} className="h-12 rounded-lg bg-[#121212] px-4" />
            </label>
          </section>

          {/* Admin-only extras */}
          <section className="rounded-lg bg-[#2c2c2c] p-4 shadow-lg">
            <div className="space-y-0.5">
              <DropdownSelector 
                label="Visibility / Audience"
                value={visibility}
                onChange={(val) => setVisibility(val)}
                options={[
                  { id: 'All Employees', label: 'All Employees', icon: <Users size={14} /> },
                  { id: 'Media Team', label: 'Media Team', icon: <Users size={14} /> },
                  { id: 'Branch Heads', label: 'Branch Heads', icon: <Users size={14} /> },
                  { id: 'Custom', label: 'Custom', icon: <Users size={14} /> },
                ]}
              />
            </div>

            <label className="mt-4 flex flex-col">
              <p className="pb-2 text-base font-bold">Resources / Rooms</p>
              <input value={resources} onChange={(e) => setResources(e.target.value)} className="h-12 rounded-lg bg-[#121212] px-4" />
            </label>
          </section>

          <div className="flex flex-col gap-3 pt-2 sm:flex-row">
            <button onClick={handleSave} disabled={isSubmitting} className="h-12 flex-1 rounded-lg bg-[#00BFA6] font-bold text-black flex items-center justify-center gap-2 disabled:opacity-50">
                {isSubmitting && <div className="w-4 h-4 rounded-full border-2 border-black/30 border-t-black animate-spin" />}
                Save Changes
            </button>
            <button onClick={onClose} disabled={isSubmitting} className="h-12 flex-1 rounded-lg border border-foreground/30 disabled:opacity-50">Cancel</button>
          </div>
        </div>
      </div>
    </>
  );
}

// src/components/FeatureFlagProvider.tsx
// Feature flag context provider for the frontend

'use client';

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { FeatureFlag, isFeatureEnabled, getAllFeatureFlags } from '@/app/featureFlags';
import { apiClient } from '@/lib/apiClient';

interface FeatureFlagContextType {
  flags: Record<FeatureFlag, boolean>;
  isFeatureEnabled: (feature: FeatureFlag) => boolean;
  refreshFlags: () => Promise<void>;
}

const FeatureFlagContext = createContext<FeatureFlagContextType | undefined>(undefined);

export function FeatureFlagProvider({ children }: { children: ReactNode }) {
  const [flags, setFlags] = useState<Record<FeatureFlag, boolean>>(getAllFeatureFlags());

  const checkFeatureEnabled = (feature: FeatureFlag): boolean => {
    return flags[feature] ?? false;
  };

  const refreshFlags = async (): Promise<void> => {
    try {
      // In development, we can fetch from the API
      if (process.env.NODE_ENV === 'development' || process.env.NEXT_PUBLIC_E2E === '1') {
        const data = await apiClient('/api/admin/feature-flags');
        setFlags(data.flags);
        return;
      }
      
      // In production, use the default implementation
      setFlags(getAllFeatureFlags());
    } catch (error) {
      console.error('Failed to refresh feature flags:', error);
      // Fallback to default flags
      setFlags(getAllFeatureFlags());
    }
  };

  useEffect(() => {
    refreshFlags();
  }, []);

  return (
    <FeatureFlagContext.Provider value={{
      flags,
      isFeatureEnabled: checkFeatureEnabled,
      refreshFlags
    }}>
      {children}
    </FeatureFlagContext.Provider>
  );
}

export function useFeatureFlags() {
  const context = useContext(FeatureFlagContext);
  if (context === undefined) {
    throw new Error('useFeatureFlags must be used within a FeatureFlagProvider');
  }
  return context;
}

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { isFeatureEnabled } from '@/app/featureFlags';

interface WalkthroughStep {
  id: string;
  title: string;
  description: string;
  elementId: string;
  position: 'top' | 'bottom' | 'left' | 'right' | 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';
}

interface FirstRunWalkthroughProps {
  onComplete?: () => void;
}

export function FirstRunWalkthrough({ onComplete }: FirstRunWalkthroughProps) {
  const [currentStep, setCurrentStep] = useState<number | null>(null);
  const [showWalkthrough, setShowWalkthrough] = useState(false);
  const [visited, setVisited] = useState(false);

  // Check if user has already seen the walkthrough
  useEffect(() => {
    if (!isFeatureEnabled('onboardingLayer')) {
      return;
    }

    const hasSeenWalkthrough = localStorage.getItem('hasSeenWalkthrough');
    if (!hasSeenWalkthrough) {
      setShowWalkthrough(true);
      // Set a small timeout to ensure the DOM elements are rendered
      setTimeout(() => setCurrentStep(0), 500);
    } else {
      setVisited(true);
    }
  }, []);

  const walkthroughSteps: WalkthroughStep[] = [
    {
      id: 'media-gallery',
      title: 'Media Gallery',
      description: 'Upload, review, and collaborate on media files. Use the proofing tools to approve or request changes.',
      elementId: 'media-gallery-section',
      position: 'bottom'
    },
    {
      id: 'admin-confidence',
      title: 'Admin Confidence Panel',
      description: 'Monitor workflow bottlenecks and task status. This panel shows blocked tasks, ready tasks, and stale items.',
      elementId: 'admin-confidence-panel',
      position: 'top'
    },
    {
      id: 'proofing-flow',
      title: 'Proofing Flow',
      description: 'Review media files, approve them, or request changes. Track versions and comments for each file.',
      elementId: 'proofing-section',
      position: 'right'
    }
  ];

  const handleNext = () => {
    if (currentStep !== null && currentStep < walkthroughSteps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      handleComplete();
    }
  };

  const handlePrev = () => {
    if (currentStep !== null && currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleComplete = () => {
    localStorage.setItem('hasSeenWalkthrough', 'true');
    setShowWalkthrough(false);
    setCurrentStep(null);
    setVisited(true);
    onComplete?.();
  };

  const handleSkip = () => {
    localStorage.setItem('hasSeenWalkthrough', 'true');
    setShowWalkthrough(false);
    setCurrentStep(null);
    setVisited(true);
  };

  // Only show if feature is enabled and user hasn't seen it yet
  if (!isFeatureEnabled('onboardingLayer') || !showWalkthrough || currentStep === null || visited) {
    return null;
  }

  const currentStepData = walkthroughSteps[currentStep];
  const totalSteps = walkthroughSteps.length;

  // Scroll to relevant section if needed
  useEffect(() => {
    if (currentStepData) {
      const element = document.getElementById(currentStepData.elementId);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [currentStepData]);

  return (
    <div className="fixed inset-0 z-[1000] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-foreground/90 dark:bg-gray-800/90 text-foreground/20 dark:text-foreground p-6 rounded-xl shadow-2xl border border-gray-200 dark:border-gray-700 max-w-md w-full">
        <div className="flex justify-between items-start mb-3">
          <h3 className="font-bold text-lg">{currentStepData.title}</h3>
          <span className="text-sm text-foreground/50 dark:text-foreground/60">
            {currentStep + 1} of {totalSteps}
          </span>
        </div>
        <p className="text-foreground/30 dark:text-foreground mb-4">
          {currentStepData.description}
        </p>
        <div className="flex justify-between items-center">
          <Button 
            variant="outline" 
            size="sm"
            onClick={handleSkip}
            className="border-gray-300 dark:border-gray-600"
          >
            Skip
          </Button>
          <div className="flex gap-2">
            {currentStep > 0 && (
              <Button 
                variant="outline" 
                size="sm"
                onClick={handlePrev}
                className="border-gray-300 dark:border-gray-600"
              >
                Back
              </Button>
            )}
            <Button 
              size="sm"
              onClick={handleNext}
            >
              {currentStep === totalSteps - 1 ? 'Complete' : 'Next'}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

