    Building2,
    ShieldCheck,
    Activity,
    Settings,
    ChevronLeft,
    ChevronRight,
    ShieldAlert,
    BarChart3,
    Sliders
} from 'lucide-react';
import { cn } from "@/lib/utils";
import { useAuth } from '@/contexts/AuthContextProvider';

const adminNavItems = [
    { id: 'overview', label: 'Overview', icon: LayoutDashboard, path: '/admin', minRole: 'manager' },
    { id: 'users', label: 'Users', icon: Users, path: '/admin/users', minRole: 'manager' },
    { id: 'leave-analytics', label: 'Leave Analytics', icon: BarChart3, path: '/admin/leave-analytics', minRole: 'manager' },
    { id: 'workspaces', label: 'Workspaces', icon: Building2, path: '/admin/workspaces', minRole: 'admin' },
    { id: 'permissions', label: 'Permissions', icon: ShieldCheck, path: '/admin/security', minRole: 'admin' },
    { id: 'activity', label: 'Activity Logs', icon: Activity, path: '/admin/activity', minRole: 'admin' },
    { id: 'features', label: 'Feature Config', icon: Sliders, path: '/admin/settings/features', minRole: 'admin' },
    { id: 'settings', label: 'Global Setup', icon: Settings, path: '/admin/structure', minRole: 'admin' },
];

export default function AdminSidebar() {
    const { user } = useAuth();
    const router = useRouter();
    const pathname = usePathname();
    const [isCollapsed, setIsCollapsed] = useState(false);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        const saved = localStorage.getItem('admin-sidebar-collapsed');
        if (saved === 'true') {
            setIsCollapsed(true);
            updatePadding(true);
        } else {
            updatePadding(false);
        }
    }, []);

    const updatePadding = (collapsed: boolean) => {
        const width = collapsed ? '72px' : '240px';
        document.documentElement.style.setProperty('--admin-sidebar-width', width);
    };

    const toggleCollapse = () => {
        const next = !isCollapsed;
        setIsCollapsed(next);
        localStorage.setItem('admin-sidebar-collapsed', String(next));
        updatePadding(next);
    };

    if (!mounted) return null;

    // Filter items based on role
    const filteredItems = adminNavItems.filter(item => {
        if (user?.role === 'admin') return true;
        if (user?.role === 'manager') return item.minRole === 'manager';
        return false;
    });

    return (
        <motion.aside 
            initial={false}
            animate={{ width: isCollapsed ? '88px' : '260px' }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            className="fixed left-6 top-1/2 -translate-y-1/2 z-[70] hidden lg:flex flex-col h-fit max-h-[calc(100vh-6rem)] rounded-[36px] glass-liquid border-foreground/10 shadow-2xl overflow-hidden backdrop-blur-xl"
        >
            <div className="p-4 space-y-6 flex-1 flex flex-col">
                <div className={cn("px-2 py-3 flex items-center gap-3", isCollapsed ? "justify-center" : "")}>
                    <div className="w-10 h-10 rounded-2xl bg-indigo-500/20 flex items-center justify-center text-indigo-400 shadow-lg shadow-indigo-500/10 shrink-0">
                        <ShieldAlert size={20} />
                    </div>
                    <AnimatePresence mode="wait">
                        {!isCollapsed && (
                            <motion.div
                                initial={{ opacity: 0, x: -10 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -10 }}
                                transition={{ duration: 0.2 }}
                            >
                                <h2 className="text-sm font-black text-foreground tracking-tight">Admin Panel</h2>
                                <p className="text-[10px] font-bold text-foreground/70 uppercase tracking-[0.2em]">Global Control</p>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>

                <nav className="flex-1 space-y-1">
                    {filteredItems.map((item) => {
                        const isActive = pathname === item.path;
                        return (
                            <button
                                key={item.id}
                                onClick={() => router.push(item.path)}
                                title={isCollapsed ? item.label : undefined}
                                className={cn(
                                    "group relative w-full flex items-center gap-3 p-3.5 rounded-2xl transition-all duration-300",
                                    isActive 
                                        ? "bg-foreground/10 text-foreground shadow-xl shadow-black/20" 
                                        : "text-foreground/80 hover:bg-foreground/5 hover:text-foreground",
                                    isCollapsed ? "justify-center" : ""
                                )}
                            >
                                <item.icon size={20} className={cn("transition-all duration-300 group-hover:scale-110 group-active:scale-95 shrink-0", isActive ? "text-indigo-400" : "")} />
                                <AnimatePresence mode="wait">
                                    {!isCollapsed && (
                                        <motion.span 
                                            initial={{ opacity: 0, x: -10 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            exit={{ opacity: 0, x: -10 }}
                                            transition={{ duration: 0.2 }}
                                            className="text-sm font-bold tracking-tight whitespace-nowrap"
                                        >
                                            {item.label}
                                        </motion.span>
                                    )}
                                </AnimatePresence>
                                {isActive && (
                                    <motion.div 
                                        layoutId="admin-active-pill"
                                        className="absolute left-0 w-1 h-5 bg-indigo-500 rounded-r-full"
                                        transition={{ type: "spring", stiffness: 300, damping: 30 }}
                                    />
                                )}
                            </button>
                        );
                    })}
                </nav>

                <div className="pt-4 border-t border-foreground/5 space-y-2">
                    <button 
                        onClick={() => router.push('/home')}
                        className={cn("group w-full flex items-center gap-3 p-3.5 rounded-2xl text-foreground/80 hover:bg-foreground/5 hover:text-foreground transition-all", isCollapsed ? "justify-center" : "")}
                        title={isCollapsed ? "Exit Admin" : undefined}
                    >
                        <ChevronLeft size={20} className="shrink-0 transition-transform group-hover:-translate-x-1" />
                        {!isCollapsed && <span className="text-sm font-bold">Exit Admin</span>}
                    </button>
                    
                    <button 
                        onClick={toggleCollapse}
                        className={cn("w-full flex items-center gap-3 p-3.5 rounded-2xl text-foreground/80 hover:bg-foreground/5 hover:text-foreground/80 transition-all", isCollapsed ? "justify-center" : "")}
                    >
                        {isCollapsed ? <ChevronRight size={20} className="animate-pulse" /> : (
                            <div className="flex items-center gap-3 w-full">
                                <ChevronLeft size={20} />
                                <span className="text-xs font-black uppercase tracking-widest">Collapse</span>
                            </div>
                        )}
                    </button>
                </div>
            </div>
        </motion.aside>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { AutomationRule, RuleAction, ConditionOperator } from '@/types/automation-rules';
import { Loader2, Plus, Lock, Send, ShieldAlert, Archive, Copy, Play, Info, ChevronRight, Zap, AlertTriangle, ChevronDown } from 'lucide-react';
import AppLink from '@/components/AppLink';
import { apiClient } from '@/lib/apiClient';
import { DropdownSelector } from '@/components/ui/selectors/DropdownSelector';

interface RulesData {
    custom: AutomationRule[];
    system: any[];
}

export default function AutomationRulesView() {
    const [data, setData] = useState<RulesData>({ custom: [], system: [] });
    const [loading, setLoading] = useState(true);
    const [isEditorOpen, setIsEditorOpen] = useState(false);
    const [editingRule, setEditingRule] = useState<AutomationRule | null>(null);

    const fetchRules = async () => {
        setLoading(true);
        try {
            const json = await apiClient('/api/admin/automation-rules');
            setData(json);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchRules();
    }, []);

    const handleCreate = () => {
        setEditingRule(null);
        setIsEditorOpen(true);
    };

    const handleEdit = (rule: AutomationRule) => {
        if (rule.locked) return;
        setEditingRule(rule);
        setIsEditorOpen(true);
    };

    const handleClone = (rule: AutomationRule) => {
        const draft = {
            ...rule,
            id: '',
            version: 0,
            locked: false,
            enabled: false
        };
        setEditingRule(draft);
        setIsEditorOpen(true);
    };

    const handleActivate = async (id: string) => {
        if (!confirm('Activate this rule? Previous versions will be disabled.')) return;
        try {
            await apiClient('/api/admin/automation-rules', {
                method: 'PATCH',
                body: JSON.stringify({ id, command: 'activate' })
            });
            fetchRules();
        } catch (e) {
            alert('Failed to activate');
        }
    };

    const handleSave = async (rule: Partial<AutomationRule>) => {
        try {
            const method = rule.id && rule.version ? 'PUT' : 'POST';
            await apiClient('/api/admin/automation-rules', {
                method,
                body: JSON.stringify(rule)
            });
            setIsEditorOpen(false);
            fetchRules();
        } catch (e) {
            alert('Error saving');
        }
    };

    const activeRules = data.custom.filter(r => r.enabled);
    const drafts = data.custom.filter(r => !r.enabled);

    return (
        <div className="min-h-screen bg-background text-foreground">
            <div className="max-w-[1400px] mx-auto px-6 py-10 space-y-12">

                {/* Header & Warning Panel */}
                <div className="space-y-8">
                    <div className="flex flex-col md:flex-row justify-between items-start gap-6 border-b border-soft pb-8">
                        <div>
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2.5 bg-indigo-500/10 rounded-xl text-indigo-500 border border-indigo-500/20 shadow-inner">
                                    <Zap size={24} className="fill-indigo-500/20" />
                                </div>
                                <h1 className="text-3xl font-bold tracking-tight text-foreground">Automation Engine</h1>
                            </div>
                            <p className="text-muted max-w-2xl font-light text-lg">
                                Advanced control plane for logic resolution, scope priority, and event triggers.
                            </p>
                        </div>
                        <button
                            onClick={handleCreate}
                            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-foreground rounded-xl transition-all font-semibold shadow-xl shadow-indigo-900/20 hover:scale-[1.02]"
                        >
                            <Plus className="w-5 h-5" />
                            Create Custom Rule
                        </button>
                    </div>

                    {/* Disclaimer Alert */}
                    <div className="relative overflow-hidden flex items-start gap-5 p-5 rounded-2xl border border-amber-500/20 bg-amber-500/5 backdrop-blur-sm">
                        <div className="absolute top-0 right-0 p-3 opacity-10">
                            <AlertTriangle className="w-32 h-32 text-amber-500 rotate-12" />
                        </div>
                        <div className="p-2 bg-amber-500/10 rounded-lg shrink-0 text-amber-500">
                            <Info className="w-6 h-6" />
                        </div>
                        <div className="space-y-1 z-10">
                            <h4 className="text-base font-semibold text-amber-600 tracking-wide uppercase text-xs">Advanced Configuration</h4>
                            <p className="text-amber-900/80 dark:text-amber-100/70 leading-relaxed max-w-3xl">
                                This interface exposes raw engine logic. For standard notification settings (reminders, due dates), use the <AppLink href="/admin/system-health" className="text-amber-600 hover:text-amber-700 underline underline-offset-4 decoration-amber-500/30 font-medium">System Health Dashboard</AppLink>. Changes here override global defaults and may affect system stability.
                            </p>
                        </div>
                    </div>
                </div>

                {loading ? (
                    <div className="flex justify-center p-32">
                        <Loader2 className="w-12 h-12 text-indigo-500 animate-spin opacity-50" />
                    </div>
                ) : (
                    <div className="grid grid-cols-1 xl:grid-cols-12 gap-10 items-start">

                        {/* Main Column: Active & Drafts (8 cols) */}
                        <div className="xl:col-span-8 space-y-16">
                            {/* Active Rules Section */}
                            <section className="space-y-6">
                                <div className="flex items-center gap-3">
                                    <h2 className="text-xl font-bold text-foreground flex items-center gap-3">
                                        <span className="flex w-3 h-3 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)] animate-pulse" />
                                        Active Overrides
                                    </h2>
                                    <span className="px-2.5 py-0.5 rounded-full bg-foreground/5 text-xs text-foreground/60 font-mono border border-foreground/5">{activeRules.length}</span>
                                </div>

                                {activeRules.length === 0 ? (
                                    <div className="p-12 text-center rounded-3xl border border-dashed border-soft bg-surface/50">
                                        <p className="text-muted font-mono text-sm">No custom overrides active. System defaults are in control.</p>
                                    </div>
                                ) : (
                                    <div className="grid gap-5">
                                        {activeRules.map(rule => (
                                            <RuleCard
                                                key={rule.id}
                                                rule={rule}
                                                onEdit={handleEdit}
                                                onClone={handleClone}
                                                onActivate={handleActivate}
                                                variant="active"
                                            />
                                        ))}
                                    </div>
                                )}
                            </section>

                            {/* Drafts Section */}
                            {drafts.length > 0 && (
                                <section className="space-y-6">
                                    <div className="flex items-center gap-3 opacity-60 hover:opacity-100 transition-opacity">
                                        <h2 className="text-lg font-bold text-muted flex items-center gap-3">
                                            <span className="w-2.5 h-2.5 rounded-full bg-amber-500/50" />
                                            Drafts & Inactive
                                        </h2>
                                        <span className="px-2 py-0.5 rounded-full bg-surface text-xs text-muted font-mono border border-soft">{drafts.length}</span>
                                    </div>
                                    <div className="grid gap-4 opacity-80">
                                        {drafts.map(rule => (
                                            <RuleCard
                                                key={rule.id}
                                                rule={rule}
                                                onEdit={handleEdit}
                                                onClone={handleClone}
                                                onActivate={handleActivate}
                                                variant="draft"
                                            />
                                        ))}
                                    </div>
                                </section>
                            )}
                        </div>

                        <div className="xl:col-span-4 space-y-6 xl:sticky xl:top-8">
                            <div className="flex items-center gap-2 pb-4 border-b border-soft">
                                <Lock className="w-4 h-4 text-muted" />
                                <h2 className="text-sm font-bold text-muted uppercase tracking-widest">System Defaults</h2>
                            </div>
                            <div className="grid gap-3 opacity-60 grayscale hover:grayscale-0 hover:opacity-100 transition-all duration-500 ease-out">
                                {data.system.map((rule: any) => (
                                    <RuleCard
                                        key={rule.id}
                                        rule={rule}
                                        readOnly
                                        variant="locked"
                                    />
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {isEditorOpen && (
                <RuleEditor
                    initialData={editingRule}
                    onClose={() => setIsEditorOpen(false)}
                    onSave={handleSave}
                />
            )}
        </div>
    );
}

function RuleCard({ rule, readOnly, onEdit, onClone, onActivate, variant = 'active' }: any) {
    const [expanded, setExpanded] = useState(false);

    // Visual Variants
    const isLocked = variant === 'locked';
    const isDraft = variant === 'draft';
    const isActive = variant === 'active';

    const baseStyles = isLocked
        ? 'bg-transparent border border-soft text-muted' // Ghosted
        : isDraft
            ? 'bg-muted/5 border border-dashed border-soft' // Draft
            : 'bg-surface border border-soft shadow-sm'; // Active

    const actionColors = {
        notify: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
        escalate: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
        suppress: 'bg-slate-500/10 text-foreground/60 border-slate-500/20',
        audit: 'bg-blue-500/10 text-blue-400 border-blue-500/20'
    };

    const actionColor = actionColors[rule.action as keyof typeof actionColors] || actionColors.notify;

    return (
        <div className={`
            group relative p-5 rounded-xl transition-all duration-300
            ${baseStyles}
            ${!isLocked && 'hover:border-indigo-500/30'}
        `}>
            {/* Active Indicator Strip */}
            {isActive && <div className="absolute left-0 top-4 bottom-4 w-1 bg-indigo-500 rounded-r-full shadow-[0_0_10px_rgba(99,102,241,0.5)]" />}

            {/* Main Row */}
            <div className={`flex justify-between items-start gap-4 ${isActive ? 'pl-3' : ''}`}>

                {/* Visual Logic: Action -> Scope -> Key */}
                <div className="flex flex-col gap-3 flex-1 min-w-0">

                    {/* Top Row: Action & Scope */}
                    <div className="flex items-center flex-wrap gap-2">
                        <div className={`
                            px-2.5 py-1 rounded text-[11px] font-bold uppercase tracking-wider border
                            ${isLocked ? 'bg-slate-800 border-slate-700 text-foreground/50' : actionColor}
                        `}>
                            {rule.action}
                        </div>

                        <div className="flex items-center gap-1.5 px-2 py-1 rounded bg-foreground/5 border border-foreground/5 text-xs font-mono text-foreground/60">
                            <span className={isActive ? 'text-indigo-300' : ''}>{rule.scopeType}</span>
                            {rule.scopeId !== 'global' && (
                                <>
                                    <span className="text-foreground/40">/</span>
                                    <span className="text-foreground truncate max-w-[120px]">{rule.scopeId}</span>
                                </>
                            )}
                        </div>

                        {rule.priority > 0 && !isLocked && (
                            <span className="text-[10px] text-orange-400/80 font-mono px-1.5 border border-orange-500/20 rounded">
                                PRI:{rule.priority}
                            </span>
                        )}
                    </div>

                    {/* Key (De-emphasized) */}
                    <div className="min-w-0">
                        <h3 className={`font-mono text-sm truncate opacity-70 ${isLocked ? 'text-muted' : 'text-foreground'}`} title={rule.ruleKey}>
                            {rule.ruleKey}
                        </h3>
                    </div>
                </div>

                {/* Right: Actions */}
                <div className="flex items-center gap-1 shrink-0">
                    {!readOnly && rule.locked && (
                        <button onClick={() => onClone(rule)} className="p-2 text-foreground/40 hover:text-foreground hover:bg-foreground/5 rounded-lg transition-colors" title="Clone as Draft">
                            <Copy className="w-4 h-4" />
                        </button>
                    )}
                    {!readOnly && !rule.locked && (
                        <>
                            <button onClick={() => onActivate(rule.id)} className="p-2 text-emerald-500/50 hover:text-emerald-400 hover:bg-emerald-500/10 rounded-lg transition-colors" title="Activate">
                                <Play className="w-4 h-4" />
                            </button>
                            <button onClick={() => onEdit(rule)} className="p-2 text-blue-500/50 hover:text-blue-400 hover:bg-blue-500/10 rounded-lg transition-colors" title="Edit">
                                <span className="text-[10px] font-bold">EDIT</span>
                            </button>
                        </>
                    )}

                    {/* Toggle Expand */}
                    <button
                        onClick={() => setExpanded(!expanded)}
                        className={`p-2 rounded-lg transition-all ${expanded ? 'bg-foreground/10 text-foreground' : 'text-foreground/30 hover:text-foreground/60'}`}
                    >
                        <ChevronRight className={`w-4 h-4 transition-transform ${expanded ? 'rotate-90' : ''}`} />
                    </button>
                </div>
            </div>

            {/* Expanded Details */}
            {expanded && (
                <div className="mt-4 pt-4 border-t border-foreground/5 space-y-4 animate-in slide-in-from-top-1 duration-200">
                    <div className="grid gap-2">
                        <label className="text-[10px] font-bold text-muted uppercase tracking-widest pl-1">Conditions</label>
                        {rule.conditions.map((c: any, i: number) => (
                            <div key={i} className={`
                                flex items-center gap-3 text-sm font-mono p-2 rounded border
                                ${isLocked ? 'bg-transparent border-soft text-muted' : 'bg-muted/5 border-soft'}
                            `}>
                                <span className={isLocked ? '' : 'text-blue-500'}>{c.field}</span>
                                <span className="text-muted text-xs">{c.operator}</span>
                                <span className={isLocked ? '' : 'text-amber-500'}>{String(c.value)}</span>
                            </div>
                        ))}
                    </div>
                    {rule.eventType && (
                        <div className="flex items-center gap-2 px-2">
                            <span className="text-[10px] uppercase tracking-wider text-foreground/40">Trigger:</span>
                            <span className="text-xs text-foreground/50 font-mono">{rule.eventType}</span>
                        </div>
                    )}
                    <div className="flex justify-end pt-2">
                        <span className="text-[10px] text-foreground/30 font-mono">ID: {rule.id || 'NEW'}</span>
                    </div>
                </div>
            )}
        </div>
    );
}

function RuleEditor({ initialData, onClose, onSave }: any) {
    const [formData, setFormData] = useState<Partial<AutomationRule>>({
        ruleKey: '',
        scopeType: 'global',
        scopeId: 'global',
        eventType: 'task_overdue',
        action: 'notify',
        priority: 1,
        conditions: [],
        ...initialData
    });

    const isEdit = !!initialData?.id;

    const updateCondition = (idx: number, field: string, value: any) => {
        const newConditions = [...(formData.conditions || [])];
        newConditions[idx] = { ...newConditions[idx], [field]: value };
        setFormData({ ...formData, conditions: newConditions });
    };

    const addCondition = () => {
        setFormData({ ...formData, conditions: [...(formData.conditions || []), { field: '', operator: 'eq', value: '' }] });
    };

    const removeCondition = (idx: number) => {
        setFormData({ ...formData, conditions: (formData.conditions || []).filter((_, i) => i !== idx) });
    };

    return (
        <div className="fixed inset-0 bg-background/90 backdrop-blur-sm flex items-center justify-center p-4 z-50">
            {/* Modal Content - Styled for Night Sky */}
            <div className="bg-surface border border-soft rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl ring-1 ring-soft">
                <div className="p-6 border-b border-soft sticky top-0 bg-surface/95 backdrop-blur z-10 flex justify-between items-center">
                    <div>
                        <h2 className="text-lg font-bold text-foreground">
                            {isEdit && !initialData.locked ? 'Edit Rule Draft' : 'New Rule Draft'}
                        </h2>
                        <p className="text-xs text-muted mt-0.5">Define logic and outcomes manually.</p>
                    </div>
                    <button onClick={onClose} className="p-2 text-muted hover:text-foreground hover:bg-muted/10 rounded-lg transition-colors">✕</button>
                </div>

                <div className="p-8 space-y-8">
                    <div className="grid grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="block text-xs font-medium text-muted uppercase tracking-wide">Rule Key (Stable ID)</label>
                            <input
                                className="w-full bg-muted/5 border border-soft rounded-xl px-4 py-3 text-sm text-foreground focus:outline-none focus:border-indigo-500/50 focus:ring-1 focus:ring-indigo-500/50 transition-all font-mono placeholder:text-muted"
                                value={formData.ruleKey}
                                onChange={e => setFormData({ ...formData, ruleKey: e.target.value })}
                                disabled={isEdit && !!formData.id}
                                placeholder="e.g. task_overdue_custom"
                            />
                        </div>
                        <div className="space-y-0.5">
                            <DropdownSelector 
                                label="Event Trigger"
                                value={formData.eventType || ''}
                                onChange={val => setFormData({ ...formData, eventType: val })}
                                options={['task_due_soon', 'task_overdue', 'task_stale_warning', 'task_stale_escalation', 'inventory_due_soon', 'inventory_overdue', 'inventory_escalated'].map(e => ({ id: e, label: e }))}
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-3 gap-6">
                        <div className="space-y-0.5">
                            <DropdownSelector 
                                label="Scope Type"
                                value={formData.scopeType || ''}
                                onChange={val => setFormData({ ...formData, scopeType: val as any })}
                                options={[
                                    { id: 'global', label: 'Global' },
                                    { id: 'institution', label: 'Institution' },
                                    { id: 'unit', label: 'Unit' }
                                ]}
                            />
                        </div>
                        <div className="col-span-2 space-y-2">
                            <label className="block text-xs font-medium text-muted uppercase tracking-wide">Scope ID (Optional for Global)</label>
                            <input
                                className="w-full bg-muted/5 border border-soft rounded-xl px-4 py-3 text-sm text-foreground focus:outline-none focus:border-indigo-500/50 font-mono placeholder:text-muted"
                                value={formData.scopeId}
                                onChange={e => setFormData({ ...formData, scopeId: e.target.value })}
                                placeholder="Global ID or Specific Unit ID"
                            />
                        </div>
                    </div>

                    {/* Conditions */}
                    <div className="space-y-4 p-5 rounded-2xl bg-muted/5 border border-soft">
                        <div className="flex justify-between items-center">
                            <label className="block text-xs font-bold text-muted uppercase tracking-widest">Logic Conditions (AND)</label>
                            <button onClick={addCondition} className="text-xs text-indigo-400 hover:text-indigo-300 flex items-center gap-1.5 font-bold transition-colors uppercase tracking-wide">
                                <Plus className="w-3.5 h-3.5" /> Add Condition
                            </button>
                        </div>
                        <div className="space-y-3">
                            {formData.conditions?.length === 0 && (
                                <div className="text-center py-6 border border-dashed border-soft rounded-xl text-muted text-xs italic">
                                    No specific conditions. Rule will trigger on every event.
                                </div>
                            )}
                            {formData.conditions?.map((c, i) => (
                                <div key={i} className="flex gap-3">
                                    <input
                                        placeholder="Field (e.g. hoursOverdue)"
                                        className="flex-1 bg-muted/10 border border-soft rounded-lg px-3 py-2 text-sm text-foreground font-mono placeholder:text-muted focus:border-indigo-500/50 outline-none transition-colors"
                                        value={c.field}
                                        onChange={e => updateCondition(i, 'field', e.target.value)}
                                    />
                                    <div className="w-28 space-y-0.5">
                                        <DropdownSelector 
                                            label="Operator"
                                            value={c.operator}
                                            onChange={val => updateCondition(i, 'operator', val)}
                                            options={['eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'contains'].map(op => ({ id: op, label: op }))}
                                        />
                                    </div>
                                    <input
                                        placeholder="Value"
                                        className="w-28 bg-muted/10 border border-soft rounded-lg px-3 py-2 text-sm text-foreground font-mono placeholder:text-muted focus:border-indigo-500/50 outline-none transition-colors"
                                        value={c.value}
                                        onChange={e => updateCondition(i, 'value', e.target.value)}
                                    />
                                    <button onClick={() => removeCondition(i)} className="text-muted hover:text-rose-500 transition-colors px-2">✕</button>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Action */}
                    <div className="grid grid-cols-2 gap-6">
                        <div className="space-y-0.5">
                            <DropdownSelector 
                                label="Resulting Action"
                                value={formData.action || ''}
                                onChange={val => setFormData({ ...formData, action: val as RuleAction })}
                                options={[
                                    { id: 'notify', label: 'Notify User (Standard)' },
                                    { id: 'escalate', label: 'Escalate (Admin/Manager)' },
                                    { id: 'suppress', label: 'Suppress (Do Nothing)' },
                                    { id: 'audit', label: 'Log Only (Silent)' }
                                ]}
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="block text-xs font-medium text-muted uppercase tracking-wide">Priority Score</label>
                            <input
                                type="number"
                                className="w-full bg-muted/5 border border-soft rounded-xl px-4 py-3 text-sm text-foreground focus:outline-none focus:border-indigo-500/50 placeholder:text-muted"
                                value={formData.priority}
                                onChange={e => setFormData({ ...formData, priority: parseInt(e.target.value) })}
                                placeholder="Higher wins (e.g. 10)"
                            />
                        </div>
                    </div>
                </div>

                <div className="p-6 border-t border-soft flex justify-end gap-3 bg-muted/5 rounded-b-2xl">
                    <button onClick={onClose} className="px-5 py-2.5 text-muted hover:text-foreground text-sm font-medium transition-colors">Cancel</button>
                    <button
                        onClick={() => onSave(formData)}
                        className="px-8 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-foreground rounded-xl text-sm font-semibold shadow-xl shadow-indigo-500/20 transition-all hover:scale-[1.02]"
                    >
                        Save Rule
                    </button>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useEffect, useState } from 'react';
import { DriveQueueItem } from '@/types/drive-queue';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { RefreshCw, Check, X, ExternalLink, HardDrive, FolderOpen, Info } from 'lucide-react';
import { Checkbox } from "@/components/ui/checkbox";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { apiClient } from '@/lib/apiClient';
import { INVENTORY_GUIDE } from '@/types/inventory';

// Helper for safely parsing Firestore Timestamps (Admin SDK serializes to _seconds)
function parseFirestoreDate(value: any): Date | null {
    if (!value) return null;
    if (value instanceof Date) return value;
    if (typeof value === 'string') return new Date(value); // ISO String
    if (typeof value.toDate === 'function') return value.toDate(); // Real Timestamp object
    if (typeof value._seconds === 'number') return new Date(value._seconds * 1000); // Admin SDK serialized
    if (typeof value.seconds === 'number') return new Date(value.seconds * 1000); // Client SDK serialized
    return null;
}

export function DriveQueueView() {
    const [items, setItems] = useState<DriveQueueItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [scanning, setScanning] = useState(false);
    const [processingId, setProcessingId] = useState<string | null>(null);
    const [folderInfo, setFolderInfo] = useState<{ id: string, name: string, webViewLink: string | null } | null>(null);
    const [scanLogs, setScanLogs] = useState<string[]>([]);

    // Bulk Selection State
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

    // Modal State
    const [modalOpen, setModalOpen] = useState(false);
    const [actionType, setActionType] = useState<'approve' | 'reject' | null>(null);
    const [targetId, setTargetId] = useState<string | null>(null); // null means bulk

    // Metadata Form State
    const [metadata, setMetadata] = useState({
        name: '',
        description: '',
        visibility: 'all', // 'all' | 'internal'
        category: 'Documents', // Default fallback
        tags: '', // Comma separated
        namePrefix: '',
        nameSuffix: ''
    });

    useEffect(() => {
        loadQueue();
        loadFolderInfo();
    }, []);

    // Helper: Auto-Suggest Category
    const getAutoCategory = (mimeType: string) => {
        if (mimeType.startsWith('image/')) return 'Photos';
        if (mimeType.startsWith('video/')) return 'Videos';
        if (mimeType.startsWith('audio/')) return 'Audio';
        if (mimeType.includes('pdf') || mimeType.startsWith('text/')) return 'Documents';
        if (mimeType.includes('zip') || mimeType.includes('compressed') || mimeType.includes('tar')) return 'Archives';
        return 'Documents';
    };

    // Helper: Auto-Suggest Tags (Enhanced)
    const getAutoTags = (item: DriveQueueItem) => {
        const tags: string[] = [];

        // 1. Year Detection (Regex > Drive Date > Current)
        const nameYearMatch = item.name.match(/\b20\d{2}\b/);
        if (nameYearMatch) {
            tags.push(nameYearMatch[0]);
        } else if (item.detectedAt) {
            const date = parseFirestoreDate(item.detectedAt);
            if (date) tags.push(date.getFullYear().toString());
            else tags.push(new Date().getFullYear().toString());
        } else {
            tags.push(new Date().getFullYear().toString());
        }

        // 2. Event Extraction [Event] or (Event)
        const eventMatch = item.name.match(/[\[\(](.*?)[\]\)]/);
        if (eventMatch && eventMatch[1]) {
            tags.push(eventMatch[1].trim());
        }

        // 3. Institution / Unit Mapping
        const lowerName = item.name.toLowerCase();
        if (lowerName.includes('orchid')) tags.push('Orchids');
        if (lowerName.includes('thaiba')) tags.push('Thaiba');
        if (lowerName.includes('garden')) tags.push('Garden');
        if (lowerName.includes('koppa')) tags.push('Koppa');
        if (lowerName.includes('feroke')) tags.push('Feroke');

        // 4. Type & Source
        const type = item.mimeType.startsWith('image/') ? 'Image' :
            item.mimeType.startsWith('video/') ? 'Video' :
                item.mimeType.includes('pdf') ? 'Doc' : 'File';
        tags.push(type);
        tags.push('Drive Import');

        // 5. Extension
        const ext = item.name.includes('.') ? item.name.split('.').pop()?.toUpperCase() : '';
        if (ext && ext.length < 5) tags.push(ext);

        // Dedup
        return Array.from(new Set(tags)).filter(Boolean).join(', ');
    };

    const loadQueue = async () => {
        // ... (rest of loadQueue)

        try {
            const data = await apiClient('/api/admin/drive-queue');
            setItems(data);
            setSelectedIds(new Set());
        } catch (e) {
            console.error(e);
            toast.error('Failed to load queue');
        } finally {
            setLoading(false);
        }
    };

    const loadFolderInfo = async () => {
        try {
            const data = await apiClient('/api/admin/drive-queue/meta');
            setFolderInfo(data);
        } catch (e) {
            console.error('Failed to load folder info', e);
        }
    };

    const handleScan = async () => {
        setScanning(true);
        setScanLogs([]);
        try {
            const data = await apiClient('/api/admin/drive-queue/scan', { method: 'POST' });

            if (data.logs) {
                setScanLogs(data.logs);
            }

            toast.success(data.message);
            loadQueue();
        } catch (e: any) {
            toast.error(e.message || 'Scan failed');
        } finally {
            setScanning(false);
        }
    };

    // Open Modal for Single Action
    const initiateSingleAction = (item: DriveQueueItem, action: 'approve' | 'reject') => {
        setTargetId(item.id);
        setActionType(action);

        // Reset/Init Metadata
        if (action === 'approve') {
            setMetadata({
                name: item.name,
                description: '',
                visibility: 'all', // Default to public
                category: getAutoCategory(item.mimeType), // Auto-suggest
                tags: getAutoTags(item),
                namePrefix: '',
                nameSuffix: ''
            });
            setModalOpen(true);
        } else {
            // Specific flow for reject (skip metadata)
            executeAction(item.id, 'reject');
        }
    };

    // Open Modal for Bulk Action
    const initiateBulkAction = (action: 'approve' | 'reject') => {
        const ids = Array.from(selectedIds);
        if (ids.length === 0) return;

        setTargetId(null); // Indicates Bulk
        setActionType(action);

        if (action === 'approve') {
            // For bulk, we can't auto-suggest per file easily in a single shared form.
            // We'll default to 'Documents' or maybe detect if mixed?
            // "Shared fields apply to all".

            // Heuristic: If all selected are images, default to Photos.
            const selectedItems = items.filter(i => selectedIds.has(i.id));
            const firstMime = selectedItems[0]?.mimeType || '';
            const allSameType = selectedItems.every(i => i.mimeType.split('/')[0] === firstMime.split('/')[0]);

            setMetadata({
                name: '',
                description: '',
                visibility: 'all',
                category: allSameType ? getAutoCategory(firstMime) : 'Documents',
                tags: `Drive Import, ${new Date().getFullYear()}`, // Generic bulk tags
                namePrefix: '',
                nameSuffix: ''
            });
            setModalOpen(true);
        } else {
            // Skip metadata for bulk reject, but maybe confirm?
            // For now, let's just confirm.
            if (confirm(`Are you sure you want to reject ${ids.length} items?`)) {
                executeBulkAction(ids, 'reject');
            }
        }
    };

    // Final Execution for Single
    const executeAction = async (id: string, action: 'approve' | 'reject', payloadMetadata?: any) => {
        setProcessingId(id);
        setModalOpen(false);

        try {
            const body: any = { id, action };
            if (action === 'approve' && payloadMetadata) {
                body.metadata = payloadMetadata;
            }

            const data = await apiClient('/api/admin/drive-queue', {
                method: 'POST',
                body: JSON.stringify(body)
            });

            toast.success(action === 'approve' ? 'File approved & published' : 'File rejected');
            setItems(prev => prev.filter(i => i.id !== id));
            if (selectedIds.has(id)) {
                const newSet = new Set(selectedIds);
                newSet.delete(id);
                setSelectedIds(newSet);
            }
        } catch (e: any) {
            toast.error(e.message || 'Action failed');
        } finally {
            setProcessingId(null);
        }
    };

    // Final Execution for Bulk
    const executeBulkAction = async (ids: string[], action: 'approve' | 'reject', payloadMetadata?: any) => {
        setProcessingId('bulk');
        setModalOpen(false);

        try {
            const body: any = { ids, action };
            if (action === 'approve' && payloadMetadata) {
                // Only include relevant fields for bulk
                body.metadata = {
                    description: payloadMetadata.description,
                    visibility: payloadMetadata.visibility,
                    category: payloadMetadata.category,
                    tags: payloadMetadata.tags, // Pass tags
                    namePrefix: payloadMetadata.namePrefix,
                    nameSuffix: payloadMetadata.nameSuffix
                };
            }

            const data = await apiClient('/api/admin/drive-queue', {
                method: 'POST',
                body: JSON.stringify(body)
            });

            toast.success(`Bulk Action: ${data.success} succeeded, ${data.failed} failed`);
            loadQueue();
        } catch (e: any) {
            toast.error(e.message || 'Bulk action failed');
        } finally {
            setProcessingId(null);
        }
    };

    const confirmModal = () => {
        if (!actionType) return;

        // Prepare visibility object based on simple select
        const finalMetadata = {
            ...metadata,
            visibility: metadata.visibility === 'all' ? { mode: 'all' } : { mode: 'internal', roles: ['admin', 'team'] }
        };

        if (targetId) {
            executeAction(targetId, actionType, finalMetadata);
        } else {
            executeBulkAction(Array.from(selectedIds), actionType, finalMetadata);
        }
    };

    // Checkbox Logic
    const toggleSelect = (id: string) => {
        const newSet = new Set(selectedIds);
        if (newSet.has(id)) newSet.delete(id);
        else newSet.add(id);
        setSelectedIds(newSet);
    };

    const toggleAll = () => {
        if (selectedIds.size === items.length) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(items.map(i => i.id)));
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h2 className="text-xl font-bold text-foreground mb-1">Detected from Drive</h2>
                    <p className="text-sm text-foreground/70">
                        Review and approve files uploaded to {folderInfo?.webViewLink ? (
                            <a
                                href={folderInfo.webViewLink}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-blue-400 hover:text-blue-300 inline-flex items-center gap-1 font-medium bg-blue-500/10 px-2 py-0.5 rounded transition-colors"
                            >
                                <FolderOpen size={12} />
                                {folderInfo.name}
                                <ExternalLink size={10} />
                            </a>
                        ) : (
                            <span className="font-mono text-xs bg-foreground/10 px-1 py-0.5 rounded">MediaHive/Incoming</span>
                        )}.
                    </p>
                </div>
                <button
                    onClick={handleScan}
                    disabled={scanning || !!processingId}
                    className="flex items-center justify-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-foreground rounded-xl font-bold shadow-lg shadow-indigo-500/20 transition-all"
                >
                    <RefreshCw size={20} className={scanning ? 'animate-spin' : ''} />
                    {scanning ? 'Scanning...' : 'Scan Now'}
                </button>
            </div>

            {loading ? (
                <div className="text-center py-12 text-foreground/70 animate-pulse">Loading queue...</div>
            ) : items.length === 0 ? (
                <div className="space-y-4">
                    <div className="flex flex-col items-center justify-center py-20 text-center border border-dashed border-[#ffffff1a] rounded-xl bg-slate-900/20">
                        <div className="w-16 h-16 bg-foreground/5 rounded-full flex items-center justify-center mb-4">
                            <HardDrive className="text-foreground/80" size={32} />
                        </div>
                        <h3 className="text-xl font-medium text-foreground/80 mb-2">Queue is empty</h3>
                        <p className="text-foreground/80 max-w-sm mx-auto">
                            Upload files to the Incoming folder and click Scan.
                        </p>
                    </div>

                    {scanLogs.length > 0 && (
                        <div className="mt-4 p-4 rounded-xl bg-black/40 border border-foreground/5">
                            <h4 className="text-xs font-mono text-foreground/70 mb-2 uppercase tracking-wide">Last Scan Debug Log</h4>
                            <div className="font-mono text-xs text-foreground/80 space-y-1 max-h-40 overflow-y-auto">
                                {scanLogs.map((log, i) => (
                                    <div key={i} className="whitespace-pre-wrap border-b border-foreground/5 pb-1 last:border-0">{log}</div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            ) : (
                <div className="space-y-4">
                    {/* Bulk Selection Toolbar */}
                    <div className="flex items-center justify-between bg-foreground/5 border border-foreground/10 rounded-xl px-4 py-3 sticky top-0 z-10 backdrop-blur-md">
                        <div className="flex items-center gap-3">
                            <Checkbox
                                id="select-all"
                                checked={items.length > 0 && selectedIds.size === items.length}
                                onCheckedChange={toggleAll}
                            />
                            <label htmlFor="select-all" className="text-sm font-medium text-foreground cursor-pointer select-none">
                                {selectedIds.size > 0 ? `${selectedIds.size} Selected` : 'Select All'}
                            </label>
                        </div>

                        {selectedIds.size > 0 && (
                            <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4 duration-200">
                                <Button
                                    variant="destructive"
                                    size="sm"
                                    onClick={() => initiateBulkAction('reject')}
                                    disabled={!!processingId}
                                >
                                    <X size={16} />
                                    Reject ({selectedIds.size})
                                </Button>
                                <Button
                                    variant="default" // Using default (primary) for Approve
                                    size="sm"
                                    className="bg-emerald-600 hover:bg-emerald-500 text-foreground border-0"
                                    onClick={() => initiateBulkAction('approve')}
                                    disabled={!!processingId}
                                >
                                    <Check size={16} />
                                    Approve ({selectedIds.size})
                                </Button>
                            </div>
                        )}
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        {items.map(item => (
                            <div
                                key={item.id}
                                className={`bg-[var(--bg-surface)] border rounded-xl p-4 flex flex-col md:flex-row items-start md:items-center gap-4 transition-all duration-200 ${selectedIds.has(item.id)
                                    ? 'border-indigo-500/50 bg-indigo-500/5 shadow-[0_0_15px_rgba(99,102,241,0.1)]'
                                    : 'border-[var(--border-subtle)] hover:border-[var(--border-default)]'
                                    }`}
                            >
                                <div className="mt-1 md:mt-0">
                                    <Checkbox
                                        checked={selectedIds.has(item.id)}
                                        onCheckedChange={() => toggleSelect(item.id)}
                                    />
                                </div>

                                {/* Thumbnail / Icon */}
                                <div className="w-12 h-12 rounded-lg bg-foreground/5 flex items-center justify-center shrink-0 overflow-hidden">
                                    {item.thumbnailLink ? (
                                        <img src={item.thumbnailLink} alt="" className="w-full h-full object-cover" />
                                    ) : (
                                        <HardDrive size={24} className="text-foreground/80" />
                                    )}
                                </div>

                                {/* Info */}
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                        <h4 className="font-medium text-foreground truncate text-lg">{item.name}</h4>
                                        <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-blue-500/10 text-blue-400 border border-blue-500/20 opacity-75">
                                            <HardDrive size={10} />
                                            Detected from Drive
                                        </span>
                                    </div>
                                    <div className="flex flex-wrap items-center gap-3 text-sm text-foreground/70 mt-1">
                                        <span className="bg-foreground/5 px-2 py-0.5 rounded text-xs uppercase tracking-wide">{item.mimeType.split('/').pop()}</span>
                                        <span>•</span>
                                        <span>{(item.size / 1024 / 1024).toFixed(2)} MB</span>
                                        <span>•</span>
                                        <span>{item.uploaded_by === 'Drive User' ? 'Uploaded via Drive' : item.uploaded_by}</span>
                                        <span>•</span>
                                        <span>
                                            {(() => {
                                                const date = parseFirestoreDate(item.detectedAt);
                                                return date ? `Detected ${formatDistanceToNow(date, { addSuffix: true })}` : '—';
                                            })()}
                                        </span>
                                    </div>
                                </div>

                                {/* Actions */}
                                <div className="flex items-center gap-2 w-full md:w-auto mt-2 md:mt-0">
                                    <a
                                        href={item.webViewLink}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="h-10 w-10 flex items-center justify-center rounded-lg hover:bg-foreground/5 text-foreground/70 transition-colors"
                                        title="Preview in Drive"
                                    >
                                        <ExternalLink size={20} />
                                    </a>

                                    <div className="h-6 w-px bg-foreground/10 mx-1 hidden md:block"></div>

                                    <button
                                        onClick={() => initiateSingleAction(item, 'reject')}
                                        title="Will not appear in Downloads"
                                        disabled={!!processingId || selectedIds.has(item.id)}
                                        className="flex-1 md:flex-none h-10 px-4 flex items-center justify-center gap-2 rounded-lg border border-red-500/20 text-red-400 hover:bg-red-500/10 transition-colors font-medium hover:scale-[1.02] active:scale-95 disabled:opacity-50 disabled:pointer-events-none"
                                    >
                                        <X size={18} />
                                        Reject
                                    </button>

                                    <button
                                        onClick={() => initiateSingleAction(item, 'approve')}
                                        disabled={!!processingId || selectedIds.has(item.id)}
                                        className="flex-1 md:flex-none h-10 px-6 flex items-center justify-center gap-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-foreground shadow-lg shadow-emerald-500/20 transition-all font-medium hover:scale-[1.02] active:scale-95 disabled:opacity-50 disabled:pointer-events-none"
                                    >
                                        {processingId === item.id ? (
                                            <div className="w-5 h-5 border-2 border-foreground/30 border-t-white rounded-full animate-spin" />
                                        ) : (
                                            <>
                                                <Check size={18} />
                                                Approve & Publish
                                            </>
                                        )}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Metadata / Approval Modal */}
            <Dialog open={modalOpen} onOpenChange={setModalOpen}>
                <DialogContent className="sm:max-w-xl">
                    <DialogHeader>
                        <DialogTitle>Approve & Publish</DialogTitle>
                        <DialogDescription>
                            {targetId
                                ? "Review updated details before publishing to Downloads."
                                : `Review details for ${selectedIds.size} selected items.`}
                        </DialogDescription>
                    </DialogHeader>

                    <div className="grid gap-4 py-4">
                        {/* Single Item: File Preview & Name Edit */}
                        {targetId && (
                            <>
                                <div className="grid gap-2">
                                    <Label htmlFor="name">Display Name</Label>
                                    <Input
                                        id="name"
                                        value={metadata.name}
                                        onChange={(e) => setMetadata({ ...metadata, name: e.target.value })}
                                    />
                                    <p className="text-xs text-muted-foreground">Original Drive filename: {items.find(i => i.id === targetId)?.name}</p>
                                </div>
                            </>
                        )}

                        {/* Bulk Item: Prefix/Suffix */}
                        {!targetId && (
                            <div className="grid grid-cols-2 gap-4">
                                <div className="grid gap-2">
                                    <Label htmlFor="prefix">Name Prefix (Optional)</Label>
                                    <Input
                                        id="prefix"
                                        placeholder="e.g. [Event A] "
                                        value={metadata.namePrefix}
                                        onChange={(e) => setMetadata({ ...metadata, namePrefix: e.target.value })}
                                    />
                                </div>
                                <div className="grid gap-2">
                                    <Label htmlFor="suffix">Name Suffix (Optional)</Label>
                                    <Input
                                        id="suffix"
                                        placeholder="e.g. - Final"
                                        value={metadata.nameSuffix}
                                        onChange={(e) => setMetadata({ ...metadata, nameSuffix: e.target.value })}
                                    />
                                </div>
                            </div>
                        )}

                        {/* Common Fields */}
                        <div className="grid grid-cols-2 gap-4">
                            <div className="grid gap-2">
                                <div className="flex items-center gap-2">
                                    <Label htmlFor="category">Category (Auto)</Label>
                                    <Popover>
                                        <PopoverTrigger asChild>
                                            <button type="button" className="text-muted-foreground hover:text-foreground transition-colors">
                                                <Info className="w-3.5 h-3.5" />
                                            </button>
                                        </PopoverTrigger>
                                        <PopoverContent className="w-80 p-0" align="start">
                                            <div className="p-3 border-b bg-muted/50 font-medium text-xs">Categorization Guide</div>
                                            <div className="max-h-60 overflow-y-auto p-2">
                                                {Object.entries(INVENTORY_GUIDE).map(([cat, desc]) => (
                                                    <div key={cat} className="p-2 hover:bg-muted rounded text-[10px]">
                                                        <div className="font-bold text-primary mb-0.5">{cat}</div>
                                                        <div className="text-muted-foreground line-clamp-2">{desc}</div>
                                                    </div>
                                                ))}
                                            </div>
                                        </PopoverContent>
                                    </Popover>
                                </div>
                                <Select
                                    value={metadata.category}
                                    onValueChange={(val) => setMetadata({ ...metadata, category: val })}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="Documents">Documents</SelectItem>
                                        <SelectItem value="Photos">Photos</SelectItem>
                                        <SelectItem value="Videos">Videos</SelectItem>
                                        <SelectItem value="Audio">Audio</SelectItem>
                                        <SelectItem value="Archives">Archives</SelectItem>
                                        <SelectItem value="Other">Other</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="visibility">Visibility</Label>
                                <Select
                                    value={metadata.visibility}
                                    onValueChange={(val) => setMetadata({ ...metadata, visibility: val })}
                                >
                                    <SelectTrigger>
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="all">Public (Visible to All)</SelectItem>
                                        <SelectItem value="internal">Internal (Admin & Team only)</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="tags">Tags (Auto-Generated)</Label>
                            <Input
                                id="tags"
                                placeholder="Year, Type, Source..."
                                value={metadata.tags}
                                onChange={(e) => setMetadata({ ...metadata, tags: e.target.value })}
                            />
                            <p className="text-[10px] text-muted-foreground">Comma-separated values.</p>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="description">Description (Optional)</Label>
                            <Textarea
                                id="description"
                                placeholder="Add context regarding this file..."
                                className="resize-none"
                                rows={3}
                                value={metadata.description}
                                onChange={(e) => setMetadata({ ...metadata, description: e.target.value })}
                            />
                        </div>
                    </div>

                    <DialogFooter>
                        <Button variant="outline" onClick={() => setModalOpen(false)}>Cancel</Button>
                        <Button onClick={confirmModal} className="bg-emerald-600 hover:bg-emerald-500 text-foreground">
                            Publish {targetId ? 'File' : 'Files'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { isFeatureEnabled } from '@/app/featureFlags';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

import { AlertCircle, UserPlus, Send, Trash2, Copy, Check } from 'lucide-react';
import { toast } from 'sonner';
import { apiClient } from '@/lib/apiClient';

interface InviteUserPanelProps {
  institution_id: string | number;
}

export const InviteUserPanel: React.FC<InviteUserPanelProps> = ({ institution_id }) => {
  const [isFeatureEnabledFlag, setIsFeatureEnabledFlag] = useState(false);
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<'admin' | 'manager' | 'team' | 'member'>('member');
  const [isLoading, setIsLoading] = useState(false);
  const [invites, setInvites] = useState<any[]>([]);
  const [loadingInvites, setLoadingInvites] = useState(true);
  const [copiedInviteId, setCopiedInviteId] = useState<string | null>(null);

  useEffect(() => {
    const checkFeature = async () => {
      const enabled = isFeatureEnabled('inviteAccessLayer');
      setIsFeatureEnabledFlag(enabled);
      if (enabled) {
        fetchInvites();
      }
    };

    checkFeature();
  }, []);

  const fetchInvites = async () => {
    setLoadingInvites(true);
    try {
      const data = await apiClient('/api/invites', {
        method: 'GET'
      });

      if (data.success) {
        setInvites(data.invites);
      } else {
        toast.error(data.error || 'Failed to fetch invites');
      }
    } catch (error) {
      console.error('Error fetching invites:', error);
      toast.error('Failed to fetch invites');
    } finally {
      setLoadingInvites(false);
    }
  };

  const handleCreateInvite = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!email) {
      toast.error('Please enter an email address');
      return;
    }

    setIsLoading(true);
    try {
      const result = await apiClient('/api/invites', {
        method: 'POST',
        body: JSON.stringify({ email, role }),
      });

      if (result.success) {
        toast.success(result.message);
        setEmail('');
        fetchInvites(); // Refresh the list
      } else {
        toast.error(result.error || 'Failed to create invite');
      }
    } catch (error) {
      console.error('Error creating invite:', error);
      toast.error('Failed to create invite');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteInvite = async (inviteId: string) => {
    if (!window.confirm('Are you sure you want to delete this invite? This action cannot be undone.')) {
      return;
    }

    try {
      const result = await apiClient(`/api/invites?id=${inviteId}`, {
        method: 'DELETE',
      });

      if (result.success) {
        toast.success('Invite deleted successfully');
        fetchInvites(); // Refresh the list
      } else {
        toast.error(result.error || 'Failed to delete invite');
      }
    } catch (error) {
      console.error('Error deleting invite:', error);
      toast.error('Failed to delete invite');
    }
  };

  const copyInviteLink = (inviteId: string) => {
    const inviteLink = `${window.location.origin}/invite/${inviteId}`;
    navigator.clipboard.writeText(inviteLink);
    setCopiedInviteId(inviteId);
    setTimeout(() => setCopiedInviteId(null), 2000);
    toast.success('Invite link copied to clipboard');
  };

  // If feature is disabled, don't render the panel
  if (!isFeatureEnabledFlag) {
    return null;
  }

  return (
    <Card className="bg-foreground/5 backdrop-blur-md border border-[#ffffff1a]">
      <CardHeader>
        <div className="flex items-center gap-2">
          <UserPlus className="w-5 h-5 text-blue-400" />
          <CardTitle className="text-foreground">Invite Users</CardTitle>
        </div>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleCreateInvite} className="mb-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="md:col-span-2">
              <Input
                type="email"
                placeholder="user@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="bg-black/20 border-foreground/20 text-foreground placeholder:text-foreground/60"
              />
            </div>
            <div>
              <Select value={role} onValueChange={(value: 'admin' | 'manager' | 'team' | 'member') => setRole(value)}>
                <SelectTrigger className="bg-black/20 border-foreground/20 text-foreground">
                  <SelectValue placeholder="Select role" />
                </SelectTrigger>
                <SelectContent className="bg-gray-800 border-foreground/20 text-foreground">
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="manager">Manager</SelectItem>
                  <SelectItem value="team">Team</SelectItem>
                  <SelectItem value="member">Member</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Button
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-500 text-foreground"
                disabled={isLoading}
              >
                {isLoading ? (
                  <>
                    <div className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"></div>
                    Creating...
                  </>
                ) : (
                  <>
                    <Send className="w-4 h-4 mr-2" />
                    Send Invite
                  </>
                )}
              </Button>
            </div>
          </div>
          <p className="text-sm text-foreground/60 mt-2">
            Invites expire in 7 days and can only be used once.
          </p>
        </form>

        <div className="border-t border-[#ffffff1a] pt-6">
          <h3 className="text-lg font-medium text-foreground mb-4">Pending Invites</h3>

          {loadingInvites ? (
            <div className="flex items-center justify-center h-20">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
            </div>
          ) : invites.length === 0 ? (
            <div className="text-center py-8">
              <div className="text-foreground/60">No pending invites</div>
            </div>
          ) : (
            <div className="space-y-3">
              {invites.map((invite) => (
                <div
                  key={invite.id}
                  className="flex items-center justify-between p-4 bg-gray-800/30 rounded-lg border border-gray-700"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-foreground">{invite.email}</span>
                      <span className={`px-2 py-1 rounded-full text-xs ${invite.role === 'admin'
                        ? 'bg-red-500/20 text-red-300'
                        : (invite.role === 'manager' || invite.role === 'member')
                          ? 'bg-blue-500/20 text-blue-300'
                          : 'bg-green-500/20 text-green-300'
                        }`}>
                        {invite.role}
                      </span>
                    </div>
                    <div className="text-xs text-foreground/60 mt-1">
                      Created: {new Date(invite.created_at).toLocaleString()} |
                      Expires: {new Date(invite.expiresAt).toLocaleString()}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => copyInviteLink(invite.id)}
                      className="bg-gray-700/50 border-gray-600 text-foreground hover:bg-gray-600/50"
                    >
                      {copiedInviteId === invite.id ? (
                        <>
                          <Check className="w-4 h-4 mr-2" />
                          Copied
                        </>
                      ) : (
                        <>
                          <Copy className="w-4 h-4 mr-2" />
                          Copy Link
                        </>
                      )}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleDeleteInvite(invite.id)}
                      className="bg-red-900/30 border-red-800 text-red-300 hover:bg-red-800/30"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { AutomationRule, RuleAction } from '@/types/automation-rules';
import { Loader2, Save, Bell, AlertTriangle, Clock, Play, ChevronDown, Check } from 'lucide-react';
import { apiClient } from '@/lib/apiClient';
import { DropdownSelector } from '@/components/ui/selectors/DropdownSelector';

// Configuration Mapping
const POLICY_CONFIG = [
    {
        key: 'task_due_soon',
        title: 'Task Due Reminder',
        description: 'Notify users before a task is due.',
        icon: Clock,
        field: 'hoursUntilDue',
        operator: 'lte',
