];

export default function NotificationPolicyView() {
    const [rules, setRules] = useState<AutomationRule[]>([]);
    const [systemRules, setSystemRules] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [processing, setProcessing] = useState<string | null>(null);

    const [scopeType, setScopeType] = useState<'global' | 'institution' | 'unit'>('global');
    const [scopeId, setScopeId] = useState('global');

    const fetchRules = async () => {
        setLoading(true);
        try {
            const json = await apiClient('/api/admin/automation-rules');
            setRules(json.custom);
            setSystemRules(json.system);
        } catch (e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchRules();
    }, []);

    const getActiveRule = (configKey: string) => {
        const matches = rules.filter(r =>
            r.ruleKey === configKey &&
            r.scopeType === scopeType &&
            r.scopeId === scopeId &&
            r.enabled
        );
        matches.sort((a, b) => b.version - a.version);
        return matches[0];
    };

    const handleSavePolicy = async (config: any, enabled: boolean, value: number) => {
        setProcessing(config.key);
        try {
            const action = enabled ? config.defaultAction : 'suppress';

            const payload = {
                ruleKey: config.key,
                scopeType,
                scopeId,
                eventType: config.key,
                conditions: [
                    {
                        field: config.field,
                        operator: config.operator,
                        value: value
                    }
                ],
                action,
                priority: 10,
            };

            if (config.operator === 'lte') {
                payload.conditions.push({ field: config.field, operator: 'gt', value: 0 });
            }

            const createRes = await apiClient('/api/admin/automation-rules', {
                method: 'POST',
                body: JSON.stringify(payload)
            });
            
            const { rule } = createRes;

            await apiClient('/api/admin/automation-rules', {
                method: 'PATCH',
                body: JSON.stringify({ id: rule.id, command: 'activate' })
            });

            await fetchRules();
        } catch (e) {
            alert('Failed to update policy');
        } finally {
            setProcessing(null);
        }
    };

    return (
        <div className="min-h-screen bg-background text-foreground animate-in fade-in duration-500">
            <div className="max-w-7xl mx-auto px-6 py-12 space-y-12">

                {/* Header Section */}
                <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-x-8 gap-y-6">
                    <div className="space-y-4">
                        <h1 className="text-4xl font-extrabold tracking-tight text-foreground drop-shadow-sm">Notification Policies</h1>
                        <p className="text-muted text-lg font-light leading-relaxed max-w-2xl">
                            Configure how and when the system alerts your team. Manage reminders, overdue warnings, and automatic escalations.
                        </p>
                    </div>

                    {/* Modern Scope Selector - Glassy & Integrated */}
                    <div className="flex flex-col gap-2 min-w-[280px]">
                        <span className="text-[10px] font-bold uppercase tracking-widest text-indigo-500/80 ml-1">Configuration Scope</span>
                        <div className="relative group">
                            <div className="absolute inset-0 bg-indigo-500/20 blur-md rounded-xl group-hover:bg-indigo-500/30 transition-all duration-500" />
                            <div className="relative flex items-center gap-2 bg-surface/80 p-1.5 rounded-xl border border-soft backdrop-blur-xl shadow-lg">
                                <div className="relative flex-1">
                                    <DropdownSelector 
                                        label="Scope Type"
                                        value={scopeType}
                                        onChange={(val) => {
                                            setScopeType(val as any);
                                            setScopeId(val === 'global' ? 'global' : '');
                                        }}
                                        options={[
                                            { id: 'global', label: 'Global Policy' },
                                            { id: 'institution', label: 'Institution Policy' },
                                            { id: 'unit', label: 'Unit Policy' }
                                        ]}
                                    />
                                </div>

                                {scopeType !== 'global' && (
                                    <input
                                        className="bg-muted/10 text-sm text-foreground px-3 py-2.5 rounded-lg border border-transparent focus:border-indigo-500/50 focus:bg-indigo-500/10 outline-none transition-all w-32 placeholder:text-muted font-mono"
                                        placeholder="ID..."
                                        value={scopeId}
                                        onChange={(e) => setScopeId(e.target.value)}
                                        autoFocus
                                    />
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {loading ? (
                    <div className="flex flex-col items-center justify-center p-32 space-y-6">
                        <div className="relative">
                            <div className="absolute inset-0 bg-indigo-500/50 blur-xl animate-pulse rounded-full" />
                            <Loader2 className="w-12 h-12 text-foreground relative animate-spin" />
                        </div>
                        <p className="text-muted font-light tracking-wide animate-pulse">Synchronizing Policies...</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {POLICY_CONFIG.map(config => {
                            const activeRule = getActiveRule(config.key);
                            const isEnabled = activeRule ? activeRule.action !== 'suppress' : true;
                            const val = activeRule?.conditions?.find(c => c.field === config.field)?.value ?? config.defaultVal;

                            return (
                                <PolicyCard
                                    key={config.key}
                                    config={config}
                                    currentValue={val}
                                    isEnabled={isEnabled}
                                    onSave={handleSavePolicy}
                                    isProcessing={processing === config.key}
                                />
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
}

function PolicyCard({ config, currentValue, isEnabled, onSave, isProcessing }: any) {
    const [enabled, setEnabled] = useState(isEnabled);
    const [val, setVal] = useState(currentValue);
    const Icon = config.icon;

    useEffect(() => {
        setEnabled(isEnabled);
        setVal(currentValue);
    }, [isEnabled, currentValue]);

    const hasChanges = enabled !== isEnabled || val !== currentValue;

    return (
        <div className={`
            group relative flex flex-col p-6 rounded-2xl border transition-all duration-500 ease-out
            overflow-hidden isolate
            ${enabled
                ? 'bg-surface border-soft shadow-xl shadow-black/5'
                : 'bg-muted/5 border-transparent shadow-none opacity-80'
            }
        `}>
            {/* Glow Effects */}
            {enabled && (
                <>
                    <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />
                    <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 blur-[60px] rounded-full pointer-events-none" />
                </>
            )}

            {/* Card Header & Toggle */}
            <div className="relative flex justify-between items-start mb-8 z-10">
                <div className="flex gap-4 pr-4">
                    <div className={`
                        p-3.5 rounded-2xl transition-all duration-300
                        ${enabled
                            ? `bg-gradient-to-br ${config.bg} to-transparent text-foreground ring-1 ring-inset ring-soft shadow-md`
                            : 'bg-muted/10 text-muted saturate-0 scale-95'
                        }
                    `}>
                        <Icon size={24} className={enabled ? 'stroke-indigo-500 drop-shadow-sm' : ''} />
                    </div>
                    <div>
                        <h3 className={`font-semibold text-lg leading-tight transition-colors ${enabled ? 'text-foreground' : 'text-muted'}`}>
                            {config.title}
                        </h3>
                        <p className="text-sm text-muted mt-1.5 font-light leading-relaxed line-clamp-2">
                            {config.description}
                        </p>
                    </div>
                </div>

                {/* Redesigned Toggle */}
                <button
                    onClick={() => setEnabled(!enabled)}
                    className={`
                        relative w-[60px] h-[32px] rounded-full transition-all duration-300 ease-in-out shrink-0 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-background focus:ring-indigo-500/50
                        ${enabled
                            ? 'bg-indigo-600 shadow-md'
                            : 'bg-muted hover:bg-muted/80'
                        }
                    `}
                >
                    <span className={`
                        absolute top-[3px] w-[26px] h-[26px] bg-white rounded-full shadow-md transition-all duration-300 ease-in-out
                        flex items-center justify-center
                        ${enabled ? 'left-[31px]' : 'left-[3px]'}
                    `}>
                        {enabled && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse" />}
                    </span>
                </button>
            </div>

            {/* Input Section */}
            <div className="relative z-10 space-y-6 mt-auto">
                <div className={`
                    flex items-center justify-between py-2 px-1 border-b border-soft transition-all duration-300
                    ${!enabled ? 'opacity-30 grayscale pointer-events-none' : 'opacity-100'}
                `}>
                    <span className="text-sm text-muted font-medium">Alert Threshold</span>
                    <div className="flex items-baseline gap-2 group/input">
                        <input
                            type="number"
                            className="w-20 bg-transparent text-right text-2xl font-bold text-foreground outline-none placeholder:text-muted font-mono transition-colors group-hover/input:text-indigo-500"
                            value={val}
                            onChange={(e) => setVal(Number(e.target.value))}
                        />
                        <span className="text-xs font-bold text-muted-foreground uppercase tracking-widest">{config.unit}</span>
                    </div>
                </div>

                {/* Actions Wrapper */}
                <div className="h-10 relative">
                    {/* Save Button */}
                    <button
                        onClick={() => onSave(config, enabled, val)}
                        disabled={!hasChanges || isProcessing}
                        className={`
                            absolute inset-0 w-full h-10 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all duration-300 transform
                            ${hasChanges
                                ? 'bg-indigo-500 hover:bg-indigo-400 text-foreground shadow-lg shadow-indigo-500/25 translate-y-0 opacity-100 z-10'
                                : 'translate-y-2 opacity-0 -z-10 pointer-events-none'
                            }
                        `}
                    >
                        {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> :
                            <><Save className="w-4 h-4" /> Save Changes</>}
                    </button>

                    {/* Faint Synced State - Replaces Button when no changes */}
                    {!hasChanges && !isProcessing && (
                        <div className="absolute inset-0 flex items-center justify-center gap-2 text-foreground/40/40 select-none transition-all duration-500">
                            <Check className="w-3.5 h-3.5" />
                            <span className="text-xs font-semibold tracking-wider uppercase">Synced</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Label } from '@/components/ui/label';
import { apiClient } from '@/lib/apiClient';
import { toast } from 'sonner';
import { Megaphone, AlertTriangle, Info, CheckCircle } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';

// Minimal interface for list items
interface SystemUpdate {
    id: string;
    title: string;
    body: string;
    severity: 'info' | 'important' | 'critical';
    created_at: any;
    created_by?: { name: string };
}

export const SystemUpdatesView = () => {
    const [title, setTitle] = useState('');
    const [body, setBody] = useState('');
    const [severity, setSeverity] = useState<'info' | 'important' | 'critical'>('info');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [history, setHistory] = useState<SystemUpdate[]>([]);
    const [loadingHistory, setLoadingHistory] = useState(true);

    // Fetch History (Mock/Direct for now? Or Admin API needs GET?)
    // Required: "Read-only list of published updates"
    // Valid approach: Add GET to /api/admin/system-updates
    useEffect(() => {
        const fetchHistory = async () => {
            try {
                const data = await apiClient('/api/admin/system-updates');
                if (data.updates) setHistory(data.updates);
            } catch (e) {
                console.error("Failed to load history", e);
            } finally {
                setLoadingHistory(false);
            }
        };
        fetchHistory();
    }, []);

    const handlePublish = async () => {
        if (!title.trim() || !body.trim()) {
            toast.error('Title and Body required');
            return;
        }

        setIsSubmitting(true);
        try {
            await apiClient('/api/admin/system-updates', {
                method: 'POST',
                body: JSON.stringify({ title, body, severity })
            });

            toast.success('System Update Published!');

            // Reset form
            setTitle('');
            setBody('');
            setSeverity('info');

            // Refresh list
            const data = await apiClient('/api/admin/system-updates');
            setHistory(data.updates || []);

        } catch (error) {
            console.error('Publish failed', error);
            toast.error('Failed to publish update');
        } finally {
            setIsSubmitting(false);
        }
    };

    const getSeverityColor = (sev: string) => {
        switch (sev) {
            case 'critical': return 'text-red-400 bg-red-500/10 border-red-500/20';
            case 'important': return 'text-orange-400 bg-orange-500/10 border-orange-500/20';
            default: return 'text-blue-400 bg-blue-500/10 border-blue-500/20';
        }
    };

    return (
        <div className="space-y-8 max-w-5xl mx-auto p-6">
            <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-indigo-500/20 rounded-xl">
                    <Megaphone className="w-8 h-8 text-indigo-400" />
                </div>
                <div>
                    <h1 className="text-2xl font-bold text-foreground">System Updates Manager</h1>
                    <p className="text-muted-foreground">Broadcast announcements to the entire organization.</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Compose Form */}
                <div className="lg:col-span-1 space-y-6">
                    <Card className="bg-card border-border shadow-sm">
                        <CardHeader>
                            <CardTitle className="text-lg">Compose Update</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="space-y-2">
                                <Label>Title</Label>
                                <Input
                                    value={title}
                                    onChange={e => setTitle(e.target.value)}
                                    placeholder="e.g. New Feature: Inventory Tracking"
                                    className="bg-background border-input"
                                />
                            </div>

                            <div className="space-y-2">
                                <Label>Severity</Label>
                                <Select value={severity} onValueChange={(v: any) => setSeverity(v)}>
                                    <SelectTrigger className="bg-background border-input">
                                        <SelectValue />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="info">Info (Blue)</SelectItem>
                                        <SelectItem value="important">Important (Orange)</SelectItem>
                                        <SelectItem value="critical">Critical (Red)</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>

                            <div className="space-y-2">
                                <Label>Message Body</Label>
                                <Textarea
                                    value={body}
                                    onChange={e => setBody(e.target.value)}
                                    placeholder="Details about the update..."
                                    className="bg-background border-input min-h-[150px]"
                                />
                            </div>

                            <Button
                                onClick={handlePublish}
                                disabled={isSubmitting}
                                className="w-full bg-indigo-600 hover:bg-indigo-700 text-foreground"
                            >
                                {isSubmitting ? 'Publishing...' : 'Publish Update'}
                            </Button>

                            <p className="text-xs text-muted-foreground text-center">
                                This will notify all opted-in users immediately.
                            </p>
                        </CardContent>
                    </Card>
                </div>

                {/* History List */}
                <div className="lg:col-span-2">
                    <Card className="bg-card border-border shadow-sm h-full">
                        <CardHeader>
                            <CardTitle className="text-lg flex justify-between items-center">
                                Published History
                                <span className="text-sm font-normal text-muted-foreground">
                                    {history.length} updates
                                </span>
                            </CardTitle>
                        </CardHeader>
                        <CardContent>
                            <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2">
                                {loadingHistory ? (
                                    <p className="text-muted-foreground text-center py-8">Loading history...</p>
                                ) : history.length === 0 ? (
                                    <p className="text-muted-foreground text-center py-8">No updates published yet.</p>
                                ) : (
                                    history.map(update => (
                                        <div key={update.id} className="p-4 rounded-lg bg-foreground/[0.02] border border-border flex flex-col gap-2">
                                            <div className="flex justify-between items-start">
                                                <div className="flex items-center gap-2">
                                                    <span className={`px-2 py-0.5 rounded text-[10px] uppercase font-bold border ${getSeverityColor(update.severity)}`}>
                                                        {update.severity}
                                                    </span>
                                                    <h3 className="font-semibold text-foreground">{update.title}</h3>
                                                </div>
                                                <span className="text-xs text-muted-foreground">
                                                    {update.created_at ? formatDistanceToNow(new Date(update.created_at), { addSuffix: true }) : 'Unknown'}
                                                </span>
                                            </div>
                                            <p className="text-sm text-muted-foreground whitespace-pre-wrap pl-1">{update.body}</p>
                                            <div className="flex justify-end items-center gap-2 mt-2">
                                                <span className="text-[10px] text-muted-foreground/70">
                                                    By {update.created_by?.name || 'Admin'}
                                                </span>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </div>
    );
};

'use client';

import { useState, useEffect } from 'react';
import { apiClient } from '@/lib/apiClient';
import { updateRole } from '@/services/roleService';
import { DropdownSelector } from '@/components/ui/selectors/DropdownSelector';
import { Shield, User as UserIcon, ShieldAlert } from 'lucide-react';

interface User {
  uid: string;
  email: string;
  role: string;
  displayName?: string;
}

const UserRoleManager = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUserRole, setCurrentUserRole] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [updating, setUpdating] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const loadUsers = async () => {
      try {
        // Fetch all users via API route
        const usersData = await apiClient('/api/users', {
          method: 'GET',
        });
        
        setUsers(usersData);
      } catch (error) {
        console.error('Error loading users:', error);
      } finally {
        setLoading(false);
      }
    };

    // Load current user's role
    const loadCurrentUserRole = async () => {
      try {
        const userData = await apiClient('/api/users/me', {
          method: 'GET',
        });
        setCurrentUserRole(userData?.role || null);
      } catch (error) {
        console.error('Error loading current user role:', error);
      }
    };

    loadUsers();
    loadCurrentUserRole();
  }, []);

  const handleRoleChange = async (userId: string, newRole: string) => {
    if (currentUserRole !== 'admin') {
      alert('Only admins can change roles');
      return;
    }

    setUpdating(prev => ({ ...prev, [userId]: true }));

    try {
      // Use Cloud Function to update role securely
      await updateRole(userId, newRole);

      // Update local state
      setUsers(prev => prev.map(user => 
        user.uid === userId ? { ...user, role: newRole } : user
      ));

      alert(`Role updated to ${newRole} for user ${userId}`);
    } catch (error) {
      console.error('Error updating role:', error);
      alert('Failed to update role');
    } finally {
      setUpdating(prev => ({ ...prev, [userId]: false }));
    }
  };

  if (loading) {
    return <div>Loading users...</div>;
  }

  if (currentUserRole !== 'admin') {
    return <div>Only admins can manage user roles</div>;
  }

  return (
    <div className="p-6">
      <h2 className="text-xl font-bold mb-4">User Role Management</h2>
      <div className="overflow-x-auto">
        <table className="min-w-full bg-white">
          <thead>
            <tr>
              <th className="py-2 px-4 border-b">User ID</th>
              <th className="py-2 px-4 border-b">Email</th>
              <th className="py-2 px-4 border-b">Display Name</th>
              <th className="py-2 px-4 border-b">Current Role</th>
              <th className="py-2 px-4 border-b">Change Role</th>
            </tr>
          </thead>
          <tbody>
            {users.map(user => (
              <tr key={user.uid}>
                <td className="py-2 px-4 border-b text-sm">{user.uid}</td>
                <td className="py-2 px-4 border-b">{user.email}</td>
                <td className="py-2 px-4 border-b">{user.displayName || 'N/A'}</td>
                <td className="py-2 px-4 border-b">
                  <span className={`px-2 py-1 rounded text-xs ${
                    user.role === 'admin' ? 'bg-red-200 text-red-800' :
                    ['manager', 'team', 'member'].includes(user.role) ? 'bg-blue-200 text-blue-800' :
                    'bg-gray-200 text-foreground/20'
                  }`}>
                    {user.role}
                  </span>
                </td>
                 <td className="py-2 px-4 border-b">
                  <DropdownSelector 
                    label=""
                    value={user.role}
                    onChange={(val) => handleRoleChange(user.uid, val)}
                    disabled={updating[user.uid]}
                    options={[
                      { id: 'admin', label: 'Admin', icon: <ShieldAlert size={14} className="text-red-400" /> },
                      { id: 'manager', label: 'Manager', icon: <Shield size={14} /> },
                      { id: 'team', label: 'Team', icon: <Shield size={14} /> },
                      { id: 'member', label: 'Member', icon: <UserIcon size={14} /> },
                    ]}
                  />
                  {updating[user.uid] && <span className="ml-2 text-xs">Updating...</span>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default UserRoleManager;

"use client";

import React, { useEffect, useState } from 'react';
