                    </div>
                </div>

                <div className="text-xs text-foreground/50 italic max-w-xs md:text-right border-l md:border-l-0 md:border-r border-[#ffffff1a] pl-4 md:pr-4 md:pl-0">
                    "{automationPreview.message}"
