import { X, TrendingUp, TrendingDown, Minus, Activity, Users, AlertTriangle, MessageSquare, Shield } from 'lucide-react';
import { SafeAvatar } from '@/components/ui/SafeAvatar';
import { apiClient } from '@/lib/apiClient';
